"""
This file contains all the classes present in the autosar schema.
It provides methods to access/modify/create elements from the autosar
arxml file.
"""

from lxml import etree
from enum import Enum, unique
import logging, os.path, sys
from xat_ecu.legacy.tools.arxml_tool import datatype_utils

# dict supposed to be used internally by the module to store the path and its corresponding autosar node
__pathsToNodeDict__ = {}
# root autosar node
__autosarNode__ = None

# namespace for autosar arxml files
__autosarNsMap__ = {None: "http://autosar.org/schema/r4.0", 'xsi': "http://www.w3.org/2001/XMLSchema-instance"}
__rootSchemaAttr__ = {'{http://www.w3.org/2001/XMLSchema-instance}schemaLocation': 'http://autosar.org/schema/r4.0 AUTOSAR_00049.xsd'}


def read(files=[]):
    """
    Reads the given files and returns the AUTOSAR root.

    :param files: List of arxml file.
    :return: The merged AUTOSAR root node(the current file + all other
             files already loaded) and the status. May return None
             if the given file is not AUTOSAR compliant file or if
             it does not have any AR-PACKAGES.
    """
    global __autosarNode__
    status = False

    if isinstance(files, list) is False:
        raise InvalidInputException('argument files should be list of file')

    for file in files:
        tree = etree.parse(file, etree.XMLParser(remove_blank_text=True))
        if tree is not None and tree.getroot() is not None:
            if etree.QName(tree.getroot()).localname == 'AUTOSAR':
                asrRootNode = AUTOSAR()._build(tree.getroot())
                if len(asrRootNode.get_arPackages()) > 0:
                    logging.info('{} read successfull.'.format(file))
                    status = True
                    if __autosarNode__ is None:
                        __autosarNode__ = asrRootNode
                    else:
                        for arpackage in asrRootNode.get_arPackages():
                            __autosarNode__.get_arPackages().add(arpackage)

                    __autosarNode__._mergedFromNodes[file] = asrRootNode
                else:
                    logging.warning('{} read but not ar-packages found. Hence ingoring the file contents.'.format(file))
            else:
                logging.error('{} read Failed. AUTOSAR root node not found in the arxml file.'.format(file))
        else:
            logging.error('{} read Failed. Seems like the file is not a valid arxml file.'.format(file))
    # Resolve the references of all the nodes.
    for node in __pathsToNodeDict__.values():
        node._resolve_references()
    return __autosarNode__, status


def new_file(path, defaultArPackage='RootPackage', overWrite=False):
    """
    Creates a new file and return the ar-package node.
    Throws exception if the file already exist when the
    argument overWrite is not provided or is False.

    :param path: The absolute path where the file needs to be created.
    :param defaultArPackage: The name of the default ar-package.
    :param overWrite: Pass True if the new file should overwrite if
                      a file is already present in the given path.
    :return: The Ar-package.
    """
    global __autosarNode__
    if os.path.isfile(path) and overWrite is False:
        raise FileExistsError('File {} already exists. If it needs overwriting, then please set True for argument overWrite.'.format(path))

    # Create file
    root = etree.Element('AUTOSAR', nsmap=__autosarNsMap__, attrib=__rootSchemaAttr__)
    arpackages = etree.SubElement(root, 'AR-PACKAGES')
    arpackage = etree.SubElement(arpackages, 'AR-PACKAGE')
    shortName = etree.SubElement(arpackage, 'SHORT-NAME')
    shortName.text = defaultArPackage
    etree.SubElement(arpackage, 'ELEMENTS')
    et = etree.ElementTree(root)
    et.write(path, pretty_print=True, xml_declaration=True,   encoding="utf-8")
    logging.info('File created successfully at {}.'.format(path))

    # Now create the Autosar object
    asrRootNode = AUTOSAR()._build(root)
    createdArPackage = next(iter(asrRootNode.get_arPackages()))
    if __autosarNode__ is None:
        __autosarNode__ = asrRootNode
    else:
        __autosarNode__.get_arPackages().add(createdArPackage)

    __autosarNode__._mergedFromNodes[path] = asrRootNode
    return createdArPackage


def get_root():
    """
    Returns the root AUTOSAR node.
    """
    global __autosarNode__
    return __autosarNode__


def reinit():
    """
    Re-initialize the package. All the loaded model entities(from input
    /newly created files, modified/new model objects) will be removed.
    """
    global __autosarNode__
    __autosarNode__ = None # Reinit the root node.
    __pathsToNodeDict__.clear() # Clearing the cache


def get_node(path):
    """
    Returns the autosar node for the corresponding path.

    :param path: The fully qualified autosar path for eg: /Autosar/Swc1/port1.
    :return: The node corresponding to the path or None if the node for path is not available.
    """
    if path in __pathsToNodeDict__:
        return __pathsToNodeDict__[path]
    else:
        return None


def save(files=[]):
    """
    Saves the changes in AUTOSAR model.
    :param files: The files to be saved. If not provided
                  all the input files will be saved.
    """
    global __autosarNode__
    __autosarNode__.save(files)


def saveAs(file, overWrite=False):
    """
    Saves the changes in AUTOSAR model(contents from input files, created files,
    new model entities, modified model entities) to a single file. This package
    do not validate if there exists AR-PACKAGE was duplicate names. It is the
    responsibility of the user to make sure this.

    :param file: The file where the complete AUTOSAR model will be saved.
    :param overWrite: Pass True if the new file should overwrite if
                      a file is already present in the given path.
    """
    global __autosarNode__
    __autosarNode__.saveAs(file, overWrite=overWrite)


def __str_to_class__(str):
    """
    To be used internally by the package.
    """
    return getattr(sys.modules[__name__], str)


class AutosarNode:
    """
    Base class for all autosar nodes
    """
    def __init__(self):
        """
        Constructor for any Autosar node.
        """
        self._parent = None
        self._node = None
        self.name = None
        self.path = ''
        self.referenced_by = set()


    def _build(self, parent, node):
        """
        Build the node
        :param parent: The parent under which new model element needs to be created.
        :param node: The xml node for which the autosar node needs to be created.
        """
        self._parent = parent
        self._node = node
        shortNameNode = node.find('{*}SHORT-NAME')
        if shortNameNode is not None:
            self.name = shortNameNode.text

        self._build_path()
        return self


    def _build_path(self):
        """
        Builds the path for the current node.
        """
        # First remove the current node from dict
        if self.path in __pathsToNodeDict__:
            del __pathsToNodeDict__[self.path]

        # Then, build the node and add to dict.
        if self._parent is not None:
            if self.name is not None:
                self.path = self._parent.path + '/' + self.name
            else:
                self.path = self._parent.path + '[' + self.__class__.__name__ + ']'
            __pathsToNodeDict__[self.path] = self
        else:
            self.path = ''


    @staticmethod
    def _add_or_get_xml_node(parentNode, tagName, dest = None, createNode = True, forceCreate = False):
        """
        Get or create a new xml node with the tagName.
        :param tagName: The tag name which needs to be created.
        :param dest: The destination object if its a reference value.
        :param createNode: Create node is it doesn't exist
        """
        xmlNode = parentNode.find('{*}' + tagName)
        if xmlNode is None and createNode:
            xmlNode = etree.SubElement(parentNode, tagName, attrib = {'DEST' : dest.tag} if dest is not None else None)
        elif forceCreate:
            xmlNode = etree.SubElement(parentNode, tagName, attrib = {'DEST' : dest.tag} if dest is not None else None)
        return xmlNode


    @staticmethod
    def _get_node_text(node, tagName):
        value = node.find('{*}' + tagName)
        if value is not None:
            return value.text
        return None


    def get_parent(self):
        return self._parent


    def get_children(self):
        """
        Get all the child nodes of the current node. This method is supposed to be overridden by all sub-classes.
        """
        return []


    def get_property_values(self):
        """
        Get the property and its value for a corresponding node as dict. This method is supposed to be overridden by all sub-classes.
        """
        return {}


    def _resolve_references(self):
        """
        This method is supposed to be overridden by all sub-classes.
        """
        pass


    def _add_mandatory_attr(self, node, name=None):
        """
        This method is supposed to be overridden by all sub-classes.
        """
        pass


    def _update_path(self):
        """
        This method is supposed to be overridden by all sub-classes.
        """
        pass


    def __repr__(self):
        return (self.__class__.__name__ + '(' + self.path + ')')


    def __hash__(self):
        return hash(self.path)


    def __eq__(self, other):
        return (self.__class__ == other.__class__ and self.path == other.path)


class ARObject(AutosarNode):
    """
    Implicit base class of all classes in meta-model.
    """
    def __init__(self):
        super().__init__()
        self.__checksum = None
        self.__timestamp = None

    def _build(self, parent, node):
        super()._build(parent, node)
        checksum_value = AutosarNode._get_node_text(node,'S')
        if checksum_value is not None:
            self.__checksum = datatype_utils.get_string_value(checksum_value)

        timestamp_value = AutosarNode._get_node_text(node,'T')
        if timestamp_value is not None:
            self.__timestamp = datatype_utils.get_string_value(timestamp_value)

        return self

    def get_checksum(self):
        return self.__checksum

    def set_checksum(self, value):
        self.__checksum = value
        checksum_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'S')
        checksum_xml_node.text = str(value) if value is not None else ''

    def get_timestamp(self):
        return self.__timestamp

    def set_timestamp(self, value):
        self.__timestamp = value
        timestamp_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'T')
        timestamp_xml_node.text = str(value) if value is not None else ''

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['Checksum'] = self.__checksum
        property_values['Timestamp'] = self.__timestamp
        return property_values

    def _update_path(self):
        """
        Updates the path of the ARObject and its children.
        """
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

class Referrable(ARObject):
    """
    Instances of this class can be referred to by their identifier (while adhering to namespace borders).
    """
    def __init__(self):
        super().__init__()
        self.__shortName = None
        self.__shortNameFragments = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        shortName_value = AutosarNode._get_node_text(node,'SHORT-NAME')
        if shortName_value is not None:
            self.__shortName = datatype_utils.get_string_value(shortName_value)

        shortNameFragments_nodes = self._node.findall('{*}SHORT-NAME-FRAGMENTS/*')
        for shortNameFragments_node in shortNameFragments_nodes:
            self.__shortNameFragments.add(ShortNameFragment()._build(self, shortNameFragments_node))

        return self

    def get_shortName(self):
        return self.__shortName

    def set_shortName(self, value):
        self.__shortName = value
        shortName_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'SHORT-NAME')
        shortName_xml_node.text = str(value) if value is not None else ''

    def get_shortNameFragments(self):
        return self.__shortNameFragments

    def add_shortNameFragment(self, value):
        """
        Adds a single value to the shortNameFragments
        """
        if value is not None:
            if any(v.name == value.name for v in self.__shortNameFragments):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, ShortNameFragment) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ShortNameFragment or its sub-classes'.format(value))
            self.__shortNameFragments.add(value)
            shortNameFragments_values = AutosarNode._add_or_get_xml_node(self._node, 'SHORT-NAME-FRAGMENTS')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            shortNameFragments_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_shortNameFragments(self, values):
        """
        Adds a list of ref value to the shortNameFragments
        """
        for value in values:
            self.add_shortNameFragment(value)

    def remove_shortNameFragment(self, value):
        """
        Removes a single value from shortNameFragments
        """
        if value is not None:
            self.__shortNameFragments.remove(value)
            shortNameFragments_values = AutosarNode._add_or_get_xml_node(self._node, 'SHORT-NAME-FRAGMENTS', createNode = False)
            shortNameFragments_values.remove(value._node)
            value._parent = None #No parent
            value._update_path() #resets the path

    def remove_shortNameFragments(self, values):
        """
        Removes a list of value from shortNameFragments
        """
        for value in values:
            self.remove_shortNameFragment(value)

    def new_ShortNameFragment(self, name=None):
        """
        Creates a new ShortNameFragment under the Referrable.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        ShortNameFragment_obj = ShortNameFragment()
        if isinstance(ShortNameFragment_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('SHORT-NAME-FRAGMENT')
        ShortNameFragment_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        ShortNameFragment_obj.name = name
        ShortNameFragment_obj._node = xmlNode
        self.add_shortNameFragment(ShortNameFragment_obj)
        return ShortNameFragment_obj

    def _add_mandatory_attr(self, node, name = None):
        super()._add_mandatory_attr(node, name)
        shortName_node = etree.SubElement(node, 'SHORT-NAME')
        if name is not None:
            shortName_node.text = name

    def get_children(self):
        children = super().get_children()
        children.extend(self.__shortNameFragments)
        return children

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['ShortName'] = self.__shortName
        return property_values

    def _update_path(self):
        """
        Updates the path of the Referrable and its children.
        """
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

class MultilanguageReferrable(Referrable):
    """
    Instances of this class can be referred to by their identifier (while adhering to namespace borders). They also may have a longName. But they are not considered to contribute substantially to the overall structure of an AUTOSAR description. In particular it does not contain other Referrables.
    """
    def __init__(self):
        super().__init__()
        self.__longName = None

    def _build(self, parent, node):
        super()._build(parent, node)
        longName_node = self._node.find('{*}LONG-NAME')
        if longName_node is not None:
            self.__longName = MultilanguageLongName()._build(self, longName_node)

        return self

    def get_longName(self):
        return self.__longName

    def set_longName(self, value):
        """
        Adds a single value to the longName
        """
        if value is not None:
            if isinstance(value, MultilanguageLongName) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of MultilanguageLongName or its sub-classes'.format(value))
            if self.__longName is not None:
                self._node.remove(self.__longName._node)
            # if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            self._node.append(value._node)
            self.__longName = value
            value._parent = self #set parent
            value._update_path() #updates the path
        elif self.__longName is not None:
            self._node.remove(self.__longName._node)
            self.__longName = None
            self.__longName._parent = None #No parent
            self.__longName._update_path() #updates the path

    def new_LongName(self, name=None):
        """
        Creates a new MultilanguageLongName under the MultilanguageReferrable.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        MultilanguageLongName_obj = MultilanguageLongName()
        if isinstance(MultilanguageLongName_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('LONG-NAME')
        MultilanguageLongName_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        MultilanguageLongName_obj.name = name
        MultilanguageLongName_obj._node = xmlNode
        self.set_longName(MultilanguageLongName_obj)
        return MultilanguageLongName_obj

    def get_children(self):
        children = super().get_children()
        if self.__longName is not None:
            children.append(self.__longName)
        return children

    def _update_path(self):
        """
        Updates the path of the MultilanguageReferrable and its children.
        """
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

class Identifiable(MultilanguageReferrable):
    """
    Instances of this class can be referred to by their identifier (within the namespace borders). In addition to this, Identifiables are objects  which contribute significantly to the overall structure of an AUTOSAR description. In particular, Identifiables might contain Identifiables.
    """
    def __init__(self):
        super().__init__()
        self.__category = None
        self.__uuid = None
        self.__desc = None
        self.__adminData = None
        self.__introduction = None
        self.__annotations = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        category_value = AutosarNode._get_node_text(node,'CATEGORY')
        if category_value is not None:
            self.__category = datatype_utils.get_string_value(category_value)

        uuid_value = AutosarNode._get_node_text(node,'UUID')
        if uuid_value is not None:
            self.__uuid = datatype_utils.get_string_value(uuid_value)

        desc_node = self._node.find('{*}DESC')
        if desc_node is not None:
            self.__desc = MultiLanguageOverviewParagraph()._build(self, desc_node)

        adminData_node = self._node.find('{*}ADMIN-DATA')
        if adminData_node is not None:
            self.__adminData = AdminData()._build(self, adminData_node)

        introduction_node = self._node.find('{*}INTRODUCTION')
        if introduction_node is not None:
            self.__introduction = DocumentationBlock()._build(self, introduction_node)

        annotations_nodes = self._node.findall('{*}ANNOTATIONS/*')
        for annotations_node in annotations_nodes:
            self.__annotations.add(Annotation()._build(self, annotations_node))

        return self

    def get_category(self):
        return self.__category

    def set_category(self, value):
        self.__category = value
        category_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'CATEGORY')
        category_xml_node.text = str(value) if value is not None else ''

    def get_uuid(self):
        return self.__uuid

    def set_uuid(self, value):
        self.__uuid = value
        uuid_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'UUID')
        uuid_xml_node.text = str(value) if value is not None else ''

    def get_desc(self):
        return self.__desc

    def set_desc(self, value):
        """
        Adds a single value to the desc
        """
        if value is not None:
            if isinstance(value, MultiLanguageOverviewParagraph) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of MultiLanguageOverviewParagraph or its sub-classes'.format(value))
            if self.__desc is not None:
                self._node.remove(self.__desc._node)
            # if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            self._node.append(value._node)
            self.__desc = value
            value._parent = self #set parent
            value._update_path() #updates the path
        elif self.__desc is not None:
            self._node.remove(self.__desc._node)
            self.__desc = None
            self.__desc._parent = None #No parent
            self.__desc._update_path() #updates the path

    def get_adminData(self):
        return self.__adminData

    def set_adminData(self, value):
        """
        Adds a single value to the adminData
        """
        if value is not None:
            if isinstance(value, AdminData) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of AdminData or its sub-classes'.format(value))
            if self.__adminData is not None:
                self._node.remove(self.__adminData._node)
            # if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            self._node.append(value._node)
            self.__adminData = value
            value._parent = self #set parent
            value._update_path() #updates the path
        elif self.__adminData is not None:
            self._node.remove(self.__adminData._node)
            self.__adminData = None
            self.__adminData._parent = None #No parent
            self.__adminData._update_path() #updates the path

    def get_introduction(self):
        return self.__introduction

    def set_introduction(self, value):
        """
        Adds a single value to the introduction
        """
        if value is not None:
            if isinstance(value, DocumentationBlock) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of DocumentationBlock or its sub-classes'.format(value))
            if self.__introduction is not None:
                self._node.remove(self.__introduction._node)
            # if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            self._node.append(value._node)
            self.__introduction = value
            value._parent = self #set parent
            value._update_path() #updates the path
        elif self.__introduction is not None:
            self._node.remove(self.__introduction._node)
            self.__introduction = None
            self.__introduction._parent = None #No parent
            self.__introduction._update_path() #updates the path

    def get_annotations(self):
        return self.__annotations

    def add_annotation(self, value):
        """
        Adds a single value to the annotations
        """
        if value is not None:
            if any(v.name == value.name for v in self.__annotations):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, Annotation) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of Annotation or its sub-classes'.format(value))
            self.__annotations.add(value)
            annotations_values = AutosarNode._add_or_get_xml_node(self._node, 'ANNOTATIONS')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            annotations_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_annotations(self, values):
        """
        Adds a list of ref value to the annotations
        """
        for value in values:
            self.add_annotation(value)

    def remove_annotation(self, value):
        """
        Removes a single value from annotations
        """
        if value is not None:
            self.__annotations.remove(value)
            annotations_values = AutosarNode._add_or_get_xml_node(self._node, 'ANNOTATIONS', createNode = False)
            annotations_values.remove(value._node)
            value._parent = None #No parent
            value._update_path() #resets the path

    def remove_annotations(self, values):
        """
        Removes a list of value from annotations
        """
        for value in values:
            self.remove_annotation(value)

    def new_AdminData(self, name=None):
        """
        Creates a new AdminData under the Identifiable.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        AdminData_obj = AdminData()
        if isinstance(AdminData_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('ADMIN-DATA')
