class CommunicationConnector(Identifiable):
    """
    The connection between the referencing ECU and the referenced channel via the referenced controller., , Connectors are used to describe the bus interfaces of the ECUs and to specify the sending/receiving behavior. , Each CommunicationConnector has a reference to exactly one communicationController. , , Note: Several CommunicationConnectors can be assigned to one PhysicalChannel in the scope of one ECU Instance.
    """
    def __init__(self):
        super().__init__()
        self.__createEcuWakeupSource = None
        self.__dynamicPncToChannelMappingEnabled = None
        self.__pncGatewayType = None
        self.__commController = None
        self.__ecuCommPortInstances = set()
        self.__variationPoint = None

    def _build(self, parent, node):
        super()._build(parent, node)
        createEcuWakeupSource_value = AutosarNode._get_node_text(node,'CREATE-ECU-WAKEUP-SOURCE')
        if createEcuWakeupSource_value is not None:
            self.__createEcuWakeupSource = datatype_utils.get_bool_value(createEcuWakeupSource_value)

        dynamicPncToChannelMappingEnabled_value = AutosarNode._get_node_text(node,'DYNAMIC-PNC-TO-CHANNEL-MAPPING-ENABLED')
        if dynamicPncToChannelMappingEnabled_value is not None:
            self.__dynamicPncToChannelMappingEnabled = datatype_utils.get_bool_value(dynamicPncToChannelMappingEnabled_value)

        pncGatewayType_value = AutosarNode._get_node_text(node,'PNC-GATEWAY-TYPE')
        if pncGatewayType_value is not None:
            self.__pncGatewayType = PncGatewayTypeEnum.get(pncGatewayType_value)

        ecuCommPortInstances_obj_dict = {}
        ecuCommPortInstances_obj_dict['I-PDU-PORT'] = 'IPduPort'
        ecuCommPortInstances_obj_dict['FRAME-PORT'] = 'FramePort'
        ecuCommPortInstances_obj_dict['I-SIGNAL-PORT'] = 'ISignalPort'
        ecuCommPortInstances_nodes = self._node.findall('{*}ECU-COMM-PORT-INSTANCES/*')
        for ecuCommPortInstances_node in ecuCommPortInstances_nodes:
            self.__ecuCommPortInstances.add(__str_to_class__(ecuCommPortInstances_obj_dict[etree.QName(ecuCommPortInstances_node).localname])()._build(self, ecuCommPortInstances_node))

        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            self.__variationPoint = VariationPoint()._build(self, variationPoint_node)

        return self

    def _resolve_references(self):
        commController_node = self._node.find('{*}COMM-CONTROLLER-REF')
        if commController_node is not None and commController_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[commController_node.text]
            ref_value.referenced_by.add(self)
            self.__commController = ref_value

    def get_createEcuWakeupSource(self):
        return self.__createEcuWakeupSource

    def set_createEcuWakeupSource(self, value):
        self.__createEcuWakeupSource = value
        createEcuWakeupSource_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'CREATE-ECU-WAKEUP-SOURCE')
        createEcuWakeupSource_xml_node.text = 'true' if value is True else 'false'

    def get_dynamicPncToChannelMappingEnabled(self):
        return self.__dynamicPncToChannelMappingEnabled

    def set_dynamicPncToChannelMappingEnabled(self, value):
        self.__dynamicPncToChannelMappingEnabled = value
        dynamicPncToChannelMappingEnabled_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'DYNAMIC-PNC-TO-CHANNEL-MAPPING-ENABLED')
        dynamicPncToChannelMappingEnabled_xml_node.text = 'true' if value is True else 'false'

    def get_pncGatewayType(self):
        return self.__pncGatewayType

    def set_pncGatewayType(self, value):
        self.__pncGatewayType = value
        pncGatewayType_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'PNC-GATEWAY-TYPE')
        pncGatewayType_xml_node.text = value.literal if value is not None else ''

    def get_commController(self):
        return self.__commController

    def set_commController(self, value):
        """
        Adds a single value to the commController
        """
        if value is not None:
            if isinstance(value, CommunicationController) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of CommunicationController or its sub-classes'.format(value))
            if self.__commController is not None:
                self.__commController.referenced_by.remove(self)
