class TDCpSoftwareClusterMapping(Identifiable):
    """
    This is used to specify a mapping between a software cluster that provides temporal and dynamic resources and the software clusters that need these resources.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'TD-CP-SOFTWARE-CLUSTER-MAPPING'
        self.__provider = None
        self.__requestors = set()
        self.__timingDescription = None
        self.__variationPoint = None

    def _build(self, parent, node):
        super()._build(parent, node)
        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            self.__variationPoint = VariationPoint()._build(self, variationPoint_node)

        return self

    def _resolve_references(self):
        provider_node = self._node.find('{*}PROVIDER-REF')
        if provider_node is not None and provider_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[provider_node.text]
            ref_value.referenced_by.add(self)
            self.__provider = ref_value
        requestors_nodes = self._node.findall('{*}REQUESTOR-REFS/*')
        for node in requestors_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__requestors.add(ref_value)
        timingDescription_node = self._node.find('{*}TIMING-DESCRIPTION-REF')
        if timingDescription_node is not None and timingDescription_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[timingDescription_node.text]
            ref_value.referenced_by.add(self)
            self.__timingDescription = ref_value

    def get_provider(self):
        return self.__provider

