class IndexEntry(ARObject):
    """
    This class represents an index entry.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'INDEX-ENTRY'
        self.__sups = None
        self.__subs = None

        self.__mixedtext = None

    def _build(self, parent, node):
        super()._build(parent, node)
        sups_value = AutosarNode._get_node_text(node,'SUP')
        if sups_value is not None:
            self.__sups = datatype_utils.get_string_value(sups_value)

        subs_value = AutosarNode._get_node_text(node,'SUB')
        if subs_value is not None:
            self.__subs = datatype_utils.get_string_value(subs_value)

        self.__mixedtext = node.text
        return self

    def get_sups(self):
        return self.__sups

    def set_sups(self, value):
        self.__sups = value
        sups_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'SUP')
        sups_xml_node.text = str(value) if value is not None else ''

    def get_subs(self):
        return self.__subs

    def set_subs(self, value):
        self.__subs = value
        subs_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'SUB')
        subs_xml_node.text = str(value) if value is not None else ''

    def get(self):
        return self.__mixedtext

    def set(self, text):
        self.__mixedtext = text
        if text is not None:
            self._node.text = str(text)
        else:
            self._node.text = ''

    def _add_mandatory_attr(self, node, name = None):
        super()._add_mandatory_attr(node, name)
        sups_node = etree.SubElement(node, 'SUP')
        self.__sups = None
        sups_node.text = ''
        subs_node = etree.SubElement(node, 'SUB')
        self.__subs = None
        subs_node.text = ''

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['Sups'] = self.__sups
        property_values['Subs'] = self.__subs
        property_values['Value'] = self.__mixedtext
        return property_values

    def _update_path(self):
        """
        Updates the path of the IndexEntry and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

