class DiagnosticDataChangeTrigger(DiagnosticResponseOnEventTrigger):
    """
    This represents the ability to define a trigger based on the change of a given DiagnosticDataIdentifier.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'DIAGNOSTIC-DATA-CHANGE-TRIGGER'
        self.__dataIdentifier = None


    def _resolve_references(self):
        dataIdentifier_node = self._node.find('{*}DATA-IDENTIFIER-REF')
        if dataIdentifier_node is not None and dataIdentifier_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[dataIdentifier_node.text]
            ref_value.referenced_by.add(self)
            self.__dataIdentifier = ref_value

    def get_dataIdentifier(self):
        return self.__dataIdentifier

    def set_dataIdentifier(self, value):
        """
        Adds a single value to the dataIdentifier
        """
        if value is not None:
            if isinstance(value, DiagnosticDataIdentifier) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of DiagnosticDataIdentifier or its sub-classes'.format(value))
            if self.__dataIdentifier is not None:
                self.__dataIdentifier.referenced_by.remove(self)
            dataIdentifier_value = AutosarNode._add_or_get_xml_node(self._node, 'DATA-IDENTIFIER-REF', value)
            dataIdentifier_value.text = value.path
            dataIdentifier_value.attrib['DEST'] = value.tag
            self.__dataIdentifier = value
            value.referenced_by.add(self)
        elif self.__dataIdentifier is not None:
            self.__dataIdentifier.referenced_by.remove(self)
            self.__dataIdentifier = None
            dataIdentifier_value = AutosarNode._add_or_get_xml_node(self._node, 'DATA-IDENTIFIER-REF', createNode = False)
            if dataIdentifier_value is not None:
                dataIdentifier_value.referenced_by.remove(self)
                dataIdentifier_value.text = ''

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['DataIdentifier'] = self.__dataIdentifier
        return property_values

    def _update_path(self):
        """
        Updates the path of the DiagnosticDataChangeTrigger and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

class AtpBlueprint(Identifiable):
    """
    This meta-class represents the ability to act as a Blueprint. As this class is an abstract one, particular blueprint meta-classes inherit from this one.
    """
    def __init__(self):
        super().__init__()
        self.__shortNamePattern = None
        self.__blueprintPolicies = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        shortNamePattern_value = AutosarNode._get_node_text(node,'SHORT-NAME-PATTERN')
        if shortNamePattern_value is not None:
            self.__shortNamePattern = datatype_utils.get_string_value(shortNamePattern_value)

        blueprintPolicies_obj_dict = {}
        blueprintPolicies_obj_dict['BLUEPRINT-POLICY-NOT-MODIFIABLE'] = 'BlueprintPolicyNotModifiable'
        blueprintPolicies_obj_dict['BLUEPRINT-POLICY-LIST'] = 'BlueprintPolicyList'
        blueprintPolicies_obj_dict['BLUEPRINT-POLICY-SINGLE'] = 'BlueprintPolicySingle'
        blueprintPolicies_nodes = self._node.findall('{*}BLUEPRINT-POLICYS/*')
        for blueprintPolicies_node in blueprintPolicies_nodes:
            self.__blueprintPolicies.add(__str_to_class__(blueprintPolicies_obj_dict[etree.QName(blueprintPolicies_node).localname])()._build(self, blueprintPolicies_node))

        return self

    def get_shortNamePattern(self):
        return self.__shortNamePattern

    def set_shortNamePattern(self, value):
        self.__shortNamePattern = value
        shortNamePattern_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'SHORT-NAME-PATTERN')
        shortNamePattern_xml_node.text = str(value) if value is not None else ''

    def get_blueprintPolicies(self):
        return self.__blueprintPolicies

    def add_blueprintPolicie(self, value):
        """
        Adds a single value to the blueprintPolicies
        """
        if value is not None:
            if any(v.name == value.name for v in self.__blueprintPolicies):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, BlueprintPolicy) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of BlueprintPolicy or its sub-classes'.format(value))
            self.__blueprintPolicies.add(value)
            blueprintPolicies_values = AutosarNode._add_or_get_xml_node(self._node, 'BLUEPRINT-POLICYS')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            blueprintPolicies_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_blueprintPolicies(self, values):
        """
        Adds a list of ref value to the blueprintPolicies
        """
        for value in values:
            self.add_blueprintPolicie(value)

    def remove_blueprintPolicie(self, value):
        """
        Removes a single value from blueprintPolicies
        """
        if value is not None:
            self.__blueprintPolicies.remove(value)
            blueprintPolicies_values = AutosarNode._add_or_get_xml_node(self._node, 'BLUEPRINT-POLICYS', createNode = False)
            blueprintPolicies_values.remove(value._node)
            value._parent = None #No parent
            value._update_path() #resets the path

    def remove_blueprintPolicies(self, values):
        """
        Removes a list of value from blueprintPolicies
        """
        for value in values:
            self.remove_blueprintPolicie(value)

    def new_BlueprintPolicySingle(self, name=None):
        """
        Creates a new BlueprintPolicySingle under the AtpBlueprint.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        BlueprintPolicySingle_obj = BlueprintPolicySingle()
        if isinstance(BlueprintPolicySingle_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('BLUEPRINT-POLICY-SINGLE')
        BlueprintPolicySingle_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        BlueprintPolicySingle_obj.name = name
        BlueprintPolicySingle_obj._node = xmlNode
        self.add_blueprintPolicie(BlueprintPolicySingle_obj)
        return BlueprintPolicySingle_obj

    def new_BlueprintPolicyList(self, name=None):
        """
        Creates a new BlueprintPolicyList under the AtpBlueprint.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        BlueprintPolicyList_obj = BlueprintPolicyList()
        if isinstance(BlueprintPolicyList_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('BLUEPRINT-POLICY-LIST')
        BlueprintPolicyList_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        BlueprintPolicyList_obj.name = name
        BlueprintPolicyList_obj._node = xmlNode
        self.add_blueprintPolicie(BlueprintPolicyList_obj)
        return BlueprintPolicyList_obj

    def new_BlueprintPolicyNotModifiable(self, name=None):
        """
        Creates a new BlueprintPolicyNotModifiable under the AtpBlueprint.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        BlueprintPolicyNotModifiable_obj = BlueprintPolicyNotModifiable()
        if isinstance(BlueprintPolicyNotModifiable_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('BLUEPRINT-POLICY-NOT-MODIFIABLE')
        BlueprintPolicyNotModifiable_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        BlueprintPolicyNotModifiable_obj.name = name
        BlueprintPolicyNotModifiable_obj._node = xmlNode
        self.add_blueprintPolicie(BlueprintPolicyNotModifiable_obj)
        return BlueprintPolicyNotModifiable_obj

    def get_children(self):
        children = super().get_children()
        children.extend(self.__blueprintPolicies)
        return children

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['ShortNamePattern'] = self.__shortNamePattern
        return property_values

    def _update_path(self):
        """
        Updates the path of the AtpBlueprint and its children.
        """
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

