class BswEvent(AbstractEvent):
    """
    Base class of various kinds of events which are used to trigger a BswModuleEntity of this BSW module or cluster. The event is local to the BSW module or cluster. The short name of the meta-class instance is intended as an input to configure the required API of the BSW Scheduler.
    """
    def __init__(self):
        super().__init__()
        self.__contextLimitations = set()
        self.__disabledInModes = set()
        self.__startsOnEvent = None
        self.__variationPoint = None

    def _build(self, parent, node):
        super()._build(parent, node)
        disabledInModes_nodes = self._node.findall('{*}DISABLED-IN-MODE-IREFS/*')
        for disabledInModes_node in disabledInModes_nodes:
            self.__disabledInModes.add(ModeInBswModuleDescriptionInstanceRef()._build(self, disabledInModes_node))

        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            self.__variationPoint = VariationPoint()._build(self, variationPoint_node)

        return self

    def _resolve_references(self):
        contextLimitations_nodes = self._node.findall('{*}CONTEXT-LIMITATION-REFS/*')
        for node in contextLimitations_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__contextLimitations.add(ref_value)
        startsOnEvent_node = self._node.find('{*}STARTS-ON-EVENT-REF')
        if startsOnEvent_node is not None and startsOnEvent_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[startsOnEvent_node.text]
            ref_value.referenced_by.add(self)
            self.__startsOnEvent = ref_value

    def get_contextLimitations(self):
        return self.__contextLimitations

    def add_contextLimitation(self, value):
        """
        Adds a single value to the contextLimitations
        """
        if value is not None:
            if any(v.name == value.name for v in self.__contextLimitations):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, BswDistinguishedPartition) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of BswDistinguishedPartition or its sub-classes'.format(value))
            self.__contextLimitations.add(value)
            contextLimitations_values = AutosarNode._add_or_get_xml_node(self._node, 'CONTEXT-LIMITATION-REFS')

            contextLimitations_value = AutosarNode._add_or_get_xml_node(contextLimitations_values, 'CONTEXT-LIMITATION-REF', value, forceCreate = True)
            contextLimitations_value.text = value.path
            value.referenced_by.add(self)

    def set_contextLimitations(self, values):
        """
        Adds a list of ref value to the contextLimitations
        """
        for value in values:
            self.add_contextLimitation(value)

    def remove_contextLimitation(self, value):
        """
        Removes a single value from contextLimitations
        """
        if value is not None:
            self.__contextLimitations.remove(value)
            contextLimitations_values = AutosarNode._add_or_get_xml_node(self._node, 'CONTEXT-LIMITATION-REFS', createNode = False)
            for contextLimitations_value in self._node.findall('{*}CONTEXT-LIMITATION-REFS/*'):
                if contextLimitations_value.text == value.path:
                    contextLimitations_value.text = ''
                    contextLimitations_values.remove(contextLimitations_value)
                    value.referenced_by.remove(self)
                    break

    def remove_contextLimitations(self, values):
        """
        Removes a list of value from contextLimitations
        """
        for value in values:
            self.remove_contextLimitation(value)

    def get_disabledInModes(self):
        return self.__disabledInModes

    def add_disabledInMode(self, value):
        """
        Adds a single value to the disabledInModes
        """
        if value is not None:
            if any(v.name == value.name for v in self.__disabledInModes):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, ModeInBswModuleDescriptionInstanceRef) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ModeInBswModuleDescriptionInstanceRef or its sub-classes'.format(value))
            self.__disabledInModes.add(value)
            disabledInModes_values = AutosarNode._add_or_get_xml_node(self._node, 'DISABLED-IN-MODE-IREFS')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            disabledInModes_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_disabledInModes(self, values):
        """
        Adds a list of ref value to the disabledInModes
        """
        for value in values:
            self.add_disabledInMode(value)

    def remove_disabledInMode(self, value):
        """
        Removes a single value from disabledInModes
        """
        if value is not None:
            self.__disabledInModes.remove(value)
            disabledInModes_values = AutosarNode._add_or_get_xml_node(self._node, 'DISABLED-IN-MODE-IREFS', createNode = False)
            disabledInModes_values.remove(value._node)
            value._parent = None #No parent
            value._update_path() #resets the path

    def remove_disabledInModes(self, values):
        """
        Removes a list of value from disabledInModes
        """
        for value in values:
            self.remove_disabledInMode(value)

    def get_startsOnEvent(self):
        return self.__startsOnEvent

    def set_startsOnEvent(self, value):
        """
        Adds a single value to the startsOnEvent
        """
        if value is not None:
            if isinstance(value, BswModuleEntity) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of BswModuleEntity or its sub-classes'.format(value))
            if self.__startsOnEvent is not None:
                self.__startsOnEvent.referenced_by.remove(self)
            startsOnEvent_value = AutosarNode._add_or_get_xml_node(self._node, 'STARTS-ON-EVENT-REF', value)
            startsOnEvent_value.text = value.path
            startsOnEvent_value.attrib['DEST'] = value.tag
            self.__startsOnEvent = value
            value.referenced_by.add(self)
        elif self.__startsOnEvent is not None:
            self.__startsOnEvent.referenced_by.remove(self)
            self.__startsOnEvent = None
            startsOnEvent_value = AutosarNode._add_or_get_xml_node(self._node, 'STARTS-ON-EVENT-REF', createNode = False)
            if startsOnEvent_value is not None:
                startsOnEvent_value.referenced_by.remove(self)
                startsOnEvent_value.text = ''

    def get_variationPoint(self):
        return self.__variationPoint

    def set_variationPoint(self, value):
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))
            if self.__variationPoint is not None:
                self._node.remove(self.__variationPoint._node)
            # if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            self._node.append(value._node)
            self.__variationPoint = value
            value._parent = self #set parent
            value._update_path() #updates the path
        elif self.__variationPoint is not None:
            self._node.remove(self.__variationPoint._node)
            self.__variationPoint = None
            self.__variationPoint._parent = None #No parent
            self.__variationPoint._update_path() #updates the path

