        property_values['PncSynchronousWakeup'] = self.__pncSynchronousWakeup
        property_values['SleepModeSupported'] = self.__sleepModeSupported
        property_values['V2xSupported'] = self.__v2xSupported
        property_values['WakeUpOverBusSupported'] = self.__wakeUpOverBusSupported
        property_values['AssociatedComIPduGroups'] = self.__associatedComIPduGroups
        property_values['AssociatedPdurIPduGroups'] = self.__associatedPdurIPduGroups
        property_values['CanTpAddress'] = self.__canTpAddress
