class CouplingElement(FibexElement):
    """
    A CouplingElement is used to connect EcuInstances to the VLAN of an EthernetCluster. CouplingElements can reach from a simple hub to a complex managed switch or even devices with functionalities in higher layers. A CouplingElement that is not related to an EcuInstance occurs as a dedicated single device.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'COUPLING-ELEMENT'
        self.__couplingType = None
        self.__communicationCluster = None
        self.__couplingPorts = set()
        self.__ecuInstance = None

    def _build(self, parent, node):
        super()._build(parent, node)
        couplingType_value = AutosarNode._get_node_text(node,'COUPLING-TYPE')
        if couplingType_value is not None:
            self.__couplingType = CouplingElementEnum.get(couplingType_value)

        couplingPorts_nodes = self._node.findall('{*}COUPLING-PORTS/*')
        for couplingPorts_node in couplingPorts_nodes:
            self.__couplingPorts.add(CouplingPort()._build(self, couplingPorts_node))

        return self

    def _resolve_references(self):
        communicationCluster_node = self._node.find('{*}COMMUNICATION-CLUSTER-REF')
        if communicationCluster_node is not None and communicationCluster_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[communicationCluster_node.text]
            ref_value.referenced_by.add(self)
            self.__communicationCluster = ref_value
        ecuInstance_node = self._node.find('{*}ECU-INSTANCE-REF')
        if ecuInstance_node is not None and ecuInstance_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[ecuInstance_node.text]
            ref_value.referenced_by.add(self)
            self.__ecuInstance = ref_value

    def get_couplingType(self):
        return self.__couplingType

    def set_couplingType(self, value):
        self.__couplingType = value
        couplingType_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'COUPLING-TYPE')
        couplingType_xml_node.text = value.literal if value is not None else ''

    def get_communicationCluster(self):
        return self.__communicationCluster

    def set_communicationCluster(self, value):
        """
        Adds a single value to the communicationCluster
        """
        if value is not None:
            if isinstance(value, EthernetCluster) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of EthernetCluster or its sub-classes'.format(value))
            if self.__communicationCluster is not None:
                self.__communicationCluster.referenced_by.remove(self)
            communicationCluster_value = AutosarNode._add_or_get_xml_node(self._node, 'COMMUNICATION-CLUSTER-REF', value)
            communicationCluster_value.text = value.path
            communicationCluster_value.attrib['DEST'] = value.tag
            self.__communicationCluster = value
            value.referenced_by.add(self)
        elif self.__communicationCluster is not None:
            self.__communicationCluster.referenced_by.remove(self)
            self.__communicationCluster = None
            communicationCluster_value = AutosarNode._add_or_get_xml_node(self._node, 'COMMUNICATION-CLUSTER-REF', createNode = False)
            if communicationCluster_value is not None:
                communicationCluster_value.referenced_by.remove(self)
                communicationCluster_value.text = ''

    def get_couplingPorts(self):
        return self.__couplingPorts

    def add_couplingPort(self, value):
        """
        Adds a single value to the couplingPorts
        """
        if value is not None:
            if any(v.name == value.name for v in self.__couplingPorts):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, CouplingPort) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of CouplingPort or its sub-classes'.format(value))
            self.__couplingPorts.add(value)
            couplingPorts_values = AutosarNode._add_or_get_xml_node(self._node, 'COUPLING-PORTS')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            couplingPorts_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_couplingPorts(self, values):
        """
        Adds a list of ref value to the couplingPorts
        """
        for value in values:
            self.add_couplingPort(value)

    def remove_couplingPort(self, value):
        """
        Removes a single value from couplingPorts
        """
        if value is not None:
            self.__couplingPorts.remove(value)
            couplingPorts_values = AutosarNode._add_or_get_xml_node(self._node, 'COUPLING-PORTS', createNode = False)
            couplingPorts_values.remove(value._node)
            value._parent = None #No parent
            value._update_path() #resets the path

    def remove_couplingPorts(self, values):
        """
        Removes a list of value from couplingPorts
        """
        for value in values:
            self.remove_couplingPort(value)

    def get_ecuInstance(self):
        return self.__ecuInstance

    def set_ecuInstance(self, value):
        """
        Adds a single value to the ecuInstance
        """
        if value is not None:
            if isinstance(value, EcuInstance) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of EcuInstance or its sub-classes'.format(value))
            if self.__ecuInstance is not None:
                self.__ecuInstance.referenced_by.remove(self)
            ecuInstance_value = AutosarNode._add_or_get_xml_node(self._node, 'ECU-INSTANCE-REF', value)
            ecuInstance_value.text = value.path
            ecuInstance_value.attrib['DEST'] = value.tag
            self.__ecuInstance = value
            value.referenced_by.add(self)
        elif self.__ecuInstance is not None:
            self.__ecuInstance.referenced_by.remove(self)
            self.__ecuInstance = None
            ecuInstance_value = AutosarNode._add_or_get_xml_node(self._node, 'ECU-INSTANCE-REF', createNode = False)
            if ecuInstance_value is not None:
                ecuInstance_value.referenced_by.remove(self)
                ecuInstance_value.text = ''

    def new_CouplingPort(self, name=None):
        """
        Creates a new CouplingPort under the CouplingElement.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        CouplingPort_obj = CouplingPort()
        if isinstance(CouplingPort_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('COUPLING-PORT')
        CouplingPort_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        CouplingPort_obj.name = name
        CouplingPort_obj._node = xmlNode
        self.add_couplingPort(CouplingPort_obj)
        return CouplingPort_obj

    def _add_mandatory_attr(self, node, name = None):
        super()._add_mandatory_attr(node, name)
        couplingType_node = etree.SubElement(node, 'COUPLING-TYPE')
        couplingType_node.text = ''

    def get_children(self):
        children = super().get_children()
        children.extend(self.__couplingPorts)
        return children

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['CouplingType'] = self.__couplingType
        property_values['CommunicationCluster'] = self.__communicationCluster
        property_values['EcuInstance'] = self.__ecuInstance
        return property_values

    def _update_path(self):
        """
        Updates the path of the CouplingElement and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

