class InvertCondition(AbstractCondition):
    """
    inverts the nested condition
    """
    def __init__(self):
        super().__init__()
        self.tag = 'INVERT-CONDITION'
        self.__condition = None

    def _build(self, parent, node):
        super()._build(parent, node)
        condition_obj_dict = {}
        condition_obj_dict['AGGREGATION-CONDITION'] = 'AggregationCondition'
        condition_obj_dict['PRIMITIVE-ATTRIBUTE-CONDITION'] = 'PrimitiveAttributeCondition'
        condition_obj_dict['INVERT-CONDITION'] = 'InvertCondition'
        condition_obj_dict['REFERENCE-CONDITION'] = 'ReferenceCondition'
        condition_obj_dict['TEXTUAL-CONDITION'] = 'TextualCondition'
        condition_node = self._node.find('{*}CONDITION/*')
        if condition_node is not None:
            self.__condition = __str_to_class__(condition_obj_dict[etree.QName(condition_node).localname])()._build(self, condition_node)

        return self

    def get_condition(self):
        return self.__condition

    def set_condition(self, value):
        """
        Adds a single value to the condition
        """
        if value is not None:
            if isinstance(value, AbstractCondition) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of AbstractCondition or its sub-classes'.format(value))
            if self.__condition is not None:
                self._node.remove(self.__condition._node)
            # if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            condition_xmlNode = AutosarNode._add_or_get_xml_node(self._node, 'CONDITION')
            self._node.append(condition_xmlNode)
            condition_xmlNode.append(value._node)
            self.__condition = value
            value._parent = self #set parent
            value._update_path() #updates the path
        elif self.__condition is not None:
            self._node.remove(self.__condition._node)
            self.__condition = None
            self.__condition._parent = None #No parent
            self.__condition._update_path() #updates the path

    def new_PrimitiveAttributeCondition(self, name=None):
        """
        Creates a new PrimitiveAttributeCondition under the InvertCondition.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        PrimitiveAttributeCondition_obj = PrimitiveAttributeCondition()
        if isinstance(PrimitiveAttributeCondition_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('PRIMITIVE-ATTRIBUTE-CONDITION')
        PrimitiveAttributeCondition_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        PrimitiveAttributeCondition_obj.name = name
        PrimitiveAttributeCondition_obj._node = xmlNode
        self.set_condition(PrimitiveAttributeCondition_obj)
        return PrimitiveAttributeCondition_obj

