class Traceable(MultilanguageReferrable):
    """
    This meta class represents the ability to be subject to tracing within an AUTOSAR model., , Note that it is expected that its subclasses inherit either from MultilanguageReferrable or from Identifiable. Nevertheless it also inherits from MultilanguageReferrable in order to provide a common reference target for all Traceables.
    """
    def __init__(self):
        super().__init__()
        self.__traces = set()


    def _resolve_references(self):
        traces_nodes = self._node.findall('{*}TRACE-REFS/*')
        for node in traces_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__traces.add(ref_value)

    def get_traces(self):
        return self.__traces

    def add_trace(self, value):
        """
        Adds a single value to the traces
        """
        if value is not None:
            if any(v.name == value.name for v in self.__traces):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, Traceable) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of Traceable or its sub-classes'.format(value))
            self.__traces.add(value)
            traces_values = AutosarNode._add_or_get_xml_node(self._node, 'TRACE-REFS')

            traces_value = AutosarNode._add_or_get_xml_node(traces_values, 'TRACE-REF', value, forceCreate = True)
            traces_value.text = value.path
            value.referenced_by.add(self)

    def set_traces(self, values):
        """
        Adds a list of ref value to the traces
        """
        for value in values:
            self.add_trace(value)

    def remove_trace(self, value):
        """
        Removes a single value from traces
        """
        if value is not None:
            self.__traces.remove(value)
            traces_values = AutosarNode._add_or_get_xml_node(self._node, 'TRACE-REFS', createNode = False)
            for traces_value in self._node.findall('{*}TRACE-REFS/*'):
                if traces_value.text == value.path:
                    traces_value.text = ''
                    traces_values.remove(traces_value)
                    value.referenced_by.remove(self)
                    break

    def remove_traces(self, values):
        """
        Removes a list of value from traces
        """
        for value in values:
            self.remove_trace(value)

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['Traces'] = self.__traces
        return property_values

    def _update_path(self):
        """
        Updates the path of the Traceable and its children.
        """
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

