class PredefinedVariant(ARElement):
    """
    This specifies one predefined variant. It is characterized by the union of all system constant values and post-build variant criterion values aggregated within all referenced system constant value sets and post build variant criterion value sets plus the value sets of the included variants.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'PREDEFINED-VARIANT'
        self.__includedVariants = set()
        self.__postBuildVariantCriterionValueSets = set()
        self.__swSystemconstantValueSets = set()


    def _resolve_references(self):
        includedVariants_nodes = self._node.findall('{*}INCLUDED-VARIANT-REFS/*')
        for node in includedVariants_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__includedVariants.add(ref_value)
        postBuildVariantCriterionValueSets_nodes = self._node.findall('{*}POST-BUILD-VARIANT-CRITERION-VALUE-SET-REFS/*')
        for node in postBuildVariantCriterionValueSets_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__postBuildVariantCriterionValueSets.add(ref_value)
        swSystemconstantValueSets_nodes = self._node.findall('{*}SW-SYSTEMCONSTANT-VALUE-SET-REFS/*')
        for node in swSystemconstantValueSets_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__swSystemconstantValueSets.add(ref_value)

    def get_includedVariants(self):
        return self.__includedVariants

    def add_includedVariant(self, value):
        """
        Adds a single value to the includedVariants
        """
        if value is not None:
            if any(v.name == value.name for v in self.__includedVariants):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, PredefinedVariant) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of PredefinedVariant or its sub-classes'.format(value))
            self.__includedVariants.add(value)
            includedVariants_values = AutosarNode._add_or_get_xml_node(self._node, 'INCLUDED-VARIANT-REFS')

            includedVariants_value = AutosarNode._add_or_get_xml_node(includedVariants_values, 'INCLUDED-VARIANT-REF', value, forceCreate = True)
            includedVariants_value.text = value.path
            value.referenced_by.add(self)

    def set_includedVariants(self, values):
        """
        Adds a list of ref value to the includedVariants
        """
        for value in values:
            self.add_includedVariant(value)

    def remove_includedVariant(self, value):
        """
        Removes a single value from includedVariants
        """
        if value is not None:
            self.__includedVariants.remove(value)
            includedVariants_values = AutosarNode._add_or_get_xml_node(self._node, 'INCLUDED-VARIANT-REFS', createNode = False)
            for includedVariants_value in self._node.findall('{*}INCLUDED-VARIANT-REFS/*'):
                if includedVariants_value.text == value.path:
                    includedVariants_value.text = ''
                    includedVariants_values.remove(includedVariants_value)
                    value.referenced_by.remove(self)
                    break

    def remove_includedVariants(self, values):
        """
        Removes a list of value from includedVariants
        """
        for value in values:
            self.remove_includedVariant(value)

