class SoftwareClusterDependencyFormula(SoftwareClusterDependencyFormulaPart):
    """
    This meta-class represents the ability to define a dependency among SoftwareClusters.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'SOFTWARE-CLUSTER-DEPENDENCY-FORMULA'
        self.__category = None
        self.__operator = None
        self.__parts = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        category_value = AutosarNode._get_node_text(node,'CATEGORY')
        if category_value is not None:
            self.__category = datatype_utils.get_string_value(category_value)

        operator_value = AutosarNode._get_node_text(node,'OPERATOR')
        if operator_value is not None:
            self.__operator = SoftwareClusterDependencyLogicalOperatorEnum.get(operator_value)

        parts_obj_dict = {}
        parts_obj_dict['SOFTWARE-CLUSTER-DEPENDENCY-COMPARE-CONDITION'] = 'SoftwareClusterDependencyCompareCondition'
        parts_obj_dict['SOFTWARE-CLUSTER-DEPENDENCY-FORMULA'] = 'SoftwareClusterDependencyFormula'
        parts_nodes = self._node.findall('{*}PARTS/*')
        for parts_node in parts_nodes:
            self.__parts.add(__str_to_class__(parts_obj_dict[etree.QName(parts_node).localname])()._build(self, parts_node))

        return self

    def get_category(self):
        return self.__category

