class TimingExtension(ARElement):
    """
    The abstract parent class of the different template specific timing extensions., , Depending on the specific timing extension the timing descriptions and timing constraints, that can be used to specify the timing behavior, are restricted.
    """
    def __init__(self):
        super().__init__()
        self.__timingConditions = set()
        self.__timingDescriptions = set()
        self.__timingGuarantees = set()
        self.__timingRequirements = set()
        self.__timingResource = None

    def _build(self, parent, node):
        super()._build(parent, node)
        timingConditions_nodes = self._node.findall('{*}TIMING-CONDITIONS/*')
        for timingConditions_node in timingConditions_nodes:
            self.__timingConditions.add(TimingCondition()._build(self, timingConditions_node))

        timingDescriptions_obj_dict = {}
        timingDescriptions_obj_dict['TD-EVENT-TT-CAN-CYCLE-START'] = 'TDEventTTCanCycleStart'
        timingDescriptions_obj_dict['TD-EVENT-TRIGGER'] = 'TDEventTrigger'
        timingDescriptions_obj_dict['TD-EVENT-BSW-MODE-DECLARATION'] = 'TDEventBswModeDeclaration'
        timingDescriptions_obj_dict['TD-EVENT-FRAME'] = 'TDEventFrame'
        timingDescriptions_obj_dict['TD-EVENT-SWC-INTERNAL-BEHAVIOR-REFERENCE'] = 'TDEventSwcInternalBehaviorReference'
        timingDescriptions_obj_dict['TD-EVENT-SERVICE-INSTANCE-METHOD'] = 'TDEventServiceInstanceMethod'
        timingDescriptions_obj_dict['TD-EVENT-FRAME-ETHERNET'] = 'TDEventFrameEthernet'
        timingDescriptions_obj_dict['TD-EVENT-BSW-MODULE'] = 'TDEventBswModule'
        timingDescriptions_obj_dict['TD-EVENT-MODE-DECLARATION'] = 'TDEventModeDeclaration'
        timingDescriptions_obj_dict['TD-EVENT-VARIABLE-DATA-PROTOTYPE'] = 'TDEventVariableDataPrototype'
        timingDescriptions_obj_dict['TD-EVENT-SERVICE-INSTANCE-DISCOVERY'] = 'TDEventServiceInstanceDiscovery'
        timingDescriptions_obj_dict['TD-EVENT-VFB-REFERENCE'] = 'TDEventVfbReference'
        timingDescriptions_obj_dict['TD-EVENT-I-PDU'] = 'TDEventIPdu'
        timingDescriptions_obj_dict['TD-EVENT-SERVICE-INSTANCE-EVENT'] = 'TDEventServiceInstanceEvent'
        timingDescriptions_obj_dict['TD-EVENT-COMPLEX'] = 'TDEventComplex'
        timingDescriptions_obj_dict['TD-EVENT-SWC-INTERNAL-BEHAVIOR'] = 'TDEventSwcInternalBehavior'
        timingDescriptions_obj_dict['TD-EVENT-BSW-INTERNAL-BEHAVIOR'] = 'TDEventBswInternalBehavior'
        timingDescriptions_obj_dict['TD-EVENT-I-SIGNAL'] = 'TDEventISignal'
        timingDescriptions_obj_dict['TD-EVENT-OPERATION'] = 'TDEventOperation'
        timingDescriptions_obj_dict['TD-EVENT-SERVICE-INSTANCE-FIELD'] = 'TDEventServiceInstanceField'
        timingDescriptions_obj_dict['TIMING-DESCRIPTION-EVENT-CHAIN'] = 'TimingDescriptionEventChain'
        timingDescriptions_obj_dict['TD-EVENT-FR-CLUSTER-CYCLE-START'] = 'TDEventFrClusterCycleStart'
        timingDescriptions_nodes = self._node.findall('{*}TIMING-DESCRIPTIONS/*')
        for timingDescriptions_node in timingDescriptions_nodes:
            self.__timingDescriptions.add(__str_to_class__(timingDescriptions_obj_dict[etree.QName(timingDescriptions_node).localname])()._build(self, timingDescriptions_node))

        timingGuarantees_obj_dict = {}
        timingGuarantees_obj_dict['LATENCY-TIMING-CONSTRAINT'] = 'LatencyTimingConstraint'
        timingGuarantees_obj_dict['SPORADIC-EVENT-TRIGGERING'] = 'SporadicEventTriggering'
        timingGuarantees_obj_dict['PERIODIC-EVENT-TRIGGERING'] = 'PeriodicEventTriggering'
        timingGuarantees_obj_dict['EXECUTION-ORDER-CONSTRAINT'] = 'ExecutionOrderConstraint'
