class EcuTiming(TimingExtension):
    """
    A model element used to define timing descriptions and constraints within the scope of one ECU configuration., , TimingDescriptions aggregated by EcuTiming are allowed to use all events derived from the class TimingDescriptionEvent.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'ECU-TIMING'
        self.__ecuConfiguration = None


    def _resolve_references(self):
        ecuConfiguration_node = self._node.find('{*}ECU-CONFIGURATION-REF')
        if ecuConfiguration_node is not None and ecuConfiguration_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[ecuConfiguration_node.text]
            ref_value.referenced_by.add(self)
            self.__ecuConfiguration = ref_value

    def get_ecuConfiguration(self):
        return self.__ecuConfiguration

    def set_ecuConfiguration(self, value):
        """
        Adds a single value to the ecuConfiguration
        """
        if value is not None:
            if isinstance(value, EcucValueCollection) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of EcucValueCollection or its sub-classes'.format(value))
            if self.__ecuConfiguration is not None:
                self.__ecuConfiguration.referenced_by.remove(self)
            ecuConfiguration_value = AutosarNode._add_or_get_xml_node(self._node, 'ECU-CONFIGURATION-REF', value)
            ecuConfiguration_value.text = value.path
            ecuConfiguration_value.attrib['DEST'] = value.tag
            self.__ecuConfiguration = value
            value.referenced_by.add(self)
        elif self.__ecuConfiguration is not None:
            self.__ecuConfiguration.referenced_by.remove(self)
            self.__ecuConfiguration = None
            ecuConfiguration_value = AutosarNode._add_or_get_xml_node(self._node, 'ECU-CONFIGURATION-REF', createNode = False)
            if ecuConfiguration_value is not None:
                ecuConfiguration_value.referenced_by.remove(self)
                ecuConfiguration_value.text = ''

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['EcuConfiguration'] = self.__ecuConfiguration
        return property_values

    def _update_path(self):
        """
        Updates the path of the EcuTiming and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

