class MultiplexedPart(ARObject):
    """
    The StaticPart and the DynamicPart have common properties. Both can be separated in multiple segments within the multiplexed PDU.
    """
    def __init__(self):
        super().__init__()
        self.__segmentPositions = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        segmentPositions_nodes = self._node.findall('{*}SEGMENT-POSITIONS/*')
        for segmentPositions_node in segmentPositions_nodes:
            self.__segmentPositions.add(SegmentPosition()._build(self, segmentPositions_node))

        return self

    def get_segmentPositions(self):
        return self.__segmentPositions

    def add_segmentPosition(self, value):
        """
        Adds a single value to the segmentPositions
        """
        if value is not None:
            if any(v.name == value.name for v in self.__segmentPositions):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, SegmentPosition) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of SegmentPosition or its sub-classes'.format(value))
            self.__segmentPositions.add(value)
            segmentPositions_values = AutosarNode._add_or_get_xml_node(self._node, 'SEGMENT-POSITIONS')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            segmentPositions_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_segmentPositions(self, values):
        """
        Adds a list of ref value to the segmentPositions
        """
        for value in values:
            self.add_segmentPosition(value)

    def remove_segmentPosition(self, value):
        """
        Removes a single value from segmentPositions
        """
        if value is not None:
            self.__segmentPositions.remove(value)
            segmentPositions_values = AutosarNode._add_or_get_xml_node(self._node, 'SEGMENT-POSITIONS', createNode = False)
            segmentPositions_values.remove(value._node)
            value._parent = None #No parent
            value._update_path() #resets the path

    def remove_segmentPositions(self, values):
        """
        Removes a list of value from segmentPositions
        """
        for value in values:
            self.remove_segmentPosition(value)

    def new_SegmentPosition(self, name=None):
        """
        Creates a new SegmentPosition under the MultiplexedPart.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        SegmentPosition_obj = SegmentPosition()
        if isinstance(SegmentPosition_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('SEGMENT-POSITION')
        SegmentPosition_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        SegmentPosition_obj.name = name
        SegmentPosition_obj._node = xmlNode
        self.add_segmentPosition(SegmentPosition_obj)
        return SegmentPosition_obj

    def get_children(self):
        children = super().get_children()
        children.extend(self.__segmentPositions)
        return children

    def _update_path(self):
        """
        Updates the path of the MultiplexedPart and its children.
        """
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

class DynamicPart(MultiplexedPart):
    """
    Dynamic part of a multiplexed I-Pdu. , Reserved space which is used to transport varying SignalIPdus at the same position, controlled by the corresponding selectorFieldCode.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'DYNAMIC-PART'
        self.__dynamicPartAlternatives = set()
        self.__variationPoint = None

    def _build(self, parent, node):
        super()._build(parent, node)
        dynamicPartAlternatives_nodes = self._node.findall('{*}DYNAMIC-PART-ALTERNATIVES/*')
        for dynamicPartAlternatives_node in dynamicPartAlternatives_nodes:
            self.__dynamicPartAlternatives.add(DynamicPartAlternative()._build(self, dynamicPartAlternatives_node))

        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            self.__variationPoint = VariationPoint()._build(self, variationPoint_node)

        return self

