        """
        Adds a single value to the providedData
        """
        if value is not None:
            if isinstance(value, VariableDataPrototype) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariableDataPrototype or its sub-classes'.format(value))
            if self.__providedData is not None:
                self.__providedData.referenced_by.remove(self)
            providedData_value = AutosarNode._add_or_get_xml_node(self._node, 'PROVIDED-DATA-REF', value)
            providedData_value.text = value.path
            providedData_value.attrib['DEST'] = value.tag
            self.__providedData = value
            value.referenced_by.add(self)
        elif self.__providedData is not None:
            self.__providedData.referenced_by.remove(self)
            self.__providedData = None
            providedData_value = AutosarNode._add_or_get_xml_node(self._node, 'PROVIDED-DATA-REF', createNode = False)
