class VariationPoint(ARObject):
    """
    This meta-class represents the ability to express a "structural variation point". The container of the variation point is part of the selected variant if swSyscond evaluates to true and each postBuildVariantCriterion is fulfilled.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'VARIATION-POINT'
        self.__shortLabel = None
        self.__desc = None
        self.__blueprintCondition = None
        self.__formalBlueprintCondition = None
        self.__formalBlueprintGenerator = None
        self.__swSyscond = None
        self.__postBuildVariantConditions = set()
        self.__sdg = None

    def _build(self, parent, node):
        super()._build(parent, node)
        shortLabel_value = AutosarNode._get_node_text(node,'SHORT-LABEL')
        if shortLabel_value is not None:
            self.__shortLabel = datatype_utils.get_string_value(shortLabel_value)

        desc_node = self._node.find('{*}DESC')
        if desc_node is not None:
            self.__desc = MultiLanguageOverviewParagraph()._build(self, desc_node)

        blueprintCondition_node = self._node.find('{*}BLUEPRINT-CONDITION')
        if blueprintCondition_node is not None:
            self.__blueprintCondition = DocumentationBlock()._build(self, blueprintCondition_node)

        formalBlueprintCondition_node = self._node.find('{*}FORMAL-BLUEPRINT-CONDITION')
        if formalBlueprintCondition_node is not None:
            self.__formalBlueprintCondition = BlueprintFormula()._build(self, formalBlueprintCondition_node)

        formalBlueprintGenerator_node = self._node.find('{*}FORMAL-BLUEPRINT-GENERATOR')
        if formalBlueprintGenerator_node is not None:
            self.__formalBlueprintGenerator = BlueprintGenerator()._build(self, formalBlueprintGenerator_node)

        swSyscond_node = self._node.find('{*}SW-SYSCOND')
        if swSyscond_node is not None:
            self.__swSyscond = ConditionByFormula()._build(self, swSyscond_node)

        postBuildVariantConditions_nodes = self._node.findall('{*}POST-BUILD-VARIANT-CONDITIONS/*')
        for postBuildVariantConditions_node in postBuildVariantConditions_nodes:
            self.__postBuildVariantConditions.add(PostBuildVariantCondition()._build(self, postBuildVariantConditions_node))

        sdg_node = self._node.find('{*}SDG')
        if sdg_node is not None:
            self.__sdg = Sdg()._build(self, sdg_node)

        return self

    def get_shortLabel(self):
        return self.__shortLabel

    def set_shortLabel(self, value):
        self.__shortLabel = value
        shortLabel_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'SHORT-LABEL')
        shortLabel_xml_node.text = str(value) if value is not None else ''

    def get_desc(self):
        return self.__desc

    def set_desc(self, value):
        """
        Adds a single value to the desc
        """
        if value is not None:
            if isinstance(value, MultiLanguageOverviewParagraph) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of MultiLanguageOverviewParagraph or its sub-classes'.format(value))
            if self.__desc is not None:
                self._node.remove(self.__desc._node)
            # if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            self._node.append(value._node)
            self.__desc = value
            value._parent = self #set parent
            value._update_path() #updates the path
        elif self.__desc is not None:
            self._node.remove(self.__desc._node)
            self.__desc = None
            self.__desc._parent = None #No parent
            self.__desc._update_path() #updates the path

    def get_blueprintCondition(self):
        return self.__blueprintCondition

    def set_blueprintCondition(self, value):
        """
        Adds a single value to the blueprintCondition
        """
