class EthTpConfig(TpConfig):
    """
    This element defines which PduTriggerings shall be handled using "TP" semantics.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'ETH-TP-CONFIG'
        self.__tpConnections = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        tpConnections_nodes = self._node.findall('{*}TP-CONNECTIONS/*')
        for tpConnections_node in tpConnections_nodes:
            self.__tpConnections.add(EthTpConnection()._build(self, tpConnections_node))

        return self

    def get_tpConnections(self):
        return self.__tpConnections

    def add_tpConnection(self, value):
        """
        Adds a single value to the tpConnections
        """
        if value is not None:
            if any(v.name == value.name for v in self.__tpConnections):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, EthTpConnection) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of EthTpConnection or its sub-classes'.format(value))
            self.__tpConnections.add(value)
            tpConnections_values = AutosarNode._add_or_get_xml_node(self._node, 'TP-CONNECTIONS')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            tpConnections_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_tpConnections(self, values):
        """
        Adds a list of ref value to the tpConnections
        """
        for value in values:
            self.add_tpConnection(value)

    def remove_tpConnection(self, value):
        """
        Removes a single value from tpConnections
        """
        if value is not None:
            self.__tpConnections.remove(value)
            tpConnections_values = AutosarNode._add_or_get_xml_node(self._node, 'TP-CONNECTIONS', createNode = False)
            tpConnections_values.remove(value._node)
            value._parent = None #No parent
            value._update_path() #resets the path

    def remove_tpConnections(self, values):
        """
        Removes a list of value from tpConnections
        """
        for value in values:
            self.remove_tpConnection(value)

    def new_TpConnection(self, name=None):
        """
        Creates a new EthTpConnection under the EthTpConfig.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        EthTpConnection_obj = EthTpConnection()
        if isinstance(EthTpConnection_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('ETH-TP-CONNECTION')
        EthTpConnection_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        EthTpConnection_obj.name = name
        EthTpConnection_obj._node = xmlNode
        self.add_tpConnection(EthTpConnection_obj)
        return EthTpConnection_obj

    def get_children(self):
        children = super().get_children()
        children.extend(self.__tpConnections)
        return children

    def _update_path(self):
        """
        Updates the path of the EthTpConfig and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

