class SdgDef(ARElement):
    """
    A SdgDef groups several SdgClasses which belong to the same extension., , The concept of an SdgDef is similiar to an UML Profile.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'SDG-DEF'
        self.__sdgClass = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        sdgClass_nodes = self._node.findall('{*}SDG-CLASSES/*')
        for sdgClass_node in sdgClass_nodes:
            self.__sdgClass.add(SdgClass()._build(self, sdgClass_node))

        return self

    def get_sdgClass(self):
        return self.__sdgClass

    def add_sdgClas(self, value):
        """
        Adds a single value to the sdgClass
        """
        if value is not None:
            if any(v.name == value.name for v in self.__sdgClass):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, SdgClass) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of SdgClass or its sub-classes'.format(value))
            self.__sdgClass.add(value)
            sdgClass_values = AutosarNode._add_or_get_xml_node(self._node, 'SDG-CLASSES')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            sdgClass_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_sdgClass(self, values):
        """
        Adds a list of ref value to the sdgClass
        """
        for value in values:
            self.add_sdgClas(value)

    def remove_sdgClas(self, value):
        """
        Removes a single value from sdgClass
        """
        if value is not None:
            self.__sdgClass.remove(value)
            sdgClass_values = AutosarNode._add_or_get_xml_node(self._node, 'SDG-CLASSES', createNode = False)
            sdgClass_values.remove(value._node)
            value._parent = None #No parent
            value._update_path() #resets the path

    def remove_sdgClass(self, values):
        """
        Removes a list of value from sdgClass
        """
        for value in values:
            self.remove_sdgClas(value)

    def new_SdgClas(self, name=None):
        """
        Creates a new SdgClass under the SdgDef.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        SdgClass_obj = SdgClass()
        if isinstance(SdgClass_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('SDG-CLASS')
        SdgClass_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        SdgClass_obj.name = name
        SdgClass_obj._node = xmlNode
        self.add_sdgClas(SdgClass_obj)
        return SdgClass_obj

    def get_children(self):
        children = super().get_children()
        children.extend(self.__sdgClass)
        return children

    def _update_path(self):
        """
        Updates the path of the SdgDef and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

