class MixedContentForOverviewParagraph(ARObject):
    """
    This is the text model of a restricted paragraph item within a documentation. Such restricted paragraphs are used mainly for overview items, e.g. desc.
    """
    def __init__(self):
        super().__init__()
        self.__sups = None
        self.__subs = None
        self.__brs = set()
        self.__fts = set()
        self.__traces = set()
        self.__tts = set()
        self.__xrefs = set()
        self.__xrefTargets = set()
        self.__es = set()
        self.__ies = set()

        self.__mixedtext = None

    def _build(self, parent, node):
        super()._build(parent, node)
        sups_value = AutosarNode._get_node_text(node,'SUP')
        if sups_value is not None:
            self.__sups = datatype_utils.get_string_value(sups_value)

        subs_value = AutosarNode._get_node_text(node,'SUB')
        if subs_value is not None:
            self.__subs = datatype_utils.get_string_value(subs_value)

        brs_nodes = self._node.findall('{*}BRS/*')
        for brs_node in brs_nodes:
            self.__brs.add(Br()._build(self, brs_node))

        fts_nodes = self._node.findall('{*}FTS/*')
        for fts_node in fts_nodes:
            self.__fts.add(SlOverviewParagraph()._build(self, fts_node))

        tts_nodes = self._node.findall('{*}TTS/*')
        for tts_node in tts_nodes:
            self.__tts.add(Tt()._build(self, tts_node))

        xrefs_nodes = self._node.findall('{*}XREFS/*')
        for xrefs_node in xrefs_nodes:
            self.__xrefs.add(Xref()._build(self, xrefs_node))

        xrefTargets_nodes = self._node.findall('{*}XREF-TARGETS/*')
        for xrefTargets_node in xrefTargets_nodes:
            self.__xrefTargets.add(XrefTarget()._build(self, xrefTargets_node))

        es_nodes = self._node.findall('{*}ES/*')
        for es_node in es_nodes:
            self.__es.add(EmphasisText()._build(self, es_node))

        ies_nodes = self._node.findall('{*}IES/*')
        for ies_node in ies_nodes:
            self.__ies.add(IndexEntry()._build(self, ies_node))

        return self

    def _resolve_references(self):
        traces_nodes = self._node.findall('{*}TRACE-REFS/*')
        for node in traces_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__traces.add(ref_value)

