class LinConfigurableFrame(ARObject):
    """
    Assignment of messageIds to Frames. , This element shall be used for the LIN 2.0 Assign-Frame command.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'LIN-CONFIGURABLE-FRAME'
        self.__messageId = None
        self.__frame = None

    def _build(self, parent, node):
        super()._build(parent, node)
        messageId_value = AutosarNode._get_node_text(node,'MESSAGE-ID')
        if messageId_value is not None:
            self.__messageId = datatype_utils.get_int_value(messageId_value)

        return self

    def _resolve_references(self):
        frame_node = self._node.find('{*}FRAME-REF')
        if frame_node is not None and frame_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[frame_node.text]
            ref_value.referenced_by.add(self)
            self.__frame = ref_value

    def get_messageId(self):
        return self.__messageId

    def set_messageId(self, value):
        self.__messageId = value
        messageId_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'MESSAGE-ID')
        messageId_xml_node.text = str(value) if value is not None else ''

    def get_frame(self):
        return self.__frame

    def set_frame(self, value):
        """
        Adds a single value to the frame
        """
        if value is not None:
            if isinstance(value, LinFrame) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of LinFrame or its sub-classes'.format(value))
            if self.__frame is not None:
                self.__frame.referenced_by.remove(self)
            frame_value = AutosarNode._add_or_get_xml_node(self._node, 'FRAME-REF', value)
            frame_value.text = value.path
            frame_value.attrib['DEST'] = value.tag
            self.__frame = value
            value.referenced_by.add(self)
        elif self.__frame is not None:
            self.__frame.referenced_by.remove(self)
            self.__frame = None
            frame_value = AutosarNode._add_or_get_xml_node(self._node, 'FRAME-REF', createNode = False)
            if frame_value is not None:
                frame_value.referenced_by.remove(self)
                frame_value.text = ''

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['MessageId'] = self.__messageId
        property_values['Frame'] = self.__frame
        return property_values

    def _update_path(self):
        """
        Updates the path of the LinConfigurableFrame and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

class MappingConstraint(ARObject):
    """
    Different constraints that may be used to limit the mapping of SW components to applicable ECUs, Partitions or Cores depending on the mappingScope attribute.
    """
    def __init__(self):
        super().__init__()
        self.__introduction = None
        self.__variationPoint = None

    def _build(self, parent, node):
        super()._build(parent, node)
        introduction_node = self._node.find('{*}INTRODUCTION')
        if introduction_node is not None:
            self.__introduction = DocumentationBlock()._build(self, introduction_node)

        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            self.__variationPoint = VariationPoint()._build(self, variationPoint_node)

        return self

    def get_introduction(self):
        return self.__introduction

    def set_introduction(self, value):
        """
        Adds a single value to the introduction
        """
        if value is not None:
            if isinstance(value, DocumentationBlock) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of DocumentationBlock or its sub-classes'.format(value))
            if self.__introduction is not None:
                self._node.remove(self.__introduction._node)
            # if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            self._node.append(value._node)
            self.__introduction = value
            value._parent = self #set parent
            value._update_path() #updates the path
        elif self.__introduction is not None:
            self._node.remove(self.__introduction._node)
            self.__introduction = None
            self.__introduction._parent = None #No parent
            self.__introduction._update_path() #updates the path

    def get_variationPoint(self):
        return self.__variationPoint

    def set_variationPoint(self, value):
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))
