class LinTpNode(Identifiable):
    """
    TP Node (Sender or Receiver) provides the TP Address and the connection to the Topology description.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'LIN-TP-NODE'
        self.__maxNumberOfRespPendingFrames = None
        self.__p2Max = None
        self.__p2Timing = None
        self.__connector = None
        self.__tpAddress = None
        self.__variationPoint = None

    def _build(self, parent, node):
        super()._build(parent, node)
        maxNumberOfRespPendingFrames_value = AutosarNode._get_node_text(node,'MAX-NUMBER-OF-RESP-PENDING-FRAMES')
        if maxNumberOfRespPendingFrames_value is not None:
            self.__maxNumberOfRespPendingFrames = datatype_utils.get_int_value(maxNumberOfRespPendingFrames_value)

        p2Max_value = AutosarNode._get_node_text(node,'P-2-MAX')
        if p2Max_value is not None:
            self.__p2Max = datatype_utils.get_float_value(p2Max_value)

        p2Timing_value = AutosarNode._get_node_text(node,'P-2-TIMING')
        if p2Timing_value is not None:
            self.__p2Timing = datatype_utils.get_float_value(p2Timing_value)

        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            self.__variationPoint = VariationPoint()._build(self, variationPoint_node)

        return self

    def _resolve_references(self):
        connector_node = self._node.find('{*}CONNECTOR-REF')
        if connector_node is not None and connector_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[connector_node.text]
            ref_value.referenced_by.add(self)
            self.__connector = ref_value
        tpAddress_node = self._node.find('{*}TP-ADDRESS-REF')
