class BswModuleEntity(ExecutableEntity):
    """
    Specifies the smallest code fragment which can be described for a BSW module or cluster within AUTOSAR.
    """
    def __init__(self):
        super().__init__()
        self.__accessedModeGroups = set()
        self.__activationPoints = set()
        self.__callPoints = set()
        self.__calledEntries = set()
        self.__dataReceivePoints = set()
        self.__dataSendPoints = set()
        self.__implementedEntry = None
        self.__issuedTriggers = set()
        self.__managedModeGroups = set()
        self.__schedulerNamePrefix = None
        self.__variationPoint = None

    def _build(self, parent, node):
        super()._build(parent, node)
        accessedModeGroups_nodes = self._node.findall('{*}ACCESSED-MODE-GROUPS/*')
        for accessedModeGroups_node in accessedModeGroups_nodes:
            self.__accessedModeGroups.add(ModeDeclarationGroupPrototypeRefConditional()._build(self, accessedModeGroups_node))

        activationPoints_nodes = self._node.findall('{*}ACTIVATION-POINTS/*')
        for activationPoints_node in activationPoints_nodes:
            self.__activationPoints.add(BswInternalTriggeringPointRefConditional()._build(self, activationPoints_node))

        callPoints_obj_dict = {}
        callPoints_obj_dict['BSW-ASYNCHRONOUS-SERVER-CALL-POINT'] = 'BswAsynchronousServerCallPoint'
        callPoints_obj_dict['BSW-DIRECT-CALL-POINT'] = 'BswDirectCallPoint'
        callPoints_obj_dict['BSW-SYNCHRONOUS-SERVER-CALL-POINT'] = 'BswSynchronousServerCallPoint'
        callPoints_obj_dict['BSW-ASYNCHRONOUS-SERVER-CALL-RESULT-POINT'] = 'BswAsynchronousServerCallResultPoint'
        callPoints_nodes = self._node.findall('{*}CALL-POINTS/*')
        for callPoints_node in callPoints_nodes:
            self.__callPoints.add(__str_to_class__(callPoints_obj_dict[etree.QName(callPoints_node).localname])()._build(self, callPoints_node))

        calledEntries_nodes = self._node.findall('{*}CALLED-ENTRYS/*')
        for calledEntries_node in calledEntries_nodes:
            self.__calledEntries.add(BswModuleEntryRefConditional()._build(self, calledEntries_node))

        dataReceivePoints_nodes = self._node.findall('{*}DATA-RECEIVE-POINTS/*')
        for dataReceivePoints_node in dataReceivePoints_nodes:
            self.__dataReceivePoints.add(BswVariableAccess()._build(self, dataReceivePoints_node))

