class TDEventOccurrenceExpressionFormula(FormulaExpression):
    """
    This is an extension of the FormulaExpression for the AUTOSAR Timing Extensions., , A TDEventOccurrenceExpressionFormula provides the means to express the temporal characteristics of timing event occurrences in correlation with specific variable and argument values., , The formal definition of the extended functions (ExtUnaryFunctions) is described in detail in the AUTOSAR Timing Extensions.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'TD-EVENT-OCCURRENCE-EXPRESSION-FORMULA'
        self.__arguments = set()
        self.__events = set()
        self.__modes = set()
        self.__variables = set()

        self.__mixedtext = None

    def _build(self, parent, node):
        super()._build(parent, node)
        self.__mixedtext = node.text
        return self

    def _resolve_references(self):
        arguments_nodes = self._node.findall('{*}ARGUMENT-REFS/*')
        for node in arguments_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__arguments.add(ref_value)
        events_nodes = self._node.findall('{*}EVENT-REFS/*')
        for node in events_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__events.add(ref_value)
        modes_nodes = self._node.findall('{*}MODE-REFS/*')
        for node in modes_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__modes.add(ref_value)
        variables_nodes = self._node.findall('{*}VARIABLE-REFS/*')
        for node in variables_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__variables.add(ref_value)

    def get_arguments(self):
        return self.__arguments

    def add_argument(self, value):
        """
        Adds a single value to the arguments
        """
        if value is not None:
            if any(v.name == value.name for v in self.__arguments):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, AutosarOperationArgumentInstance) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of AutosarOperationArgumentInstance or its sub-classes'.format(value))
            self.__arguments.add(value)
            arguments_values = AutosarNode._add_or_get_xml_node(self._node, 'ARGUMENT-REFS')

            arguments_value = AutosarNode._add_or_get_xml_node(arguments_values, 'ARGUMENT-REF', value, forceCreate = True)
            arguments_value.text = value.path
            value.referenced_by.add(self)

    def set_arguments(self, values):
        """
        Adds a list of ref value to the arguments
        """
        for value in values:
            self.add_argument(value)

    def remove_argument(self, value):
        """
        Removes a single value from arguments
        """
        if value is not None:
            self.__arguments.remove(value)
            arguments_values = AutosarNode._add_or_get_xml_node(self._node, 'ARGUMENT-REFS', createNode = False)
            for arguments_value in self._node.findall('{*}ARGUMENT-REFS/*'):
                if arguments_value.text == value.path:
                    arguments_value.text = ''
                    arguments_values.remove(arguments_value)
                    value.referenced_by.remove(self)
                    break

