class KeywordSet(ARElement,AtpBlueprint,AtpBlueprintable):
    """
    This meta--class represents the ability to collect a set of predefined keywords.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'KEYWORD-SET'
        self.__keywords = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        keywords_nodes = self._node.findall('{*}KEYWORDS/*')
        for keywords_node in keywords_nodes:
            self.__keywords.add(Keyword()._build(self, keywords_node))

        return self

    def get_keywords(self):
        return self.__keywords

    def add_keyword(self, value):
        """
        Adds a single value to the keywords
        """
        if value is not None:
            if any(v.name == value.name for v in self.__keywords):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, Keyword) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of Keyword or its sub-classes'.format(value))
            self.__keywords.add(value)
            keywords_values = AutosarNode._add_or_get_xml_node(self._node, 'KEYWORDS')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            keywords_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_keywords(self, values):
        """
        Adds a list of ref value to the keywords
        """
        for value in values:
            self.add_keyword(value)

    def remove_keyword(self, value):
        """
        Removes a single value from keywords
        """
        if value is not None:
            self.__keywords.remove(value)
            keywords_values = AutosarNode._add_or_get_xml_node(self._node, 'KEYWORDS', createNode = False)
            keywords_values.remove(value._node)
            value._parent = None #No parent
            value._update_path() #resets the path

    def remove_keywords(self, values):
        """
        Removes a list of value from keywords
        """
        for value in values:
            self.remove_keyword(value)

    def new_Keyword(self, name=None):
        """
        Creates a new Keyword under the KeywordSet.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        Keyword_obj = Keyword()
        if isinstance(Keyword_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('KEYWORD')
        Keyword_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        Keyword_obj.name = name
        Keyword_obj._node = xmlNode
        self.add_keyword(Keyword_obj)
        return Keyword_obj

    def get_children(self):
        children = super().get_children()
        children.extend(self.__keywords)
        return children

    def _update_path(self):
        """
        Updates the path of the KeywordSet and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

