class DoIpRoutingActivation(Identifiable):
    """
    This meta-class defines a DoIP routing activation possibility that activates the routing to the referenced doIPTargetAddress. This means that the diagnostic request messages related to the specified doIPTargetAddress received by socketConnections that are referenced by the same DoIpInterface that aggregates this DoIpRoutingActivation are activated.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'DO-IP-ROUTING-ACTIVATION'
        self.__doIpTargetAddress = set()


    def _resolve_references(self):
        doIpTargetAddress_nodes = self._node.findall('{*}DO-IP-TARGET-ADDRESS-REFS/*')
        for node in doIpTargetAddress_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__doIpTargetAddress.add(ref_value)

    def get_doIpTargetAddress(self):
        return self.__doIpTargetAddress

    def add_doIpTargetAddres(self, value):
        """
        Adds a single value to the doIpTargetAddress
        """
        if value is not None:
            if any(v.name == value.name for v in self.__doIpTargetAddress):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, DoIpLogicTargetAddressProps) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of DoIpLogicTargetAddressProps or its sub-classes'.format(value))
            self.__doIpTargetAddress.add(value)
            doIpTargetAddress_values = AutosarNode._add_or_get_xml_node(self._node, 'DO-IP-TARGET-ADDRESS-REFS')

            doIpTargetAddress_value = AutosarNode._add_or_get_xml_node(doIpTargetAddress_values, 'DO-IP-TARGET-ADDRESS-REF', value, forceCreate = True)
            doIpTargetAddress_value.text = value.path
            value.referenced_by.add(self)

    def set_doIpTargetAddress(self, values):
        """
        Adds a list of ref value to the doIpTargetAddress
        """
        for value in values:
            self.add_doIpTargetAddres(value)

    def remove_doIpTargetAddres(self, value):
        """
        Removes a single value from doIpTargetAddress
        """
        if value is not None:
            self.__doIpTargetAddress.remove(value)
            doIpTargetAddress_values = AutosarNode._add_or_get_xml_node(self._node, 'DO-IP-TARGET-ADDRESS-REFS', createNode = False)
            for doIpTargetAddress_value in self._node.findall('{*}DO-IP-TARGET-ADDRESS-REFS/*'):
                if doIpTargetAddress_value.text == value.path:
                    doIpTargetAddress_value.text = ''
                    doIpTargetAddress_values.remove(doIpTargetAddress_value)
                    value.referenced_by.remove(self)
                    break

    def remove_doIpTargetAddress(self, values):
        """
        Removes a list of value from doIpTargetAddress
        """
        for value in values:
            self.remove_doIpTargetAddres(value)

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['DoIpTargetAddress'] = self.__doIpTargetAddress
        return property_values

    def _update_path(self):
        """
        Updates the path of the DoIpRoutingActivation and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

class EmphasisText(ARObject):
    """
    This is an emphasized text. As a compromise it contains some rendering oriented attributes such as color and font.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'EMPHASIS-TEXT'
        self.__color = None
        self.__font = None
        self.__subs = None
        self.__sups = None
        self.__type = None
        self.__tts = set()

        self.__mixedtext = None

    def _build(self, parent, node):
        super()._build(parent, node)
        color_value = AutosarNode._get_node_text(node,'COLOR')
        if color_value is not None:
            self.__color = datatype_utils.get_string_value(color_value)

        font_value = AutosarNode._get_node_text(node,'FONT')
        if font_value is not None:
            self.__font = EEnumFont.get(font_value)

        subs_value = AutosarNode._get_node_text(node,'SUB')
        if subs_value is not None:
            self.__subs = datatype_utils.get_string_value(subs_value)

        sups_value = AutosarNode._get_node_text(node,'SUP')
        if sups_value is not None:
            self.__sups = datatype_utils.get_string_value(sups_value)

        type_value = AutosarNode._get_node_text(node,'TYPE')
        if type_value is not None:
            self.__type = EEnum.get(type_value)

        tts_nodes = self._node.findall('{*}TTS/*')
        for tts_node in tts_nodes:
            self.__tts.add(Tt()._build(self, tts_node))

        self.__mixedtext = node.text
        return self

    def get_color(self):
        return self.__color

    def set_color(self, value):
        self.__color = value
        color_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'COLOR')
        color_xml_node.text = str(value) if value is not None else ''

    def get_font(self):
        return self.__font

    def set_font(self, value):
        self.__font = value
        font_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'FONT')
        font_xml_node.text = value.literal if value is not None else ''

    def get_subs(self):
        return self.__subs

    def set_subs(self, value):
        self.__subs = value
        subs_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'SUB')
        subs_xml_node.text = str(value) if value is not None else ''

    def get_sups(self):
        return self.__sups

    def set_sups(self, value):
        self.__sups = value
        sups_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'SUP')
        sups_xml_node.text = str(value) if value is not None else ''

    def get_type(self):
        return self.__type

    def set_type(self, value):
        self.__type = value
        type_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'TYPE')
        type_xml_node.text = value.literal if value is not None else ''

    def get_tts(self):
        return self.__tts

    def add_tt(self, value):
        """
        Adds a single value to the tts
        """
        if value is not None:
            if any(v.name == value.name for v in self.__tts):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, Tt) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of Tt or its sub-classes'.format(value))
            self.__tts.add(value)
            tts_values = AutosarNode._add_or_get_xml_node(self._node, 'TTS')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            tts_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_tts(self, values):
        """
        Adds a list of ref value to the tts
        """
        for value in values:
            self.add_tt(value)

    def remove_tt(self, value):
        """
        Removes a single value from tts
        """
        if value is not None:
            self.__tts.remove(value)
            tts_values = AutosarNode._add_or_get_xml_node(self._node, 'TTS', createNode = False)
            tts_values.remove(value._node)
            value._parent = None #No parent
            value._update_path() #resets the path

    def remove_tts(self, values):
        """
        Removes a list of value from tts
        """
        for value in values:
            self.remove_tt(value)

    def new_Tt(self, name=None):
        """
        Creates a new Tt under the EmphasisText.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        Tt_obj = Tt()
        if isinstance(Tt_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('TT')
        Tt_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        Tt_obj.name = name
        Tt_obj._node = xmlNode
        self.add_tt(Tt_obj)
        return Tt_obj

    def get(self):
        return self.__mixedtext

    def set(self, text):
        self.__mixedtext = text
        if text is not None:
            self._node.text = str(text)
        else:
            self._node.text = ''

    def _add_mandatory_attr(self, node, name = None):
        super()._add_mandatory_attr(node, name)
        subs_node = etree.SubElement(node, 'SUB')
        self.__subs = None
        subs_node.text = ''
        sups_node = etree.SubElement(node, 'SUP')
        self.__sups = None
        sups_node.text = ''

    def get_children(self):
        children = super().get_children()
        children.extend(self.__tts)
        return children

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['Color'] = self.__color
        property_values['Font'] = self.__font
        property_values['Subs'] = self.__subs
        property_values['Sups'] = self.__sups
        property_values['Type'] = self.__type
        property_values['Value'] = self.__mixedtext
        return property_values

    def _update_path(self):
        """
        Updates the path of the EmphasisText and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

