class SwComponentType(ARElement,AtpBlueprint,AtpBlueprintable,AtpType):
    """
    Base class for AUTOSAR software components.
    """
    def __init__(self):
        super().__init__()
        self.__swComponentDocumentations = set()
        self.__consistencyNeeds = set()
        self.__ports = set()
        self.__portGroups = set()
        self.__unitGroups = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        swComponentDocumentations_nodes = self._node.findall('{*}SW-COMPONENT-DOCUMENTATIONS/*')
        for swComponentDocumentations_node in swComponentDocumentations_nodes:
            self.__swComponentDocumentations.add(SwComponentDocumentation()._build(self, swComponentDocumentations_node))

        consistencyNeeds_nodes = self._node.findall('{*}CONSISTENCY-NEEDSS/*')
        for consistencyNeeds_node in consistencyNeeds_nodes:
            self.__consistencyNeeds.add(ConsistencyNeeds()._build(self, consistencyNeeds_node))

        ports_obj_dict = {}
        ports_obj_dict['PR-PORT-PROTOTYPE'] = 'PRPortPrototype'
        ports_obj_dict['R-PORT-PROTOTYPE'] = 'RPortPrototype'
        ports_obj_dict['P-PORT-PROTOTYPE'] = 'PPortPrototype'
        ports_nodes = self._node.findall('{*}PORTS/*')
        for ports_node in ports_nodes:
            self.__ports.add(__str_to_class__(ports_obj_dict[etree.QName(ports_node).localname])()._build(self, ports_node))

        portGroups_nodes = self._node.findall('{*}PORT-GROUPS/*')
        for portGroups_node in portGroups_nodes:
            self.__portGroups.add(PortGroup()._build(self, portGroups_node))

        return self

    def _resolve_references(self):
        unitGroups_nodes = self._node.findall('{*}UNIT-GROUP-REFS/*')
        for node in unitGroups_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__unitGroups.add(ref_value)

    def get_swComponentDocumentations(self):
        return self.__swComponentDocumentations

    def add_swComponentDocumentation(self, value):
        """
        Adds a single value to the swComponentDocumentations
        """
        if value is not None:
            if any(v.name == value.name for v in self.__swComponentDocumentations):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, SwComponentDocumentation) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of SwComponentDocumentation or its sub-classes'.format(value))
            self.__swComponentDocumentations.add(value)
            swComponentDocumentations_values = AutosarNode._add_or_get_xml_node(self._node, 'SW-COMPONENT-DOCUMENTATIONS')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            swComponentDocumentations_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_swComponentDocumentations(self, values):
        """
        Adds a list of ref value to the swComponentDocumentations
        """
        for value in values:
            self.add_swComponentDocumentation(value)

