class DiagnosticAbstractDataIdentifier(DiagnosticCommonElement):
    """
    This meta-class represents an abstract base class for the modeling of a diagnostic data identifier (DID).
    """
    def __init__(self):
        super().__init__()
        self.__id = None

    def _build(self, parent, node):
        super()._build(parent, node)
        id_node = self._node.find('{*}ID')
        if id_node is not None:
            self.__id = PositiveIntegerValueVariationPoint()._build(self, id_node)

        return self

    def get_id(self):
        return self.__id

    def set_id(self, value):
        """
        Adds a single value to the id
        """
        if value is not None:
            if isinstance(value, PositiveIntegerValueVariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of PositiveIntegerValueVariationPoint or its sub-classes'.format(value))
            if self.__id is not None:
                self._node.remove(self.__id._node)
            # if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            self._node.append(value._node)
            self.__id = value
            value._parent = self #set parent
            value._update_path() #updates the path
        elif self.__id is not None:
            self._node.remove(self.__id._node)
            self.__id = None
            self.__id._parent = None #No parent
            self.__id._update_path() #updates the path

    def new_Id(self, name=None):
        """
        Creates a new PositiveIntegerValueVariationPoint under the DiagnosticAbstractDataIdentifier.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        PositiveIntegerValueVariationPoint_obj = PositiveIntegerValueVariationPoint()
        if isinstance(PositiveIntegerValueVariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('ID')
        PositiveIntegerValueVariationPoint_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        PositiveIntegerValueVariationPoint_obj.name = name
        PositiveIntegerValueVariationPoint_obj._node = xmlNode
        self.set_id(PositiveIntegerValueVariationPoint_obj)
        return PositiveIntegerValueVariationPoint_obj

    def get_children(self):
        children = super().get_children()
        if self.__id is not None:
            children.append(self.__id)
        return children

    def _update_path(self):
        """
        Updates the path of the DiagnosticAbstractDataIdentifier and its children.
        """
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

