class IamModuleInstantiation(NonOsModuleInstantiation):
    """
    This meta-class represents the ability to define a definition of an IAM instantiation.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'IAM-MODULE-INSTANTIATION'
        self.__localComAccessControlEnabled = None
        self.__remoteAccessControlEnabled = None
        self.__grants = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        localComAccessControlEnabled_value = AutosarNode._get_node_text(node,'LOCAL-COM-ACCESS-CONTROL-ENABLED')
        if localComAccessControlEnabled_value is not None:
            self.__localComAccessControlEnabled = datatype_utils.get_bool_value(localComAccessControlEnabled_value)

        remoteAccessControlEnabled_value = AutosarNode._get_node_text(node,'REMOTE-ACCESS-CONTROL-ENABLED')
        if remoteAccessControlEnabled_value is not None:
            self.__remoteAccessControlEnabled = datatype_utils.get_bool_value(remoteAccessControlEnabled_value)

        return self

    def _resolve_references(self):
        grants_nodes = self._node.findall('{*}GRANT-REFS/*')
        for node in grants_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__grants.add(ref_value)

    def get_localComAccessControlEnabled(self):
        return self.__localComAccessControlEnabled

    def set_localComAccessControlEnabled(self, value):
        self.__localComAccessControlEnabled = value
        localComAccessControlEnabled_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'LOCAL-COM-ACCESS-CONTROL-ENABLED')
        localComAccessControlEnabled_xml_node.text = 'true' if value is True else 'false'

    def get_remoteAccessControlEnabled(self):
        return self.__remoteAccessControlEnabled

    def set_remoteAccessControlEnabled(self, value):
        self.__remoteAccessControlEnabled = value
        remoteAccessControlEnabled_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'REMOTE-ACCESS-CONTROL-ENABLED')
        remoteAccessControlEnabled_xml_node.text = 'true' if value is True else 'false'

    def get_grants(self):
        return self.__grants

    def add_grant(self, value):
        """
        Adds a single value to the grants
        """
        if value is not None:
            if any(v.name == value.name for v in self.__grants):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, Grant) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of Grant or its sub-classes'.format(value))
            self.__grants.add(value)
            grants_values = AutosarNode._add_or_get_xml_node(self._node, 'GRANT-REFS')

            grants_value = AutosarNode._add_or_get_xml_node(grants_values, 'GRANT-REF', value, forceCreate = True)
            grants_value.text = value.path
            value.referenced_by.add(self)

    def set_grants(self, values):
        """
        Adds a list of ref value to the grants
        """
        for value in values:
            self.add_grant(value)

    def remove_grant(self, value):
        """
        Removes a single value from grants
        """
        if value is not None:
            self.__grants.remove(value)
            grants_values = AutosarNode._add_or_get_xml_node(self._node, 'GRANT-REFS', createNode = False)
            for grants_value in self._node.findall('{*}GRANT-REFS/*'):
                if grants_value.text == value.path:
                    grants_value.text = ''
                    grants_values.remove(grants_value)
                    value.referenced_by.remove(self)
                    break

    def remove_grants(self, values):
        """
        Removes a list of value from grants
        """
        for value in values:
            self.remove_grant(value)

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['LocalComAccessControlEnabled'] = self.__localComAccessControlEnabled
        property_values['RemoteAccessControlEnabled'] = self.__remoteAccessControlEnabled
        property_values['Grants'] = self.__grants
        return property_values

    def _update_path(self):
        """
        Updates the path of the IamModuleInstantiation and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

