        for node in applicationPartitions_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__applicationPartitions.add(ref_value)
        ecuPartition_node = self._node.find('{*}ECU-PARTITION-REF')
        if ecuPartition_node is not None and ecuPartition_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[ecuPartition_node.text]
            ref_value.referenced_by.add(self)
