class StaticPart(MultiplexedPart):
    """
    Some parts/signals of the I-PDU may be the same regardless of the selector field. Such a part is called static part. The static part is optional.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'STATIC-PART'
        self.__iPdu = None
        self.__variationPoint = None

    def _build(self, parent, node):
        super()._build(parent, node)
        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            self.__variationPoint = VariationPoint()._build(self, variationPoint_node)

        return self

    def _resolve_references(self):
        iPdu_node = self._node.find('{*}I-PDU-REF')
        if iPdu_node is not None and iPdu_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[iPdu_node.text]
            ref_value.referenced_by.add(self)
            self.__iPdu = ref_value

    def get_iPdu(self):
        return self.__iPdu

    def set_iPdu(self, value):
        """
        Adds a single value to the iPdu
        """
        if value is not None:
            if isinstance(value, ISignalIPdu) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ISignalIPdu or its sub-classes'.format(value))
            if self.__iPdu is not None:
                self.__iPdu.referenced_by.remove(self)
            iPdu_value = AutosarNode._add_or_get_xml_node(self._node, 'I-PDU-REF', value)
            iPdu_value.text = value.path
            iPdu_value.attrib['DEST'] = value.tag
            self.__iPdu = value
            value.referenced_by.add(self)
        elif self.__iPdu is not None:
            self.__iPdu.referenced_by.remove(self)
            self.__iPdu = None
            iPdu_value = AutosarNode._add_or_get_xml_node(self._node, 'I-PDU-REF', createNode = False)
            if iPdu_value is not None:
                iPdu_value.referenced_by.remove(self)
                iPdu_value.text = ''

    def get_variationPoint(self):
        return self.__variationPoint

    def set_variationPoint(self, value):
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))
            if self.__variationPoint is not None:
                self._node.remove(self.__variationPoint._node)
            # if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            self._node.append(value._node)
            self.__variationPoint = value
            value._parent = self #set parent
            value._update_path() #updates the path
        elif self.__variationPoint is not None:
            self._node.remove(self.__variationPoint._node)
            self.__variationPoint = None
            self.__variationPoint._parent = None #No parent
            self.__variationPoint._update_path() #updates the path

    def new_VariationPoint(self, name=None):
        """
        Creates a new VariationPoint under the StaticPart.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        VariationPoint_obj = VariationPoint()
        if isinstance(VariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('VARIATION-POINT')
        VariationPoint_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        VariationPoint_obj.name = name
        VariationPoint_obj._node = xmlNode
        self.set_variationPoint(VariationPoint_obj)
        return VariationPoint_obj

    def get_children(self):
        children = super().get_children()
        if self.__variationPoint is not None:
            children.append(self.__variationPoint)
        return children

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['IPdu'] = self.__iPdu
        return property_values

    def _update_path(self):
        """
        Updates the path of the StaticPart and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

class RptExecutableEntityEvent(Identifiable):
    """
    This describes an ExecutableEntity event instance which can be bypassed.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'RPT-EXECUTABLE-ENTITY-EVENT'
        self.__rptEventId = None
        self.__executionContexts = set()
        self.__mcDataAssignments = set()
        self.__rptExecutableEntityProperties = None
        self.__rptImplPolicy = None
        self.__rptServicePointPosts = set()
        self.__rptServicePointPres = set()
        self.__variationPoint = None

    def _build(self, parent, node):
        super()._build(parent, node)
        rptEventId_value = AutosarNode._get_node_text(node,'RPT-EVENT-ID')
        if rptEventId_value is not None:
            self.__rptEventId = datatype_utils.get_int_value(rptEventId_value)

        mcDataAssignments_nodes = self._node.findall('{*}MC-DATA-ASSIGNMENTS/*')
        for mcDataAssignments_node in mcDataAssignments_nodes:
            self.__mcDataAssignments.add(RoleBasedMcDataAssignment()._build(self, mcDataAssignments_node))

        rptExecutableEntityProperties_node = self._node.find('{*}RPT-EXECUTABLE-ENTITY-PROPERTIES')
        if rptExecutableEntityProperties_node is not None:
            self.__rptExecutableEntityProperties = RptExecutableEntityProperties()._build(self, rptExecutableEntityProperties_node)

        rptImplPolicy_node = self._node.find('{*}RPT-IMPL-POLICY')
        if rptImplPolicy_node is not None:
            self.__rptImplPolicy = RptImplPolicy()._build(self, rptImplPolicy_node)

        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            self.__variationPoint = VariationPoint()._build(self, variationPoint_node)

