class PduToFrameMapping(Identifiable):
    """
    A PduToFrameMapping defines the composition of Pdus in each frame.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'PDU-TO-FRAME-MAPPING'
        self.__packingByteOrder = None
        self.__startPosition = None
        self.__updateIndicationBitPosition = None
        self.__pdu = None
        self.__variationPoint = None

    def _build(self, parent, node):
        super()._build(parent, node)
        packingByteOrder_value = AutosarNode._get_node_text(node,'PACKING-BYTE-ORDER')
        if packingByteOrder_value is not None:
            self.__packingByteOrder = ByteOrderEnum.get(packingByteOrder_value)

        startPosition_value = AutosarNode._get_node_text(node,'START-POSITION')
        if startPosition_value is not None:
            self.__startPosition = datatype_utils.get_int_value(startPosition_value)

        updateIndicationBitPosition_value = AutosarNode._get_node_text(node,'UPDATE-INDICATION-BIT-POSITION')
        if updateIndicationBitPosition_value is not None:
            self.__updateIndicationBitPosition = datatype_utils.get_int_value(updateIndicationBitPosition_value)

        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            self.__variationPoint = VariationPoint()._build(self, variationPoint_node)

        return self

    def _resolve_references(self):
        pdu_node = self._node.find('{*}PDU-REF')
        if pdu_node is not None and pdu_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[pdu_node.text]
            ref_value.referenced_by.add(self)
            self.__pdu = ref_value

