class DiagnosticDataIdentifierSet(DiagnosticCommonElement):
    """
    This represents the ability to define a list of DiagnosticDataIdentifiers that can be reused in different contexts.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'DIAGNOSTIC-DATA-IDENTIFIER-SET'
        self.__dataIdentifiers = set()


    def _resolve_references(self):
        dataIdentifiers_nodes = self._node.findall('{*}DATA-IDENTIFIER-REFS/*')
        for node in dataIdentifiers_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__dataIdentifiers.add(ref_value)

    def get_dataIdentifiers(self):
        return self.__dataIdentifiers

    def add_dataIdentifier(self, value):
        """
        Adds a single value to the dataIdentifiers
        """
        if value is not None:
            if any(v.name == value.name for v in self.__dataIdentifiers):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, DiagnosticDataIdentifier) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of DiagnosticDataIdentifier or its sub-classes'.format(value))
            self.__dataIdentifiers.add(value)
            dataIdentifiers_values = AutosarNode._add_or_get_xml_node(self._node, 'DATA-IDENTIFIER-REFS')

            dataIdentifiers_value = AutosarNode._add_or_get_xml_node(dataIdentifiers_values, 'DATA-IDENTIFIER-REF', value, forceCreate = True)
            dataIdentifiers_value.text = value.path
            value.referenced_by.add(self)

    def set_dataIdentifiers(self, values):
        """
        Adds a list of ref value to the dataIdentifiers
        """
        for value in values:
            self.add_dataIdentifier(value)

    def remove_dataIdentifier(self, value):
        """
        Removes a single value from dataIdentifiers
        """
        if value is not None:
            self.__dataIdentifiers.remove(value)
            dataIdentifiers_values = AutosarNode._add_or_get_xml_node(self._node, 'DATA-IDENTIFIER-REFS', createNode = False)
            for dataIdentifiers_value in self._node.findall('{*}DATA-IDENTIFIER-REFS/*'):
                if dataIdentifiers_value.text == value.path:
                    dataIdentifiers_value.text = ''
                    dataIdentifiers_values.remove(dataIdentifiers_value)
                    value.referenced_by.remove(self)
                    break

    def remove_dataIdentifiers(self, values):
        """
        Removes a list of value from dataIdentifiers
        """
        for value in values:
            self.remove_dataIdentifier(value)

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['DataIdentifiers'] = self.__dataIdentifiers
        return property_values

    def _update_path(self):
        """
        Updates the path of the DiagnosticDataIdentifierSet and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

