class TriggerPortAnnotation(GeneralAnnotation):
    """
    Annotation to a port used for calibration regarding a certain Trigger.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'TRIGGER-PORT-ANNOTATION'
        self.__trigger = None


    def _resolve_references(self):
        trigger_node = self._node.find('{*}TRIGGER-REF')
        if trigger_node is not None and trigger_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[trigger_node.text]
            ref_value.referenced_by.add(self)
            self.__trigger = ref_value

    def get_trigger(self):
        return self.__trigger

    def set_trigger(self, value):
        """
        Adds a single value to the trigger
        """
        if value is not None:
            if isinstance(value, Trigger) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of Trigger or its sub-classes'.format(value))
            if self.__trigger is not None:
                self.__trigger.referenced_by.remove(self)
            trigger_value = AutosarNode._add_or_get_xml_node(self._node, 'TRIGGER-REF', value)
            trigger_value.text = value.path
            trigger_value.attrib['DEST'] = value.tag
            self.__trigger = value
            value.referenced_by.add(self)
        elif self.__trigger is not None:
            self.__trigger.referenced_by.remove(self)
            self.__trigger = None
            trigger_value = AutosarNode._add_or_get_xml_node(self._node, 'TRIGGER-REF', createNode = False)
            if trigger_value is not None:
                trigger_value.referenced_by.remove(self)
                trigger_value.text = ''

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['Trigger'] = self.__trigger
        return property_values

    def _update_path(self):
        """
        Updates the path of the TriggerPortAnnotation and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

