class ConcretePatternEventTriggering(EventTriggeringConstraint):
    """
    The ConcretePatternEventTriggering describes the behavior of an event, which occurs following a precisely known pattern.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'CONCRETE-PATTERN-EVENT-TRIGGERING'
        self.__patternJitter = None
        self.__patternPeriod = None
        self.__offsets = set()
        self.__patternLength = None

    def _build(self, parent, node):
        super()._build(parent, node)
        patternJitter_node = self._node.find('{*}PATTERN-JITTER')
        if patternJitter_node is not None:
            self.__patternJitter = MultidimensionalTime()._build(self, patternJitter_node)

        patternPeriod_node = self._node.find('{*}PATTERN-PERIOD')
        if patternPeriod_node is not None:
            self.__patternPeriod = MultidimensionalTime()._build(self, patternPeriod_node)

        offsets_nodes = self._node.findall('{*}OFFSETS/*')
        for offsets_node in offsets_nodes:
            self.__offsets.add(MultidimensionalTime()._build(self, offsets_node))

        patternLength_node = self._node.find('{*}PATTERN-LENGTH')
        if patternLength_node is not None:
            self.__patternLength = MultidimensionalTime()._build(self, patternLength_node)

        return self

    def get_patternJitter(self):
        return self.__patternJitter

    def set_patternJitter(self, value):
        """
        Adds a single value to the patternJitter
        """
        if value is not None:
            if isinstance(value, MultidimensionalTime) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of MultidimensionalTime or its sub-classes'.format(value))
            if self.__patternJitter is not None:
                self._node.remove(self.__patternJitter._node)
            # if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            self._node.append(value._node)
            self.__patternJitter = value
            value._parent = self #set parent
            value._update_path() #updates the path
        elif self.__patternJitter is not None:
            self._node.remove(self.__patternJitter._node)
            self.__patternJitter = None
            self.__patternJitter._parent = None #No parent
            self.__patternJitter._update_path() #updates the path

    def get_patternPeriod(self):
        return self.__patternPeriod

    def set_patternPeriod(self, value):
        """
        Adds a single value to the patternPeriod
        """
        if value is not None:
            if isinstance(value, MultidimensionalTime) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of MultidimensionalTime or its sub-classes'.format(value))
            if self.__patternPeriod is not None:
                self._node.remove(self.__patternPeriod._node)
            # if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            self._node.append(value._node)
            self.__patternPeriod = value
            value._parent = self #set parent
            value._update_path() #updates the path
        elif self.__patternPeriod is not None:
            self._node.remove(self.__patternPeriod._node)
            self.__patternPeriod = None
            self.__patternPeriod._parent = None #No parent
            self.__patternPeriod._update_path() #updates the path

    def get_offsets(self):
        return self.__offsets

    def add_offset(self, value):
        """
        Adds a single value to the offsets
        """
        if value is not None:
            if any(v.name == value.name for v in self.__offsets):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, MultidimensionalTime) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of MultidimensionalTime or its sub-classes'.format(value))
            self.__offsets.add(value)
            offsets_values = AutosarNode._add_or_get_xml_node(self._node, 'OFFSETS')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            offsets_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_offsets(self, values):
        """
        Adds a list of ref value to the offsets
        """
        for value in values:
            self.add_offset(value)

    def remove_offset(self, value):
        """
        Removes a single value from offsets
        """
        if value is not None:
            self.__offsets.remove(value)
            offsets_values = AutosarNode._add_or_get_xml_node(self._node, 'OFFSETS', createNode = False)
            offsets_values.remove(value._node)
            value._parent = None #No parent
            value._update_path() #resets the path

    def remove_offsets(self, values):
        """
        Removes a list of value from offsets
        """
        for value in values:
            self.remove_offset(value)

    def get_patternLength(self):
        return self.__patternLength

    def set_patternLength(self, value):
        """
        Adds a single value to the patternLength
        """
        if value is not None:
            if isinstance(value, MultidimensionalTime) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of MultidimensionalTime or its sub-classes'.format(value))
            if self.__patternLength is not None:
                self._node.remove(self.__patternLength._node)
            # if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            self._node.append(value._node)
            self.__patternLength = value
            value._parent = self #set parent
            value._update_path() #updates the path
        elif self.__patternLength is not None:
            self._node.remove(self.__patternLength._node)
            self.__patternLength = None
            self.__patternLength._parent = None #No parent
            self.__patternLength._update_path() #updates the path

