class EvaluatedVariantSet(ARElement):
    """
    This meta class represents the ability to express if a set of ARElements is able to support one or more particular variants., , In other words, for a given set of evaluatedElements this meta class represents a table of evaluated variants, where each PredefinedVariant represents one column. In this column each descendant swSystemconstantValue resp. postbuildVariantCriterionValue represents one entry., , In a graphical representation each swSystemconstantValueSet / postBuildVariantCriterionValueSet could be used as an intermediate headline in the table column., , If the approvalStatus is "APPROVED" it expresses that the collection of CollectableElements is known be valid for the given evaluatedVariants., , Note that the EvaluatedVariantSet is a CollectableElement. This allows to establish a hierarchy of EvaluatedVariantSets.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'EVALUATED-VARIANT-SET'
        self.__approvalStatus = None
        self.__evaluatedElements = set()
        self.__evaluatedVariants = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        approvalStatus_value = AutosarNode._get_node_text(node,'APPROVAL-STATUS')
        if approvalStatus_value is not None:
            self.__approvalStatus = datatype_utils.get_string_value(approvalStatus_value)

        return self

    def _resolve_references(self):
        evaluatedElements_nodes = self._node.findall('{*}EVALUATED-ELEMENT-REFS/*')
        for node in evaluatedElements_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__evaluatedElements.add(ref_value)
        evaluatedVariants_nodes = self._node.findall('{*}EVALUATED-VARIANT-REFS/*')
        for node in evaluatedVariants_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__evaluatedVariants.add(ref_value)

    def get_approvalStatus(self):
        return self.__approvalStatus

    def set_approvalStatus(self, value):
        self.__approvalStatus = value
        approvalStatus_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'APPROVAL-STATUS')
        approvalStatus_xml_node.text = str(value) if value is not None else ''

    def get_evaluatedElements(self):
        return self.__evaluatedElements

    def add_evaluatedElement(self, value):
        """
        Adds a single value to the evaluatedElements
        """
        if value is not None:
            if any(v.name == value.name for v in self.__evaluatedElements):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, CollectableElement) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of CollectableElement or its sub-classes'.format(value))
            self.__evaluatedElements.add(value)
            evaluatedElements_values = AutosarNode._add_or_get_xml_node(self._node, 'EVALUATED-ELEMENT-REFS')

            evaluatedElements_value = AutosarNode._add_or_get_xml_node(evaluatedElements_values, 'EVALUATED-ELEMENT-REF', value, forceCreate = True)
            evaluatedElements_value.text = value.path
            value.referenced_by.add(self)

    def set_evaluatedElements(self, values):
        """
        Adds a list of ref value to the evaluatedElements
        """
        for value in values:
            self.add_evaluatedElement(value)

    def remove_evaluatedElement(self, value):
        """
        Removes a single value from evaluatedElements
        """
        if value is not None:
            self.__evaluatedElements.remove(value)
            evaluatedElements_values = AutosarNode._add_or_get_xml_node(self._node, 'EVALUATED-ELEMENT-REFS', createNode = False)
            for evaluatedElements_value in self._node.findall('{*}EVALUATED-ELEMENT-REFS/*'):
                if evaluatedElements_value.text == value.path:
                    evaluatedElements_value.text = ''
                    evaluatedElements_values.remove(evaluatedElements_value)
                    value.referenced_by.remove(self)
                    break

    def remove_evaluatedElements(self, values):
        """
        Removes a list of value from evaluatedElements
        """
        for value in values:
            self.remove_evaluatedElement(value)

    def get_evaluatedVariants(self):
        return self.__evaluatedVariants

    def add_evaluatedVariant(self, value):
        """
        Adds a single value to the evaluatedVariants
        """
        if value is not None:
            if any(v.name == value.name for v in self.__evaluatedVariants):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, PredefinedVariant) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of PredefinedVariant or its sub-classes'.format(value))
            self.__evaluatedVariants.add(value)
            evaluatedVariants_values = AutosarNode._add_or_get_xml_node(self._node, 'EVALUATED-VARIANT-REFS')

            evaluatedVariants_value = AutosarNode._add_or_get_xml_node(evaluatedVariants_values, 'EVALUATED-VARIANT-REF', value, forceCreate = True)
            evaluatedVariants_value.text = value.path
            value.referenced_by.add(self)

    def set_evaluatedVariants(self, values):
        """
        Adds a list of ref value to the evaluatedVariants
        """
        for value in values:
            self.add_evaluatedVariant(value)

    def remove_evaluatedVariant(self, value):
        """
        Removes a single value from evaluatedVariants
        """
        if value is not None:
            self.__evaluatedVariants.remove(value)
            evaluatedVariants_values = AutosarNode._add_or_get_xml_node(self._node, 'EVALUATED-VARIANT-REFS', createNode = False)
            for evaluatedVariants_value in self._node.findall('{*}EVALUATED-VARIANT-REFS/*'):
                if evaluatedVariants_value.text == value.path:
                    evaluatedVariants_value.text = ''
                    evaluatedVariants_values.remove(evaluatedVariants_value)
                    value.referenced_by.remove(self)
                    break

    def remove_evaluatedVariants(self, values):
        """
        Removes a list of value from evaluatedVariants
        """
        for value in values:
            self.remove_evaluatedVariant(value)

    def _add_mandatory_attr(self, node, name = None):
        super()._add_mandatory_attr(node, name)
        approvalStatus_node = etree.SubElement(node, 'APPROVAL-STATUS')
        self.__approvalStatus = None
        approvalStatus_node.text = ''

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['ApprovalStatus'] = self.__approvalStatus
        property_values['EvaluatedElements'] = self.__evaluatedElements
        property_values['EvaluatedVariants'] = self.__evaluatedVariants
        return property_values

    def _update_path(self):
        """
        Updates the path of the EvaluatedVariantSet and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

class ValueSpecification(ARObject):
    """
    Base class for expressions leading to a value which can be used to initialize a data object.
    """
    def __init__(self):
        super().__init__()
        self.__shortLabel = None
        self.__variationPoint = None

    def _build(self, parent, node):
        super()._build(parent, node)
        shortLabel_value = AutosarNode._get_node_text(node,'SHORT-LABEL')
        if shortLabel_value is not None:
            self.__shortLabel = datatype_utils.get_string_value(shortLabel_value)

        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            self.__variationPoint = VariationPoint()._build(self, variationPoint_node)

        return self

    def get_shortLabel(self):
        return self.__shortLabel

    def set_shortLabel(self, value):
        self.__shortLabel = value
        shortLabel_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'SHORT-LABEL')
        shortLabel_xml_node.text = str(value) if value is not None else ''

    def get_variationPoint(self):
        return self.__variationPoint

    def set_variationPoint(self, value):
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))
            if self.__variationPoint is not None:
                self._node.remove(self.__variationPoint._node)
            # if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            self._node.append(value._node)
            self.__variationPoint = value
            value._parent = self #set parent
            value._update_path() #updates the path
        elif self.__variationPoint is not None:
            self._node.remove(self.__variationPoint._node)
            self.__variationPoint = None
            self.__variationPoint._parent = None #No parent
            self.__variationPoint._update_path() #updates the path

    def new_VariationPoint(self, name=None):
        """
        Creates a new VariationPoint under the ValueSpecification.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        VariationPoint_obj = VariationPoint()
        if isinstance(VariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('VARIATION-POINT')
        VariationPoint_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        VariationPoint_obj.name = name
        VariationPoint_obj._node = xmlNode
        self.set_variationPoint(VariationPoint_obj)
        return VariationPoint_obj

    def get_children(self):
        children = super().get_children()
        if self.__variationPoint is not None:
            children.append(self.__variationPoint)
        return children

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['ShortLabel'] = self.__shortLabel
        return property_values

    def _update_path(self):
        """
        Updates the path of the ValueSpecification and its children.
        """
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

