class RecordValueSpecification(CompositeValueSpecification):
    """
    Specifies the values for a record.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'RECORD-VALUE-SPECIFICATION'
        self.__fields = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        fields_obj_dict = {}
        fields_obj_dict['TEXT-VALUE-SPECIFICATION'] = 'TextValueSpecification'
        fields_obj_dict['COMPOSITE-RULE-BASED-VALUE-SPECIFICATION'] = 'CompositeRuleBasedValueSpecification'
        fields_obj_dict['APPLICATION-ASSOC-MAP-VALUE-SPECIFICATION'] = 'ApplicationAssocMapValueSpecification'
        fields_obj_dict['NOT-AVAILABLE-VALUE-SPECIFICATION'] = 'NotAvailableValueSpecification'
        fields_obj_dict['NUMERICAL-RULE-BASED-VALUE-SPECIFICATION'] = 'NumericalRuleBasedValueSpecification'
        fields_obj_dict['NUMERICAL-VALUE-SPECIFICATION'] = 'NumericalValueSpecification'
        fields_obj_dict['REFERENCE-VALUE-SPECIFICATION'] = 'ReferenceValueSpecification'
        fields_obj_dict['APPLICATION-VALUE-SPECIFICATION'] = 'ApplicationValueSpecification'
        fields_obj_dict['APPLICATION-RULE-BASED-VALUE-SPECIFICATION'] = 'ApplicationRuleBasedValueSpecification'
        fields_obj_dict['CONSTANT-REFERENCE'] = 'ConstantReference'
        fields_obj_dict['RECORD-VALUE-SPECIFICATION'] = 'RecordValueSpecification'
        fields_obj_dict['ARRAY-VALUE-SPECIFICATION'] = 'ArrayValueSpecification'
        fields_nodes = self._node.findall('{*}FIELDS/*')
        for fields_node in fields_nodes:
            self.__fields.add(__str_to_class__(fields_obj_dict[etree.QName(fields_node).localname])()._build(self, fields_node))

        return self

    def get_fields(self):
        return self.__fields

    def add_field(self, value):
        """
        Adds a single value to the fields
        """
        if value is not None:
            if any(v.name == value.name for v in self.__fields):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, ValueSpecification) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ValueSpecification or its sub-classes'.format(value))
            self.__fields.add(value)
            fields_values = AutosarNode._add_or_get_xml_node(self._node, 'FIELDS')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            fields_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_fields(self, values):
        """
        Adds a list of ref value to the fields
        """
        for value in values:
            self.add_field(value)

    def remove_field(self, value):
        """
        Removes a single value from fields
        """
        if value is not None:
            self.__fields.remove(value)
            fields_values = AutosarNode._add_or_get_xml_node(self._node, 'FIELDS', createNode = False)
            fields_values.remove(value._node)
            value._parent = None #No parent
            value._update_path() #resets the path

    def remove_fields(self, values):
        """
        Removes a list of value from fields
        """
        for value in values:
            self.remove_field(value)

