class SwValues(ARObject):
    """
    This meta-class represents a list of values. These values can either be the input values of a curve (abscissa values) or the associated values (ordinate values). , , In case of multidimensional structures, the values are ordered such that the lowest index runs the fastest. In particular for maps and cuboids etc. the resulting long value list can be subsectioned using ValueGroup. But the processing needs to be done as if vg is not there., , Note that numerical values and textual values should not be mixed.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'SW-VALUES'
        self.__vts = None
        self.__vs = None
        self.__vtfs = set()
        self.__vfs = set()
        self.__vgs = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        vts_value = AutosarNode._get_node_text(node,'VT')
        if vts_value is not None:
            self.__vts = datatype_utils.get_string_value(vts_value)

        vs_value = AutosarNode._get_node_text(node,'V')
        if vs_value is not None:
            self.__vs = datatype_utils.get_string_value(vs_value)

        vtfs_nodes = self._node.findall('{*}VTFS/*')
        for vtfs_node in vtfs_nodes:
            self.__vtfs.add(NumericalOrText()._build(self, vtfs_node))

        vfs_nodes = self._node.findall('{*}VFS/*')
        for vfs_node in vfs_nodes:
            self.__vfs.add(NumericalValueVariationPoint()._build(self, vfs_node))

        vgs_nodes = self._node.findall('{*}VGS/*')
        for vgs_node in vgs_nodes:
            self.__vgs.add(ValueGroup()._build(self, vgs_node))

        return self

    def get_vts(self):
        return self.__vts

    def set_vts(self, value):
        self.__vts = value
        vts_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'VT')
        vts_xml_node.text = str(value) if value is not None else ''

    def get_vs(self):
        return self.__vs

    def set_vs(self, value):
        self.__vs = value
        vs_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'V')
        vs_xml_node.text = str(value) if value is not None else ''

    def get_vtfs(self):
        return self.__vtfs

    def add_vtf(self, value):
        """
        Adds a single value to the vtfs
        """
        if value is not None:
            if any(v.name == value.name for v in self.__vtfs):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, NumericalOrText) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of NumericalOrText or its sub-classes'.format(value))
            self.__vtfs.add(value)
            vtfs_values = AutosarNode._add_or_get_xml_node(self._node, 'VTFS')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            vtfs_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_vtfs(self, values):
        """
        Adds a list of ref value to the vtfs
        """
        for value in values:
            self.add_vtf(value)

    def remove_vtf(self, value):
        """
        Removes a single value from vtfs
        """
        if value is not None:
            self.__vtfs.remove(value)
            vtfs_values = AutosarNode._add_or_get_xml_node(self._node, 'VTFS', createNode = False)
            vtfs_values.remove(value._node)
            value._parent = None #No parent
            value._update_path() #resets the path

    def remove_vtfs(self, values):
        """
        Removes a list of value from vtfs
        """
        for value in values:
            self.remove_vtf(value)

    def get_vfs(self):
        return self.__vfs

    def add_vf(self, value):
        """
        Adds a single value to the vfs
        """
        if value is not None:
            if any(v.name == value.name for v in self.__vfs):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, NumericalValueVariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of NumericalValueVariationPoint or its sub-classes'.format(value))
            self.__vfs.add(value)
            vfs_values = AutosarNode._add_or_get_xml_node(self._node, 'VFS')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            vfs_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_vfs(self, values):
        """
        Adds a list of ref value to the vfs
        """
        for value in values:
            self.add_vf(value)

