class PduTriggering(Identifiable):
    """
    The PduTriggering describes on which channel the IPdu is transmitted., The Pdu routing by the PduR is only allowed for subclasses of IPdu., , Depending on its relation to entities such channels and clusters it can be unambiguously deduced whether a fan-out is handled by the Pdu router or the Bus Interface. , , If the fan-out is specified between different clusters it shall be handled by the Pdu Router. If the fan-out is specified between different channels of the same cluster it shall be handled by the Bus Interface.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'PDU-TRIGGERING'
        self.__iPduPorts = set()
        self.__iPdu = None
        self.__iSignalTriggerings = set()
        self.__secOcCryptoMapping = None
        self.__triggerIPduSendConditions = set()
        self.__variationPoint = None

    def _build(self, parent, node):
        super()._build(parent, node)
        iSignalTriggerings_nodes = self._node.findall('{*}I-SIGNAL-TRIGGERINGS/*')
        for iSignalTriggerings_node in iSignalTriggerings_nodes:
            self.__iSignalTriggerings.add(ISignalTriggeringRefConditional()._build(self, iSignalTriggerings_node))

        triggerIPduSendConditions_nodes = self._node.findall('{*}TRIGGER-I-PDU-SEND-CONDITIONS/*')
        for triggerIPduSendConditions_node in triggerIPduSendConditions_nodes:
            self.__triggerIPduSendConditions.add(TriggerIPduSendCondition()._build(self, triggerIPduSendConditions_node))

        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            self.__variationPoint = VariationPoint()._build(self, variationPoint_node)

        return self

    def _resolve_references(self):
        iPduPorts_nodes = self._node.findall('{*}I-PDU-PORT-REFS/*')
        for node in iPduPorts_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__iPduPorts.add(ref_value)
        iPdu_node = self._node.find('{*}I-PDU-REF')
        if iPdu_node is not None and iPdu_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[iPdu_node.text]
            ref_value.referenced_by.add(self)
            self.__iPdu = ref_value
        secOcCryptoMapping_node = self._node.find('{*}SEC-OC-CRYPTO-MAPPING-REF')
        if secOcCryptoMapping_node is not None and secOcCryptoMapping_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[secOcCryptoMapping_node.text]
            ref_value.referenced_by.add(self)
            self.__secOcCryptoMapping = ref_value

