class DataPrototypeMapping(ARObject):
    """
    Defines the mapping of two particular VariableDataPrototypes, ParameterDataPrototypes or ArgumentDataPrototypes with unequal names and/or unequal semantic (resolution or range) in context of two different SenderReceiverInterface, NvDataInterface or ParameterInterface or Operations., , If the semantic is unequal following rules apply:, The textTableMapping is only applicable if the referred DataPrototypes are typed by AutosarDataType referring to CompuMethods of category TEXTTABLE, SCALE_LINEAR_AND_TEXTTABLE or BITFIELD_TEXTTABLE., , In the case that the  DataPrototypes are typed by AutosarDataType either referring to CompuMethods of category LINEAR, IDENTICAL or referring to no CompuMethod (which is similar as  IDENTICAL) the linear conversion factor is calculated out of the factorSiToUnit and offsetSiToUnit attributes of the referred Units and the CompuRationalCoeffs of a compuInternalToPhys of the referred CompuMethods.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'DATA-PROTOTYPE-MAPPING'
        self.__firstDataPrototype = None
        self.__firstToSecondDataTransformation = None
        self.__secondDataPrototype = None
        self.__secondToFirstDataTransformation = None
        self.__subElementMappings = set()
        self.__textTableMappings = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        subElementMappings_nodes = self._node.findall('{*}SUB-ELEMENT-MAPPINGS/*')
        for subElementMappings_node in subElementMappings_nodes:
            self.__subElementMappings.add(SubElementMapping()._build(self, subElementMappings_node))

        textTableMappings_nodes = self._node.findall('{*}TEXT-TABLE-MAPPINGS/*')
        for textTableMappings_node in textTableMappings_nodes:
            self.__textTableMappings.add(TextTableMapping()._build(self, textTableMappings_node))

        return self

    def _resolve_references(self):
        firstDataPrototype_node = self._node.find('{*}FIRST-DATA-PROTOTYPE-REF')
        if firstDataPrototype_node is not None and firstDataPrototype_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[firstDataPrototype_node.text]
            ref_value.referenced_by.add(self)
            self.__firstDataPrototype = ref_value
        firstToSecondDataTransformation_node = self._node.find('{*}FIRST-TO-SECOND-DATA-TRANSFORMATION-REF')
        if firstToSecondDataTransformation_node is not None and firstToSecondDataTransformation_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[firstToSecondDataTransformation_node.text]
            ref_value.referenced_by.add(self)
            self.__firstToSecondDataTransformation = ref_value
        secondDataPrototype_node = self._node.find('{*}SECOND-DATA-PROTOTYPE-REF')
        if secondDataPrototype_node is not None and secondDataPrototype_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[secondDataPrototype_node.text]
            ref_value.referenced_by.add(self)
            self.__secondDataPrototype = ref_value
        secondToFirstDataTransformation_node = self._node.find('{*}SECOND-TO-FIRST-DATA-TRANSFORMATION-REF')
        if secondToFirstDataTransformation_node is not None and secondToFirstDataTransformation_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[secondToFirstDataTransformation_node.text]
            ref_value.referenced_by.add(self)
            self.__secondToFirstDataTransformation = ref_value

    def get_firstDataPrototype(self):
        return self.__firstDataPrototype

    def set_firstDataPrototype(self, value):
        """
        Adds a single value to the firstDataPrototype
        """
        if value is not None:
            if isinstance(value, AutosarDataPrototype) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of AutosarDataPrototype or its sub-classes'.format(value))
            if self.__firstDataPrototype is not None:
                self.__firstDataPrototype.referenced_by.remove(self)
            firstDataPrototype_value = AutosarNode._add_or_get_xml_node(self._node, 'FIRST-DATA-PROTOTYPE-REF', value)
            firstDataPrototype_value.text = value.path
            firstDataPrototype_value.attrib['DEST'] = value.tag
            self.__firstDataPrototype = value
            value.referenced_by.add(self)
        elif self.__firstDataPrototype is not None:
            self.__firstDataPrototype.referenced_by.remove(self)
            self.__firstDataPrototype = None
            firstDataPrototype_value = AutosarNode._add_or_get_xml_node(self._node, 'FIRST-DATA-PROTOTYPE-REF', createNode = False)
            if firstDataPrototype_value is not None:
                firstDataPrototype_value.referenced_by.remove(self)
                firstDataPrototype_value.text = ''

    def get_firstToSecondDataTransformation(self):
        return self.__firstToSecondDataTransformation

    def set_firstToSecondDataTransformation(self, value):
        """
        Adds a single value to the firstToSecondDataTransformation
        """
        if value is not None:
            if isinstance(value, DataTransformation) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of DataTransformation or its sub-classes'.format(value))
            if self.__firstToSecondDataTransformation is not None:
                self.__firstToSecondDataTransformation.referenced_by.remove(self)
            firstToSecondDataTransformation_value = AutosarNode._add_or_get_xml_node(self._node, 'FIRST-TO-SECOND-DATA-TRANSFORMATION-REF', value)
            firstToSecondDataTransformation_value.text = value.path
            firstToSecondDataTransformation_value.attrib['DEST'] = value.tag
            self.__firstToSecondDataTransformation = value
            value.referenced_by.add(self)
        elif self.__firstToSecondDataTransformation is not None:
            self.__firstToSecondDataTransformation.referenced_by.remove(self)
            self.__firstToSecondDataTransformation = None
            firstToSecondDataTransformation_value = AutosarNode._add_or_get_xml_node(self._node, 'FIRST-TO-SECOND-DATA-TRANSFORMATION-REF', createNode = False)
            if firstToSecondDataTransformation_value is not None:
                firstToSecondDataTransformation_value.referenced_by.remove(self)
                firstToSecondDataTransformation_value.text = ''

    def get_secondDataPrototype(self):
        return self.__secondDataPrototype

    def set_secondDataPrototype(self, value):
        """
        Adds a single value to the secondDataPrototype
        """
        if value is not None:
            if isinstance(value, AutosarDataPrototype) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of AutosarDataPrototype or its sub-classes'.format(value))
            if self.__secondDataPrototype is not None:
                self.__secondDataPrototype.referenced_by.remove(self)
            secondDataPrototype_value = AutosarNode._add_or_get_xml_node(self._node, 'SECOND-DATA-PROTOTYPE-REF', value)
            secondDataPrototype_value.text = value.path
