class BswInternalTriggerOccurredEvent(BswScheduleEvent):
    """
    A BswEvent, which can happen sporadically. The event is activated by explicit calls from the module to the BSW Scheduler. The main purpose for such an event is to cause a context switch, e.g. from an ISR context into a task context. Activation and switching are handled within the same module or cluster only.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'BSW-INTERNAL-TRIGGER-OCCURRED-EVENT'
        self.__eventSource = None


    def _resolve_references(self):
        eventSource_node = self._node.find('{*}EVENT-SOURCE-REF')
        if eventSource_node is not None and eventSource_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[eventSource_node.text]
            ref_value.referenced_by.add(self)
            self.__eventSource = ref_value

    def get_eventSource(self):
        return self.__eventSource

    def set_eventSource(self, value):
        """
        Adds a single value to the eventSource
        """
        if value is not None:
            if isinstance(value, BswInternalTriggeringPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of BswInternalTriggeringPoint or its sub-classes'.format(value))
            if self.__eventSource is not None:
                self.__eventSource.referenced_by.remove(self)
            eventSource_value = AutosarNode._add_or_get_xml_node(self._node, 'EVENT-SOURCE-REF', value)
            eventSource_value.text = value.path
            eventSource_value.attrib['DEST'] = value.tag
            self.__eventSource = value
            value.referenced_by.add(self)
        elif self.__eventSource is not None:
            self.__eventSource.referenced_by.remove(self)
            self.__eventSource = None
            eventSource_value = AutosarNode._add_or_get_xml_node(self._node, 'EVENT-SOURCE-REF', createNode = False)
            if eventSource_value is not None:
                eventSource_value.referenced_by.remove(self)
                eventSource_value.text = ''

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['EventSource'] = self.__eventSource
        return property_values

    def _update_path(self):
        """
        Updates the path of the BswInternalTriggerOccurredEvent and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

