class FlexrayTpNode(Identifiable):
    """
    TP Node (Sender or Receiver) provides the TP Address and the connection to the Topology description.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'FLEXRAY-TP-NODE'
        self.__connectors = set()
        self.__tpAddress = None
        self.__variationPoint = None

    def _build(self, parent, node):
        super()._build(parent, node)
        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            self.__variationPoint = VariationPoint()._build(self, variationPoint_node)

        return self

    def _resolve_references(self):
        connectors_nodes = self._node.findall('{*}CONNECTOR-REFS/*')
        for node in connectors_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__connectors.add(ref_value)
        tpAddress_node = self._node.find('{*}TP-ADDRESS-REF')
        if tpAddress_node is not None and tpAddress_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[tpAddress_node.text]
            ref_value.referenced_by.add(self)
            self.__tpAddress = ref_value

    def get_connectors(self):
        return self.__connectors

    def add_connector(self, value):
        """
        Adds a single value to the connectors
        """
        if value is not None:
            if any(v.name == value.name for v in self.__connectors):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, CommunicationConnector) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of CommunicationConnector or its sub-classes'.format(value))
            self.__connectors.add(value)
            connectors_values = AutosarNode._add_or_get_xml_node(self._node, 'CONNECTOR-REFS')

            connectors_value = AutosarNode._add_or_get_xml_node(connectors_values, 'CONNECTOR-REF', value, forceCreate = True)
            connectors_value.text = value.path
            value.referenced_by.add(self)

    def set_connectors(self, values):
        """
        Adds a list of ref value to the connectors
        """
        for value in values:
            self.add_connector(value)

    def remove_connector(self, value):
        """
        Removes a single value from connectors
        """
        if value is not None:
            self.__connectors.remove(value)
            connectors_values = AutosarNode._add_or_get_xml_node(self._node, 'CONNECTOR-REFS', createNode = False)
            for connectors_value in self._node.findall('{*}CONNECTOR-REFS/*'):
                if connectors_value.text == value.path:
                    connectors_value.text = ''
                    connectors_values.remove(connectors_value)
                    value.referenced_by.remove(self)
                    break

    def remove_connectors(self, values):
        """
        Removes a list of value from connectors
        """
        for value in values:
            self.remove_connector(value)

    def get_tpAddress(self):
        return self.__tpAddress

    def set_tpAddress(self, value):
        """
        Adds a single value to the tpAddress
        """
        if value is not None:
            if isinstance(value, TpAddress) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of TpAddress or its sub-classes'.format(value))
            if self.__tpAddress is not None:
                self.__tpAddress.referenced_by.remove(self)
            tpAddress_value = AutosarNode._add_or_get_xml_node(self._node, 'TP-ADDRESS-REF', value)
            tpAddress_value.text = value.path
            tpAddress_value.attrib['DEST'] = value.tag
            self.__tpAddress = value
            value.referenced_by.add(self)
        elif self.__tpAddress is not None:
            self.__tpAddress.referenced_by.remove(self)
            self.__tpAddress = None
            tpAddress_value = AutosarNode._add_or_get_xml_node(self._node, 'TP-ADDRESS-REF', createNode = False)
            if tpAddress_value is not None:
                tpAddress_value.referenced_by.remove(self)
                tpAddress_value.text = ''

    def get_variationPoint(self):
        return self.__variationPoint

    def set_variationPoint(self, value):
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))
            if self.__variationPoint is not None:
                self._node.remove(self.__variationPoint._node)
            # if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            self._node.append(value._node)
            self.__variationPoint = value
            value._parent = self #set parent
            value._update_path() #updates the path
        elif self.__variationPoint is not None:
            self._node.remove(self.__variationPoint._node)
            self.__variationPoint = None
            self.__variationPoint._parent = None #No parent
            self.__variationPoint._update_path() #updates the path

    def new_VariationPoint(self, name=None):
        """
        Creates a new VariationPoint under the FlexrayTpNode.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        VariationPoint_obj = VariationPoint()
        if isinstance(VariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('VARIATION-POINT')
        VariationPoint_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        VariationPoint_obj.name = name
        VariationPoint_obj._node = xmlNode
        self.set_variationPoint(VariationPoint_obj)
        return VariationPoint_obj

    def get_children(self):
        children = super().get_children()
        if self.__variationPoint is not None:
            children.append(self.__variationPoint)
        return children

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['Connectors'] = self.__connectors
        property_values['TpAddress'] = self.__tpAddress
        return property_values

    def _update_path(self):
        """
        Updates the path of the FlexrayTpNode and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

class ExecutionOrderConstraint(TimingConstraint):
    """
    This constraint is used to restrict the order of execution for a set of ExecutableEntities. The ExecutionOrderConstraint can be used in any timing view., , The various scopes for ExecutionOrderConstraint are described below. Generally, each ExecutionOrderConstraint has a scope of software components and can reference all executable entities available in the corresponding internal behavior (RunnableEntity and BswModuleEntity) either directly or by the events activating respectively starting them (RteEvent and BswEvent)., , On VFB level an ExecutionOrderConstraint can be specified for RunnableEntities part of the composition hierarchy referenced by the VfbTiming. The ExecutionOrderConstraint is aggregated by the VfbTiming., , On SW-C level an ExecutionOrderConstraint can be specified for RunnableEntities part of the InternalBehavior referenced by the SwcTiming. The ExecutionOrderConstraint is aggregated by the SwcTiming., , On System level an ExecutionOrderConstraint can be specified for RunnableEntities part of the composition hierarchy of the system referenced by the SystemTiming. The ExecutionOrderConstraint is aggregated by the SystemTiming., , On BSW Module level, an ExectionOrderConstraint can be specified for BswModuleEntities part of an BswInternalBehavior referenced by the BswModuleTiming. The ExecutionOrderConstraint is aggregated by the BswModuleTiming., , On ECU level an ExecutionOrderConstraint can be specified for all ExecutableEntities and Events available via the EcucValueCollection, covering ECU Extract and BSW Module Configuration, referenced by the EcuTiming. The ExecutionOrderConstraint is aggregated by the EcuTiming.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'EXECUTION-ORDER-CONSTRAINT'
        self.__executionOrderConstraintType = None
        self.__ignoreOrderAllowed = None
        self.__isEvent = None
        self.__permitMultipleReferencesToEE = None
        self.__baseComposition = None
        self.__orderedElements = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        executionOrderConstraintType_value = AutosarNode._get_node_text(node,'EXECUTION-ORDER-CONSTRAINT-TYPE')
        if executionOrderConstraintType_value is not None:
            self.__executionOrderConstraintType = ExecutionOrderConstraintTypeEnum.get(executionOrderConstraintType_value)

        ignoreOrderAllowed_value = AutosarNode._get_node_text(node,'IGNORE-ORDER-ALLOWED')
        if ignoreOrderAllowed_value is not None:
            self.__ignoreOrderAllowed = datatype_utils.get_bool_value(ignoreOrderAllowed_value)

        isEvent_value = AutosarNode._get_node_text(node,'IS-EVENT')
        if isEvent_value is not None:
            self.__isEvent = datatype_utils.get_bool_value(isEvent_value)

        permitMultipleReferencesToEE_value = AutosarNode._get_node_text(node,'PERMIT-MULTIPLE-REFERENCES-TO-EE')
        if permitMultipleReferencesToEE_value is not None:
            self.__permitMultipleReferencesToEE = datatype_utils.get_bool_value(permitMultipleReferencesToEE_value)

        orderedElements_obj_dict = {}
        orderedElements_obj_dict['EOC-EVENT-REF'] = 'EOCEventRef'
        orderedElements_obj_dict['EOC-EXECUTABLE-ENTITY-REF'] = 'EOCExecutableEntityRef'
        orderedElements_obj_dict['EOC-EXECUTABLE-ENTITY-REF-GROUP'] = 'EOCExecutableEntityRefGroup'
        orderedElements_nodes = self._node.findall('{*}ORDERED-ELEMENTS/*')
        for orderedElements_node in orderedElements_nodes:
            self.__orderedElements.add(__str_to_class__(orderedElements_obj_dict[etree.QName(orderedElements_node).localname])()._build(self, orderedElements_node))

        return self

