class AbstractProvidedPortPrototype(PortPrototype):
    """
    This abstract class provides the ability to become a provided PortPrototype.
    """
    def __init__(self):
        super().__init__()
        self.__providedComSpecs = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        providedComSpecs_obj_dict = {}
        providedComSpecs_obj_dict['NONQUEUED-SENDER-COM-SPEC'] = 'NonqueuedSenderComSpec'
        providedComSpecs_obj_dict['PARAMETER-PROVIDE-COM-SPEC'] = 'ParameterProvideComSpec'
        providedComSpecs_obj_dict['SERVER-COM-SPEC'] = 'ServerComSpec'
        providedComSpecs_obj_dict['NV-PROVIDE-COM-SPEC'] = 'NvProvideComSpec'
        providedComSpecs_obj_dict['QUEUED-SENDER-COM-SPEC'] = 'QueuedSenderComSpec'
        providedComSpecs_obj_dict['FIELD-SENDER-COM-SPEC'] = 'FieldSenderComSpec'
        providedComSpecs_obj_dict['MODE-SWITCH-SENDER-COM-SPEC'] = 'ModeSwitchSenderComSpec'
        providedComSpecs_nodes = self._node.findall('{*}PROVIDED-COM-SPECS/*')
        for providedComSpecs_node in providedComSpecs_nodes:
            self.__providedComSpecs.add(__str_to_class__(providedComSpecs_obj_dict[etree.QName(providedComSpecs_node).localname])()._build(self, providedComSpecs_node))

        return self

