    def _resolve_references(self):
        accessPermission_node = self._node.find('{*}ACCESS-PERMISSION-REF')
        if accessPermission_node is not None and accessPermission_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[accessPermission_node.text]
