        if value is not None:
            if isinstance(value, DiagnosticAccessPermission) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of DiagnosticAccessPermission or its sub-classes'.format(value))
            if self.__accessPermission is not None:
                self.__accessPermission.referenced_by.remove(self)
            accessPermission_value = AutosarNode._add_or_get_xml_node(self._node, 'ACCESS-PERMISSION-REF', value)
            accessPermission_value.text = value.path
            accessPermission_value.attrib['DEST'] = value.tag
