class PrimitiveAttributeCondition(AttributeCondition,AbstractValueRestriction):
    """
    The PrimitiveAttributeCondition evaluates to true, if the referenced primitive attribute is accepted by all rules of this condition.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'PRIMITIVE-ATTRIBUTE-CONDITION'
        self.__attribute = None


    def _resolve_references(self):
        attribute_node = self._node.find('{*}ATTRIBUTE-REF')
        if attribute_node is not None and attribute_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[attribute_node.text]
            ref_value.referenced_by.add(self)
            self.__attribute = ref_value

    def get_attribute(self):
        return self.__attribute

    def set_attribute(self, value):
        """
        Adds a single value to the attribute
        """
        if value is not None:
            if isinstance(value, PrimitiveAttributeTailoring) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of PrimitiveAttributeTailoring or its sub-classes'.format(value))
            if self.__attribute is not None:
                self.__attribute.referenced_by.remove(self)
            attribute_value = AutosarNode._add_or_get_xml_node(self._node, 'ATTRIBUTE-REF', value)
            attribute_value.text = value.path
            attribute_value.attrib['DEST'] = value.tag
            self.__attribute = value
            value.referenced_by.add(self)
        elif self.__attribute is not None:
            self.__attribute.referenced_by.remove(self)
            self.__attribute = None
            attribute_value = AutosarNode._add_or_get_xml_node(self._node, 'ATTRIBUTE-REF', createNode = False)
            if attribute_value is not None:
                attribute_value.referenced_by.remove(self)
                attribute_value.text = ''

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['Attribute'] = self.__attribute
        return property_values

    def _update_path(self):
        """
        Updates the path of the PrimitiveAttributeCondition and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

