class CpSoftwareClusterResource(Identifiable):
    """
    Represents a single resource required or provided by a CP Software Cluster.
    """
    def __init__(self):
        super().__init__()
        self.__globalResourceId = None
        self.__isMandatory = None
        self.__dependentResources = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        globalResourceId_value = AutosarNode._get_node_text(node,'GLOBAL-RESOURCE-ID')
        if globalResourceId_value is not None:
            self.__globalResourceId = datatype_utils.get_int_value(globalResourceId_value)

        isMandatory_value = AutosarNode._get_node_text(node,'IS-MANDATORY')
        if isMandatory_value is not None:
            self.__isMandatory = datatype_utils.get_bool_value(isMandatory_value)

        dependentResources_nodes = self._node.findall('{*}DEPENDENT-RESOURCES/*')
        for dependentResources_node in dependentResources_nodes:
            self.__dependentResources.add(RoleBasedResourceDependency()._build(self, dependentResources_node))

        return self

    def get_globalResourceId(self):
        return self.__globalResourceId

    def set_globalResourceId(self, value):
        self.__globalResourceId = value
        globalResourceId_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'GLOBAL-RESOURCE-ID')
        globalResourceId_xml_node.text = str(value) if value is not None else ''

    def get_isMandatory(self):
        return self.__isMandatory

    def set_isMandatory(self, value):
        self.__isMandatory = value
        isMandatory_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'IS-MANDATORY')
        isMandatory_xml_node.text = 'true' if value is True else 'false'

    def get_dependentResources(self):
        return self.__dependentResources

    def add_dependentResource(self, value):
        """
        Adds a single value to the dependentResources
        """
        if value is not None:
            if any(v.name == value.name for v in self.__dependentResources):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, RoleBasedResourceDependency) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of RoleBasedResourceDependency or its sub-classes'.format(value))
            self.__dependentResources.add(value)
            dependentResources_values = AutosarNode._add_or_get_xml_node(self._node, 'DEPENDENT-RESOURCES')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            dependentResources_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_dependentResources(self, values):
        """
        Adds a list of ref value to the dependentResources
        """
        for value in values:
            self.add_dependentResource(value)

    def remove_dependentResource(self, value):
        """
        Removes a single value from dependentResources
        """
        if value is not None:
            self.__dependentResources.remove(value)
            dependentResources_values = AutosarNode._add_or_get_xml_node(self._node, 'DEPENDENT-RESOURCES', createNode = False)
            dependentResources_values.remove(value._node)
            value._parent = None #No parent
            value._update_path() #resets the path

    def remove_dependentResources(self, values):
        """
        Removes a list of value from dependentResources
        """
        for value in values:
            self.remove_dependentResource(value)

    def new_DependentResource(self, name=None):
        """
        Creates a new RoleBasedResourceDependency under the CpSoftwareClusterResource.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        RoleBasedResourceDependency_obj = RoleBasedResourceDependency()
        if isinstance(RoleBasedResourceDependency_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('ROLE-BASED-RESOURCE-DEPENDENCY')
        RoleBasedResourceDependency_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        RoleBasedResourceDependency_obj.name = name
        RoleBasedResourceDependency_obj._node = xmlNode
        self.add_dependentResource(RoleBasedResourceDependency_obj)
        return RoleBasedResourceDependency_obj

    def get_children(self):
        children = super().get_children()
        children.extend(self.__dependentResources)
        return children

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['GlobalResourceId'] = self.__globalResourceId
        property_values['IsMandatory'] = self.__isMandatory
        return property_values

    def _update_path(self):
        """
        Updates the path of the CpSoftwareClusterResource and its children.
        """
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

