class VfbTiming(AtpBlueprint,AtpBlueprintable,TimingExtension):
    """
    A model element used to define timing descriptions and constraints at VFB level., , TimingDescriptions aggregated by VfbTiming are restricted to event chains referring to events which are derived from the class TDEventVfb.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'VFB-TIMING'
        self.__component = None


    def _resolve_references(self):
        component_node = self._node.find('{*}COMPONENT-REF')
        if component_node is not None and component_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[component_node.text]
            ref_value.referenced_by.add(self)
            self.__component = ref_value

    def get_component(self):
        return self.__component

    def set_component(self, value):
        """
        Adds a single value to the component
        """
        if value is not None:
            if isinstance(value, SwComponentType) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of SwComponentType or its sub-classes'.format(value))
            if self.__component is not None:
                self.__component.referenced_by.remove(self)
            component_value = AutosarNode._add_or_get_xml_node(self._node, 'COMPONENT-REF', value)
            component_value.text = value.path
            component_value.attrib['DEST'] = value.tag
            self.__component = value
            value.referenced_by.add(self)
        elif self.__component is not None:
            self.__component.referenced_by.remove(self)
            self.__component = None
            component_value = AutosarNode._add_or_get_xml_node(self._node, 'COMPONENT-REF', createNode = False)
            if component_value is not None:
                component_value.referenced_by.remove(self)
                component_value.text = ''

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['Component'] = self.__component
        return property_values

    def _update_path(self):
        """
        Updates the path of the VfbTiming and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

