class Gateway(FibexElement):
    """
    A gateway is an ECU that is connected to two or more clusters (channels, but not redundant), and performs a frame, Pdu or signal mapping between them.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'GATEWAY'
        self.__ecu = None
        self.__frameMappings = set()
        self.__iPduMappings = set()
        self.__signalMappings = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        frameMappings_nodes = self._node.findall('{*}FRAME-MAPPINGS/*')
        for frameMappings_node in frameMappings_nodes:
            self.__frameMappings.add(FrameMapping()._build(self, frameMappings_node))

        iPduMappings_nodes = self._node.findall('{*}I-PDU-MAPPINGS/*')
        for iPduMappings_node in iPduMappings_nodes:
            self.__iPduMappings.add(IPduMapping()._build(self, iPduMappings_node))

        signalMappings_nodes = self._node.findall('{*}SIGNAL-MAPPINGS/*')
        for signalMappings_node in signalMappings_nodes:
            self.__signalMappings.add(ISignalMapping()._build(self, signalMappings_node))

        return self

    def _resolve_references(self):
        ecu_node = self._node.find('{*}ECU-REF')
        if ecu_node is not None and ecu_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[ecu_node.text]
            ref_value.referenced_by.add(self)
            self.__ecu = ref_value

    def get_ecu(self):
        return self.__ecu

    def set_ecu(self, value):
        """
        Adds a single value to the ecu
        """
        if value is not None:
            if isinstance(value, EcuInstance) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of EcuInstance or its sub-classes'.format(value))
            if self.__ecu is not None:
                self.__ecu.referenced_by.remove(self)
            ecu_value = AutosarNode._add_or_get_xml_node(self._node, 'ECU-REF', value)
            ecu_value.text = value.path
            ecu_value.attrib['DEST'] = value.tag
            self.__ecu = value
            value.referenced_by.add(self)
        elif self.__ecu is not None:
            self.__ecu.referenced_by.remove(self)
            self.__ecu = None
            ecu_value = AutosarNode._add_or_get_xml_node(self._node, 'ECU-REF', createNode = False)
            if ecu_value is not None:
                ecu_value.referenced_by.remove(self)
                ecu_value.text = ''

