        if value is not None:
            if isinstance(value, BswModuleClientServerEntry) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of BswModuleClientServerEntry or its sub-classes'.format(value))
            if self.__calledEntry is not None:
                self.__calledEntry.referenced_by.remove(self)
            calledEntry_value = AutosarNode._add_or_get_xml_node(self._node, 'CALLED-ENTRY-REF', value)
            calledEntry_value.text = value.path
