class DiagnosticJ1939FreezeFrame(DiagnosticCommonElement):
    """
    This meta-class represents the ability to model a J1939 Freeze Frame.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'DIAGNOSTIC-J-1939-FREEZE-FRAME'
        self.__node = None
        self.__spns = set()


    def _resolve_references(self):
        node_node = self._node.find('{*}NODE-REF')
        if node_node is not None and node_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[node_node.text]
            ref_value.referenced_by.add(self)
            self.__node = ref_value
        spns_nodes = self._node.findall('{*}SPN-REFS/*')
        for node in spns_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__spns.add(ref_value)

