class CouplingPortConnection(ARObject):
    """
    Connection between two CouplingPorts (firstPort and secondPort) or between a collection of Ports that are all referenced by the portCollection reference.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'COUPLING-PORT-CONNECTION'
        self.__plcaLocalNodeCount = None
        self.__plcaTransmitOpportunityTimer = None
        self.__firstPort = None
        self.__nodePorts = set()
        self.__secondPort = None
        self.__variationPoint = None

    def _build(self, parent, node):
        super()._build(parent, node)
        plcaLocalNodeCount_value = AutosarNode._get_node_text(node,'PLCA-LOCAL-NODE-COUNT')
        if plcaLocalNodeCount_value is not None:
            self.__plcaLocalNodeCount = datatype_utils.get_int_value(plcaLocalNodeCount_value)

        plcaTransmitOpportunityTimer_value = AutosarNode._get_node_text(node,'PLCA-TRANSMIT-OPPORTUNITY-TIMER')
        if plcaTransmitOpportunityTimer_value is not None:
            self.__plcaTransmitOpportunityTimer = datatype_utils.get_int_value(plcaTransmitOpportunityTimer_value)

        nodePorts_nodes = self._node.findall('{*}NODE-PORTS/*')
        for nodePorts_node in nodePorts_nodes:
            self.__nodePorts.add(CouplingPortRefConditional()._build(self, nodePorts_node))

        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            self.__variationPoint = VariationPoint()._build(self, variationPoint_node)

        return self

    def _resolve_references(self):
        firstPort_node = self._node.find('{*}FIRST-PORT-REF')
        if firstPort_node is not None and firstPort_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[firstPort_node.text]
