class BswModuleDescription(ARElement,AtpBlueprint,AtpBlueprintable,AtpStructureElement):
    """
    Root element for the description of a single BSW module or BSW cluster., In case it describes a BSW module, the short name of this element equals the name of the BSW module.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'BSW-MODULE-DESCRIPTION'
        self.__moduleId = None
        self.__expectedEntries = set()
        self.__implementedEntries = set()
        self.__bswModuleDocumentations = set()
        self.__providedEntries = set()
        self.__outgoingCallbacks = set()
        self.__bswModuleDependencies = set()
        self.__providedModeGroups = set()
        self.__requiredModeGroups = set()
        self.__releasedTriggers = set()
        self.__requiredTriggers = set()
        self.__providedClientServerEntries = set()
        self.__requiredClientServerEntries = set()
        self.__providedDatas = set()
        self.__requiredDatas = set()
        self.__internalBehaviors = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        moduleId_value = AutosarNode._get_node_text(node,'MODULE-ID')
        if moduleId_value is not None:
            self.__moduleId = datatype_utils.get_int_value(moduleId_value)

        expectedEntries_nodes = self._node.findall('{*}EXPECTED-ENTRYS/*')
        for expectedEntries_node in expectedEntries_nodes:
            self.__expectedEntries.add(BswModuleEntryRefConditional()._build(self, expectedEntries_node))

        implementedEntries_nodes = self._node.findall('{*}IMPLEMENTED-ENTRYS/*')
        for implementedEntries_node in implementedEntries_nodes:
            self.__implementedEntries.add(BswModuleEntryRefConditional()._build(self, implementedEntries_node))

        bswModuleDocumentations_nodes = self._node.findall('{*}BSW-MODULE-DOCUMENTATIONS/*')
        for bswModuleDocumentations_node in bswModuleDocumentations_nodes:
            self.__bswModuleDocumentations.add(SwComponentDocumentation()._build(self, bswModuleDocumentations_node))

        providedEntries_nodes = self._node.findall('{*}PROVIDED-ENTRYS/*')
        for providedEntries_node in providedEntries_nodes:
            self.__providedEntries.add(BswModuleEntryRefConditional()._build(self, providedEntries_node))

        outgoingCallbacks_nodes = self._node.findall('{*}OUTGOING-CALLBACKS/*')
        for outgoingCallbacks_node in outgoingCallbacks_nodes:
            self.__outgoingCallbacks.add(BswModuleEntryRefConditional()._build(self, outgoingCallbacks_node))

        bswModuleDependencies_nodes = self._node.findall('{*}BSW-MODULE-DEPENDENCYS/*')
        for bswModuleDependencies_node in bswModuleDependencies_nodes:
            self.__bswModuleDependencies.add(BswModuleDependency()._build(self, bswModuleDependencies_node))

        providedModeGroups_nodes = self._node.findall('{*}PROVIDED-MODE-GROUPS/*')
        for providedModeGroups_node in providedModeGroups_nodes:
            self.__providedModeGroups.add(ModeDeclarationGroupPrototype()._build(self, providedModeGroups_node))

        requiredModeGroups_nodes = self._node.findall('{*}REQUIRED-MODE-GROUPS/*')
