class BswModuleEntry(ARElement,AtpBlueprint,AtpBlueprintable):
    """
    This class represents a single API entry (C-function prototype) into the BSW module or cluster., , The name of the C-function is equal to the short name of this element with one exception: In case of multiple instances of a module on the same CPU, special rules for "infixes" apply, see description of class BswImplementation.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'BSW-MODULE-ENTRY'
        self.__functionPrototypeEmitter = None
        self.__serviceId = None
        self.__role = None
        self.__isReentrant = None
        self.__isSynchronous = None
        self.__callType = None
        self.__executionContext = None
        self.__swServiceImplPolicy = None
        self.__bswEntryKind = None
        self.__returnType = None
        self.__arguments = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        functionPrototypeEmitter_value = AutosarNode._get_node_text(node,'FUNCTION-PROTOTYPE-EMITTER')
        if functionPrototypeEmitter_value is not None:
            self.__functionPrototypeEmitter = datatype_utils.get_string_value(functionPrototypeEmitter_value)

        serviceId_value = AutosarNode._get_node_text(node,'SERVICE-ID')
        if serviceId_value is not None:
            self.__serviceId = datatype_utils.get_int_value(serviceId_value)

        role_value = AutosarNode._get_node_text(node,'ROLE')
        if role_value is not None:
            self.__role = datatype_utils.get_string_value(role_value)

        isReentrant_value = AutosarNode._get_node_text(node,'IS-REENTRANT')
        if isReentrant_value is not None:
            self.__isReentrant = datatype_utils.get_bool_value(isReentrant_value)

        isSynchronous_value = AutosarNode._get_node_text(node,'IS-SYNCHRONOUS')
        if isSynchronous_value is not None:
            self.__isSynchronous = datatype_utils.get_bool_value(isSynchronous_value)

        callType_value = AutosarNode._get_node_text(node,'CALL-TYPE')
        if callType_value is not None:
            self.__callType = BswCallType.get(callType_value)

        executionContext_value = AutosarNode._get_node_text(node,'EXECUTION-CONTEXT')
        if executionContext_value is not None:
            self.__executionContext = BswExecutionContext.get(executionContext_value)

        swServiceImplPolicy_value = AutosarNode._get_node_text(node,'SW-SERVICE-IMPL-POLICY')
        if swServiceImplPolicy_value is not None:
            self.__swServiceImplPolicy = SwServiceImplPolicyEnum.get(swServiceImplPolicy_value)

        bswEntryKind_value = AutosarNode._get_node_text(node,'BSW-ENTRY-KIND')
        if bswEntryKind_value is not None:
            self.__bswEntryKind = BswEntryKindEnum.get(bswEntryKind_value)

        returnType_node = self._node.find('{*}RETURN-TYPE')
        if returnType_node is not None:
            self.__returnType = SwServiceArg()._build(self, returnType_node)

        arguments_nodes = self._node.findall('{*}ARGUMENTS/*')
        for arguments_node in arguments_nodes:
            self.__arguments.add(SwServiceArg()._build(self, arguments_node))

        return self

    def get_functionPrototypeEmitter(self):
        return self.__functionPrototypeEmitter

    def set_functionPrototypeEmitter(self, value):
        self.__functionPrototypeEmitter = value
        functionPrototypeEmitter_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'FUNCTION-PROTOTYPE-EMITTER')
        functionPrototypeEmitter_xml_node.text = str(value) if value is not None else ''

    def get_serviceId(self):
        return self.__serviceId

    def set_serviceId(self, value):
        self.__serviceId = value
        serviceId_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'SERVICE-ID')
        serviceId_xml_node.text = str(value) if value is not None else ''

