class RptSupportData(ARObject):
    """
    Root element for rapid prototyping support data related to one Implementation artifact on an ECU, in particular the RTE. , The rapid prototyping support data may reference to elements provided for McSupportData.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'RPT-SUPPORT-DATA'
        self.__executionContexts = set()
        self.__rptComponents = set()
        self.__rptServicePoints = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        executionContexts_nodes = self._node.findall('{*}EXECUTION-CONTEXTS/*')
        for executionContexts_node in executionContexts_nodes:
            self.__executionContexts.add(RptExecutionContext()._build(self, executionContexts_node))

        rptComponents_nodes = self._node.findall('{*}RPT-COMPONENTS/*')
        for rptComponents_node in rptComponents_nodes:
            self.__rptComponents.add(RptComponent()._build(self, rptComponents_node))

        rptServicePoints_nodes = self._node.findall('{*}RPT-SERVICE-POINTS/*')
        for rptServicePoints_node in rptServicePoints_nodes:
            self.__rptServicePoints.add(RptServicePoint()._build(self, rptServicePoints_node))

        return self

    def get_executionContexts(self):
        return self.__executionContexts

    def add_executionContext(self, value):
        """
        Adds a single value to the executionContexts
        """
        if value is not None:
            if any(v.name == value.name for v in self.__executionContexts):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, RptExecutionContext) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of RptExecutionContext or its sub-classes'.format(value))
            self.__executionContexts.add(value)
            executionContexts_values = AutosarNode._add_or_get_xml_node(self._node, 'EXECUTION-CONTEXTS')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            executionContexts_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_executionContexts(self, values):
        """
        Adds a list of ref value to the executionContexts
        """
        for value in values:
            self.add_executionContext(value)

    def remove_executionContext(self, value):
        """
        Removes a single value from executionContexts
        """
        if value is not None:
            self.__executionContexts.remove(value)
            executionContexts_values = AutosarNode._add_or_get_xml_node(self._node, 'EXECUTION-CONTEXTS', createNode = False)
            executionContexts_values.remove(value._node)
            value._parent = None #No parent
            value._update_path() #resets the path

    def remove_executionContexts(self, values):
        """
        Removes a list of value from executionContexts
        """
        for value in values:
            self.remove_executionContext(value)

