class Implementation(ARElement):
    """
    Description of an implementation a single software component or module.
    """
    def __init__(self):
        super().__init__()
        self.__programmingLanguage = None
        self.__swVersion = None
        self.__usedCodeGenerator = None
        self.__vendorId = None
        self.__buildActionManifests = set()
        self.__codeDescriptors = set()
        self.__compilers = set()
        self.__generatedArtifacts = set()
        self.__hwElements = set()
        self.__linkers = set()
        self.__mcSupport = None
        self.__requiredArtifacts = set()
        self.__requiredGeneratorTools = set()
        self.__resourceConsumption = None
        self.__swcBswMapping = None

    def _build(self, parent, node):
        super()._build(parent, node)
        programmingLanguage_value = AutosarNode._get_node_text(node,'PROGRAMMING-LANGUAGE')
        if programmingLanguage_value is not None:
            self.__programmingLanguage = ProgramminglanguageEnum.get(programmingLanguage_value)

        swVersion_value = AutosarNode._get_node_text(node,'SW-VERSION')
        if swVersion_value is not None:
            self.__swVersion = datatype_utils.get_string_value(swVersion_value)

        usedCodeGenerator_value = AutosarNode._get_node_text(node,'USED-CODE-GENERATOR')
        if usedCodeGenerator_value is not None:
            self.__usedCodeGenerator = datatype_utils.get_string_value(usedCodeGenerator_value)

        vendorId_value = AutosarNode._get_node_text(node,'VENDOR-ID')
        if vendorId_value is not None:
            self.__vendorId = datatype_utils.get_int_value(vendorId_value)

        buildActionManifests_nodes = self._node.findall('{*}BUILD-ACTION-MANIFESTS/*')
        for buildActionManifests_node in buildActionManifests_nodes:
            self.__buildActionManifests.add(BuildActionManifestRefConditional()._build(self, buildActionManifests_node))

        codeDescriptors_nodes = self._node.findall('{*}CODE-DESCRIPTORS/*')
        for codeDescriptors_node in codeDescriptors_nodes:
            self.__codeDescriptors.add(Code()._build(self, codeDescriptors_node))

        compilers_nodes = self._node.findall('{*}COMPILERS/*')
        for compilers_node in compilers_nodes:
            self.__compilers.add(Compiler()._build(self, compilers_node))

        generatedArtifacts_nodes = self._node.findall('{*}GENERATED-ARTIFACTS/*')
        for generatedArtifacts_node in generatedArtifacts_nodes:
            self.__generatedArtifacts.add(DependencyOnArtifact()._build(self, generatedArtifacts_node))

        linkers_nodes = self._node.findall('{*}LINKERS/*')
        for linkers_node in linkers_nodes:
            self.__linkers.add(Linker()._build(self, linkers_node))

        mcSupport_node = self._node.find('{*}MC-SUPPORT')
        if mcSupport_node is not None:
            self.__mcSupport = McSupportData()._build(self, mcSupport_node)

        requiredArtifacts_nodes = self._node.findall('{*}REQUIRED-ARTIFACTS/*')
        for requiredArtifacts_node in requiredArtifacts_nodes:
            self.__requiredArtifacts.add(DependencyOnArtifact()._build(self, requiredArtifacts_node))

        requiredGeneratorTools_nodes = self._node.findall('{*}REQUIRED-GENERATOR-TOOLS/*')
        for requiredGeneratorTools_node in requiredGeneratorTools_nodes:
            self.__requiredGeneratorTools.add(DependencyOnArtifact()._build(self, requiredGeneratorTools_node))

        resourceConsumption_node = self._node.find('{*}RESOURCE-CONSUMPTION')
        if resourceConsumption_node is not None:
            self.__resourceConsumption = ResourceConsumption()._build(self, resourceConsumption_node)

        return self

    def _resolve_references(self):
        hwElements_nodes = self._node.findall('{*}HW-ELEMENT-REFS/*')
        for node in hwElements_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__hwElements.add(ref_value)
        swcBswMapping_node = self._node.find('{*}SWC-BSW-MAPPING-REF')
        if swcBswMapping_node is not None and swcBswMapping_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[swcBswMapping_node.text]
            ref_value.referenced_by.add(self)
            self.__swcBswMapping = ref_value

