class RuleArguments(ARObject):
    """
    This represents the arguments for a rule-based value specification.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'RULE-ARGUMENTS'
        self.__vs = None
        self.__vts = None
        self.__vfs = set()
        self.__vtfs = set()
        self.__variationPoints = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        vs_value = AutosarNode._get_node_text(node,'V')
        if vs_value is not None:
            self.__vs = datatype_utils.get_string_value(vs_value)

        vts_value = AutosarNode._get_node_text(node,'VT')
        if vts_value is not None:
            self.__vts = datatype_utils.get_string_value(vts_value)

        vfs_nodes = self._node.findall('{*}VFS/*')
        for vfs_node in vfs_nodes:
            self.__vfs.add(NumericalValueVariationPoint()._build(self, vfs_node))

        vtfs_nodes = self._node.findall('{*}VTFS/*')
        for vtfs_node in vtfs_nodes:
            self.__vtfs.add(NumericalOrText()._build(self, vtfs_node))

        variationPoints_nodes = self._node.findall('{*}VARIATION-POINTS/*')
        for variationPoints_node in variationPoints_nodes:
            self.__variationPoints.add(VariationPoint()._build(self, variationPoints_node))

        return self

