class Code(Identifiable):
    """
    A generic code descriptor. The type of the code (source or object) is defined via the category attribute of the associated engineering object.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'CODE'
        self.__artifactDescriptors = set()
        self.__callbackHeaders = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        artifactDescriptors_nodes = self._node.findall('{*}ARTIFACT-DESCRIPTORS/*')
        for artifactDescriptors_node in artifactDescriptors_nodes:
            self.__artifactDescriptors.add(AutosarEngineeringObject()._build(self, artifactDescriptors_node))

        return self

    def _resolve_references(self):
        callbackHeaders_nodes = self._node.findall('{*}CALLBACK-HEADER-REFS/*')
        for node in callbackHeaders_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__callbackHeaders.add(ref_value)

    def get_artifactDescriptors(self):
        return self.__artifactDescriptors

    def add_artifactDescriptor(self, value):
        """
        Adds a single value to the artifactDescriptors
        """
        if value is not None:
            if any(v.name == value.name for v in self.__artifactDescriptors):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, AutosarEngineeringObject) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of AutosarEngineeringObject or its sub-classes'.format(value))
            self.__artifactDescriptors.add(value)
            artifactDescriptors_values = AutosarNode._add_or_get_xml_node(self._node, 'ARTIFACT-DESCRIPTORS')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            artifactDescriptors_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_artifactDescriptors(self, values):
        """
        Adds a list of ref value to the artifactDescriptors
        """
        for value in values:
            self.add_artifactDescriptor(value)

    def remove_artifactDescriptor(self, value):
        """
        Removes a single value from artifactDescriptors
        """
        if value is not None:
            self.__artifactDescriptors.remove(value)
            artifactDescriptors_values = AutosarNode._add_or_get_xml_node(self._node, 'ARTIFACT-DESCRIPTORS', createNode = False)
            artifactDescriptors_values.remove(value._node)
            value._parent = None #No parent
            value._update_path() #resets the path

    def remove_artifactDescriptors(self, values):
        """
        Removes a list of value from artifactDescriptors
        """
        for value in values:
            self.remove_artifactDescriptor(value)

    def get_callbackHeaders(self):
        return self.__callbackHeaders

    def add_callbackHeader(self, value):
        """
        Adds a single value to the callbackHeaders
        """
        if value is not None:
            if any(v.name == value.name for v in self.__callbackHeaders):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, ServiceNeeds) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ServiceNeeds or its sub-classes'.format(value))
            self.__callbackHeaders.add(value)
            callbackHeaders_values = AutosarNode._add_or_get_xml_node(self._node, 'CALLBACK-HEADER-REFS')

            callbackHeaders_value = AutosarNode._add_or_get_xml_node(callbackHeaders_values, 'CALLBACK-HEADER-REF', value, forceCreate = True)
            callbackHeaders_value.text = value.path
            value.referenced_by.add(self)

    def set_callbackHeaders(self, values):
        """
        Adds a list of ref value to the callbackHeaders
        """
        for value in values:
            self.add_callbackHeader(value)

    def remove_callbackHeader(self, value):
        """
        Removes a single value from callbackHeaders
        """
        if value is not None:
            self.__callbackHeaders.remove(value)
            callbackHeaders_values = AutosarNode._add_or_get_xml_node(self._node, 'CALLBACK-HEADER-REFS', createNode = False)
            for callbackHeaders_value in self._node.findall('{*}CALLBACK-HEADER-REFS/*'):
                if callbackHeaders_value.text == value.path:
                    callbackHeaders_value.text = ''
                    callbackHeaders_values.remove(callbackHeaders_value)
                    value.referenced_by.remove(self)
                    break

    def remove_callbackHeaders(self, values):
        """
        Removes a list of value from callbackHeaders
        """
        for value in values:
            self.remove_callbackHeader(value)

    def new_ArtifactDescriptor(self, name=None):
        """
        Creates a new AutosarEngineeringObject under the Code.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        AutosarEngineeringObject_obj = AutosarEngineeringObject()
        if isinstance(AutosarEngineeringObject_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('AUTOSAR-ENGINEERING-OBJECT')
        AutosarEngineeringObject_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        AutosarEngineeringObject_obj.name = name
        AutosarEngineeringObject_obj._node = xmlNode
        self.add_artifactDescriptor(AutosarEngineeringObject_obj)
        return AutosarEngineeringObject_obj

    def get_children(self):
        children = super().get_children()
        children.extend(self.__artifactDescriptors)
        return children

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['CallbackHeaders'] = self.__callbackHeaders
        return property_values

    def _update_path(self):
        """
        Updates the path of the Code and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

