class Prms(Paginateable):
    """
    This metaclass represents the ability to specify a parameter table. It can be used e.g. to specify parameter tables in a data sheet.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'PRMS'
        self.__label = None
        self.__prms = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        label_node = self._node.find('{*}LABEL')
        if label_node is not None:
            self.__label = MultilanguageLongName()._build(self, label_node)

        prms_nodes = self._node.findall('{*}PRMS/*')
        for prms_node in prms_nodes:
            self.__prms.add(GeneralParameter()._build(self, prms_node))

        return self

    def get_label(self):
        return self.__label

    def set_label(self, value):
        """
        Adds a single value to the label
        """
        if value is not None:
            if isinstance(value, MultilanguageLongName) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of MultilanguageLongName or its sub-classes'.format(value))
            if self.__label is not None:
                self._node.remove(self.__label._node)
            # if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            self._node.append(value._node)
            self.__label = value
            value._parent = self #set parent
            value._update_path() #updates the path
        elif self.__label is not None:
            self._node.remove(self.__label._node)
            self.__label = None
            self.__label._parent = None #No parent
            self.__label._update_path() #updates the path

    def get_prms(self):
        return self.__prms

    def add_prm(self, value):
        """
        Adds a single value to the prms
        """
        if value is not None:
            if any(v.name == value.name for v in self.__prms):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, GeneralParameter) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of GeneralParameter or its sub-classes'.format(value))
            self.__prms.add(value)
            prms_values = AutosarNode._add_or_get_xml_node(self._node, 'PRMS')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            prms_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_prms(self, values):
        """
        Adds a list of ref value to the prms
        """
        for value in values:
            self.add_prm(value)

    def remove_prm(self, value):
        """
        Removes a single value from prms
        """
        if value is not None:
            self.__prms.remove(value)
            prms_values = AutosarNode._add_or_get_xml_node(self._node, 'PRMS', createNode = False)
            prms_values.remove(value._node)
            value._parent = None #No parent
            value._update_path() #resets the path

    def remove_prms(self, values):
        """
        Removes a list of value from prms
        """
        for value in values:
            self.remove_prm(value)

    def new_Label(self, name=None):
        """
        Creates a new MultilanguageLongName under the Prms.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        MultilanguageLongName_obj = MultilanguageLongName()
        if isinstance(MultilanguageLongName_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
