class DiagnosticComControlSpecificChannel(ARObject):
    """
    This represents the ability to add further attributes to the definition of a specific channel that is subject to the diagnostic service "communication control".
    """
    def __init__(self):
        super().__init__()
        self.tag = 'DIAGNOSTIC-COM-CONTROL-SPECIFIC-CHANNEL'
        self.__subnetNumber = None
        self.__specificChannel = None

    def _build(self, parent, node):
        super()._build(parent, node)
        subnetNumber_value = AutosarNode._get_node_text(node,'SUBNET-NUMBER')
        if subnetNumber_value is not None:
            self.__subnetNumber = datatype_utils.get_int_value(subnetNumber_value)

        return self

    def _resolve_references(self):
        specificChannel_node = self._node.find('{*}SPECIFIC-CHANNEL-REF')
        if specificChannel_node is not None and specificChannel_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[specificChannel_node.text]
            ref_value.referenced_by.add(self)
            self.__specificChannel = ref_value

    def get_subnetNumber(self):
        return self.__subnetNumber

    def set_subnetNumber(self, value):
        self.__subnetNumber = value
        subnetNumber_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'SUBNET-NUMBER')
        subnetNumber_xml_node.text = str(value) if value is not None else ''

    def get_specificChannel(self):
        return self.__specificChannel

    def set_specificChannel(self, value):
        """
        Adds a single value to the specificChannel
        """
        if value is not None:
            if isinstance(value, CommunicationCluster) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of CommunicationCluster or its sub-classes'.format(value))
            if self.__specificChannel is not None:
                self.__specificChannel.referenced_by.remove(self)
            specificChannel_value = AutosarNode._add_or_get_xml_node(self._node, 'SPECIFIC-CHANNEL-REF', value)
            specificChannel_value.text = value.path
            specificChannel_value.attrib['DEST'] = value.tag
            self.__specificChannel = value
            value.referenced_by.add(self)
        elif self.__specificChannel is not None:
            self.__specificChannel.referenced_by.remove(self)
            self.__specificChannel = None
            specificChannel_value = AutosarNode._add_or_get_xml_node(self._node, 'SPECIFIC-CHANNEL-REF', createNode = False)
            if specificChannel_value is not None:
                specificChannel_value.referenced_by.remove(self)
                specificChannel_value.text = ''

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['SubnetNumber'] = self.__subnetNumber
        property_values['SpecificChannel'] = self.__specificChannel
        return property_values

    def _update_path(self):
        """
        Updates the path of the DiagnosticComControlSpecificChannel and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

