class ClientServerInterface(PortInterface):
    """
    A client/server interface declares a number of operations that can be invoked on a server by a client.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'CLIENT-SERVER-INTERFACE'
        self.__operations = set()
        self.__possibleErrors = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        operations_nodes = self._node.findall('{*}OPERATIONS/*')
        for operations_node in operations_nodes:
            self.__operations.add(ClientServerOperation()._build(self, operations_node))

        possibleErrors_nodes = self._node.findall('{*}POSSIBLE-ERRORS/*')
        for possibleErrors_node in possibleErrors_nodes:
            self.__possibleErrors.add(ApplicationError()._build(self, possibleErrors_node))

        return self

    def get_operations(self):
        return self.__operations

    def add_operation(self, value):
        """
        Adds a single value to the operations
        """
        if value is not None:
            if any(v.name == value.name for v in self.__operations):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, ClientServerOperation) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ClientServerOperation or its sub-classes'.format(value))
            self.__operations.add(value)
            operations_values = AutosarNode._add_or_get_xml_node(self._node, 'OPERATIONS')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            operations_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_operations(self, values):
        """
        Adds a list of ref value to the operations
        """
        for value in values:
            self.add_operation(value)

    def remove_operation(self, value):
        """
        Removes a single value from operations
        """
        if value is not None:
            self.__operations.remove(value)
            operations_values = AutosarNode._add_or_get_xml_node(self._node, 'OPERATIONS', createNode = False)
            operations_values.remove(value._node)
            value._parent = None #No parent
            value._update_path() #resets the path

    def remove_operations(self, values):
        """
        Removes a list of value from operations
        """
        for value in values:
            self.remove_operation(value)

    def get_possibleErrors(self):
        return self.__possibleErrors

    def add_possibleError(self, value):
        """
        Adds a single value to the possibleErrors
        """
        if value is not None:
            if any(v.name == value.name for v in self.__possibleErrors):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, ApplicationError) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ApplicationError or its sub-classes'.format(value))
            self.__possibleErrors.add(value)
            possibleErrors_values = AutosarNode._add_or_get_xml_node(self._node, 'POSSIBLE-ERRORS')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            possibleErrors_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_possibleErrors(self, values):
        """
        Adds a list of ref value to the possibleErrors
        """
        for value in values:
            self.add_possibleError(value)

    def remove_possibleError(self, value):
        """
        Removes a single value from possibleErrors
        """
