class DataTransformation(Identifiable):
    """
    A DataTransformation represents a transformer chain. It is an ordered list of transformers.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'DATA-TRANSFORMATION'
        self.__dataTransformationKind = None
        self.__executeDespiteDataUnavailability = None
        self.__transformerChains = set()
        self.__variationPoint = None

    def _build(self, parent, node):
        super()._build(parent, node)
        dataTransformationKind_value = AutosarNode._get_node_text(node,'DATA-TRANSFORMATION-KIND')
        if dataTransformationKind_value is not None:
            self.__dataTransformationKind = DataTransformationKindEnum.get(dataTransformationKind_value)

        executeDespiteDataUnavailability_value = AutosarNode._get_node_text(node,'EXECUTE-DESPITE-DATA-UNAVAILABILITY')
        if executeDespiteDataUnavailability_value is not None:
            self.__executeDespiteDataUnavailability = datatype_utils.get_bool_value(executeDespiteDataUnavailability_value)

        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            self.__variationPoint = VariationPoint()._build(self, variationPoint_node)

        return self

    def _resolve_references(self):
        transformerChains_nodes = self._node.findall('{*}TRANSFORMER-CHAIN-REFS/*')
        for node in transformerChains_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__transformerChains.add(ref_value)

    def get_dataTransformationKind(self):
        return self.__dataTransformationKind

    def set_dataTransformationKind(self, value):
        self.__dataTransformationKind = value
        dataTransformationKind_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'DATA-TRANSFORMATION-KIND')
        dataTransformationKind_xml_node.text = value.literal if value is not None else ''

    def get_executeDespiteDataUnavailability(self):
        return self.__executeDespiteDataUnavailability

    def set_executeDespiteDataUnavailability(self, value):
        self.__executeDespiteDataUnavailability = value
        executeDespiteDataUnavailability_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'EXECUTE-DESPITE-DATA-UNAVAILABILITY')
        executeDespiteDataUnavailability_xml_node.text = 'true' if value is True else 'false'

    def get_transformerChains(self):
        return self.__transformerChains

    def add_transformerChain(self, value):
        """
        Adds a single value to the transformerChains
        """
        if value is not None:
            if any(v.name == value.name for v in self.__transformerChains):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, TransformationTechnology) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of TransformationTechnology or its sub-classes'.format(value))
            self.__transformerChains.add(value)
            transformerChains_values = AutosarNode._add_or_get_xml_node(self._node, 'TRANSFORMER-CHAIN-REFS')

            transformerChains_value = AutosarNode._add_or_get_xml_node(transformerChains_values, 'TRANSFORMER-CHAIN-REF', value, forceCreate = True)
            transformerChains_value.text = value.path
            value.referenced_by.add(self)

    def set_transformerChains(self, values):
        """
        Adds a list of ref value to the transformerChains
        """
        for value in values:
            self.add_transformerChain(value)

    def remove_transformerChain(self, value):
        """
        Removes a single value from transformerChains
        """
        if value is not None:
            self.__transformerChains.remove(value)
            transformerChains_values = AutosarNode._add_or_get_xml_node(self._node, 'TRANSFORMER-CHAIN-REFS', createNode = False)
            for transformerChains_value in self._node.findall('{*}TRANSFORMER-CHAIN-REFS/*'):
                if transformerChains_value.text == value.path:
                    transformerChains_value.text = ''
                    transformerChains_values.remove(transformerChains_value)
                    value.referenced_by.remove(self)
                    break

    def remove_transformerChains(self, values):
        """
        Removes a list of value from transformerChains
        """
        for value in values:
            self.remove_transformerChain(value)

    def get_variationPoint(self):
        return self.__variationPoint

    def set_variationPoint(self, value):
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))
            if self.__variationPoint is not None:
                self._node.remove(self.__variationPoint._node)
            # if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            self._node.append(value._node)
            self.__variationPoint = value
            value._parent = self #set parent
            value._update_path() #updates the path
        elif self.__variationPoint is not None:
            self._node.remove(self.__variationPoint._node)
            self.__variationPoint = None
            self.__variationPoint._parent = None #No parent
            self.__variationPoint._update_path() #updates the path

    def new_VariationPoint(self, name=None):
        """
        Creates a new VariationPoint under the DataTransformation.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        VariationPoint_obj = VariationPoint()
        if isinstance(VariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('VARIATION-POINT')
        VariationPoint_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        VariationPoint_obj.name = name
        VariationPoint_obj._node = xmlNode
        self.set_variationPoint(VariationPoint_obj)
        return VariationPoint_obj

    def _add_mandatory_attr(self, node, name = None):
        super()._add_mandatory_attr(node, name)
        executeDespiteDataUnavailability_node = etree.SubElement(node, 'EXECUTE-DESPITE-DATA-UNAVAILABILITY')
        self.__executeDespiteDataUnavailability = False
        executeDespiteDataUnavailability_node.text = 'false'

    def get_children(self):
        children = super().get_children()
        if self.__variationPoint is not None:
            children.append(self.__variationPoint)
        return children

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['DataTransformationKind'] = self.__dataTransformationKind
        property_values['ExecuteDespiteDataUnavailability'] = self.__executeDespiteDataUnavailability
        property_values['TransformerChains'] = self.__transformerChains
        return property_values

    def _update_path(self):
        """
        Updates the path of the DataTransformation and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

