class UcmStep(Identifiable):
    """
    This meta-class represents the ability to define a rollout-condition for a vehicle update campaign.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'UCM-STEP'
        self.__softwarePackageSteps = set()
        self.__ucm = None

    def _build(self, parent, node):
        super()._build(parent, node)
        softwarePackageSteps_nodes = self._node.findall('{*}SOFTWARE-PACKAGE-STEPS/*')
        for softwarePackageSteps_node in softwarePackageSteps_nodes:
            self.__softwarePackageSteps.add(SoftwarePackageStep()._build(self, softwarePackageSteps_node))

        return self

    def _resolve_references(self):
        ucm_node = self._node.find('{*}UCM-REF')
        if ucm_node is not None and ucm_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[ucm_node.text]
            ref_value.referenced_by.add(self)
            self.__ucm = ref_value

