class DiagnosticStopRoutine(DiagnosticRoutineSubfunction):
    """
    This represents the ability to stop a diagnostic routine.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'DIAGNOSTIC-STOP-ROUTINE'
        self.__requests = set()
        self.__responses = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        requests_nodes = self._node.findall('{*}REQUESTS/*')
        for requests_node in requests_nodes:
            self.__requests.add(DiagnosticParameter()._build(self, requests_node))

        responses_nodes = self._node.findall('{*}RESPONSES/*')
        for responses_node in responses_nodes:
            self.__responses.add(DiagnosticParameter()._build(self, responses_node))

        return self

    def get_requests(self):
        return self.__requests

    def add_request(self, value):
        """
        Adds a single value to the requests
        """
        if value is not None:
            if any(v.name == value.name for v in self.__requests):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, DiagnosticParameter) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of DiagnosticParameter or its sub-classes'.format(value))
            self.__requests.add(value)
            requests_values = AutosarNode._add_or_get_xml_node(self._node, 'REQUESTS')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            requests_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

