class MemorySection(Identifiable):
    """
    Provides a description of an abstract memory section used in the Implementation for code or data. It shall be declared by the Implementation Description of the module or component, which actually allocates the memory in its code. This means in case of data prototypes which are allocated by the RTE, that the generated Implementation Description of the RTE shall contain the corresponding MemorySections., , The attribute "symbol" (if symbol is missing: "shortName") defines the module or component specific section name used in the code. For details see the document "Specification of Memory Mapping"., Typically the section name is build according the pattern:, , <SwAddrMethod shortName>[_<further specialization nominator>][_<alignment>] , where, * '''[<SwAddrMethod shortName>]''' is the shortName of the referenced SwAddrMethod, * '''[_<further specialization nominator>]''' is an optional infix to indicate the specialization in the case that several MemorySections for different purpose of the same Implementation Description referring to the same or equally named SwAddrMethods. , * '''[_<alignment>]''' is the alignment attributes value and is only applicable in the case that the memoryAllocationKeywordPolicy value of the referenced SwAddrMethod is set to addrMethodShortNameAndAlignment , , MemorySection used to Implement the code of RunnableEntitys and BswSchedulableEntitys shall have a symbol (if missing: shortName) identical to the referred SwAddrMethod to conform to the generated RTE header files.   , , In addition to the section name described above, a prefix is used in the corresponding macro code in order to define a name space. This prefix is by default given by the shortName of the BswModuleDescription resp. the SwComponentType. It can be superseded by  the prefix attribute.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'MEMORY-SECTION'
        self.__alignment = None
        self.__memClassSymbol = None
        self.__options = None
        self.__size = None
        self.__symbol = None
        self.__executableEntities = set()
        self.__prefix = None
        self.__swAddrmethod = None
        self.__variationPoint = None

    def _build(self, parent, node):
        super()._build(parent, node)
        alignment_value = AutosarNode._get_node_text(node,'ALIGNMENT')
        if alignment_value is not None:
            self.__alignment = datatype_utils.get_string_value(alignment_value)

        memClassSymbol_value = AutosarNode._get_node_text(node,'MEM-CLASS-SYMBOL')
        if memClassSymbol_value is not None:
            self.__memClassSymbol = datatype_utils.get_string_value(memClassSymbol_value)

        options_value = AutosarNode._get_node_text(node,'OPTION')
        if options_value is not None:
            self.__options = datatype_utils.get_string_value(options_value)

        size_value = AutosarNode._get_node_text(node,'SIZE')
        if size_value is not None:
            self.__size = datatype_utils.get_int_value(size_value)

        symbol_value = AutosarNode._get_node_text(node,'SYMBOL')
        if symbol_value is not None:
            self.__symbol = datatype_utils.get_string_value(symbol_value)

        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            self.__variationPoint = VariationPoint()._build(self, variationPoint_node)

        return self

    def _resolve_references(self):
        executableEntities_nodes = self._node.findall('{*}EXECUTABLE-ENTITY-REFS/*')
        for node in executableEntities_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__executableEntities.add(ref_value)
        prefix_node = self._node.find('{*}PREFIX-REF')
        if prefix_node is not None and prefix_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[prefix_node.text]
            ref_value.referenced_by.add(self)
            self.__prefix = ref_value
        swAddrmethod_node = self._node.find('{*}SW-ADDRMETHOD-REF')
        if swAddrmethod_node is not None and swAddrmethod_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[swAddrmethod_node.text]
            ref_value.referenced_by.add(self)
            self.__swAddrmethod = ref_value

    def get_alignment(self):
        return self.__alignment

    def set_alignment(self, value):
        self.__alignment = value
        alignment_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'ALIGNMENT')
        alignment_xml_node.text = str(value) if value is not None else ''

    def get_memClassSymbol(self):
        return self.__memClassSymbol

    def set_memClassSymbol(self, value):
        self.__memClassSymbol = value
        memClassSymbol_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'MEM-CLASS-SYMBOL')
        memClassSymbol_xml_node.text = str(value) if value is not None else ''

