class ReferenceTailoring(AttributeTailoring):
    """
    Tailoring of Non-Containment References.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'REFERENCE-TAILORING'
        self.__typeTailorings = set()
        self.__unresolvedReferenceRestriction = None

    def _build(self, parent, node):
        super()._build(parent, node)
        typeTailorings_obj_dict = {}
        typeTailorings_obj_dict['CONCRETE-CLASS-TAILORING'] = 'ConcreteClassTailoring'
        typeTailorings_obj_dict['ABSTRACT-CLASS-TAILORING'] = 'AbstractClassTailoring'
        typeTailorings_nodes = self._node.findall('{*}TYPE-TAILORINGS/*')
        for typeTailorings_node in typeTailorings_nodes:
            self.__typeTailorings.add(__str_to_class__(typeTailorings_obj_dict[etree.QName(typeTailorings_node).localname])()._build(self, typeTailorings_node))

        unresolvedReferenceRestriction_node = self._node.find('{*}UNRESOLVED-REFERENCE-RESTRICTION')
        if unresolvedReferenceRestriction_node is not None:
            self.__unresolvedReferenceRestriction = UnresolvedReferenceRestrictionWithSeverity()._build(self, unresolvedReferenceRestriction_node)

        return self

    def get_typeTailorings(self):
        return self.__typeTailorings

    def add_typeTailoring(self, value):
        """
        Adds a single value to the typeTailorings
        """
        if value is not None:
            if any(v.name == value.name for v in self.__typeTailorings):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, ClassTailoring) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ClassTailoring or its sub-classes'.format(value))
            self.__typeTailorings.add(value)
            typeTailorings_values = AutosarNode._add_or_get_xml_node(self._node, 'TYPE-TAILORINGS')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            typeTailorings_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_typeTailorings(self, values):
        """
        Adds a list of ref value to the typeTailorings
        """
        for value in values:
            self.add_typeTailoring(value)

    def remove_typeTailoring(self, value):
        """
        Removes a single value from typeTailorings
        """
        if value is not None:
            self.__typeTailorings.remove(value)
            typeTailorings_values = AutosarNode._add_or_get_xml_node(self._node, 'TYPE-TAILORINGS', createNode = False)
            typeTailorings_values.remove(value._node)
            value._parent = None #No parent
            value._update_path() #resets the path

    def remove_typeTailorings(self, values):
        """
        Removes a list of value from typeTailorings
        """
        for value in values:
            self.remove_typeTailoring(value)

    def get_unresolvedReferenceRestriction(self):
        return self.__unresolvedReferenceRestriction

    def set_unresolvedReferenceRestriction(self, value):
        """
        Adds a single value to the unresolvedReferenceRestriction
        """
        if value is not None:
            if isinstance(value, UnresolvedReferenceRestrictionWithSeverity) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of UnresolvedReferenceRestrictionWithSeverity or its sub-classes'.format(value))
            if self.__unresolvedReferenceRestriction is not None:
                self._node.remove(self.__unresolvedReferenceRestriction._node)
