class SeparateSignalPath(SignalPathConstraint):
    """
    The SeparateSignalPath describes that two SwcToSwcSignals and/or SwcToSwcOperationArguments shall not take the same way (Signal Path) in the topology (e.g. Redundancy). , This means that the signals are not allowed to share even a single physical channel in their path.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'SEPARATE-SIGNAL-PATH'
        self.__operations = set()
        self.__signals = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        operations_nodes = self._node.findall('{*}OPERATIONS/*')
        for operations_node in operations_nodes:
            self.__operations.add(SwcToSwcOperationArguments()._build(self, operations_node))

        signals_nodes = self._node.findall('{*}SIGNALS/*')
        for signals_node in signals_nodes:
            self.__signals.add(SwcToSwcSignal()._build(self, signals_node))

        return self

    def get_operations(self):
        return self.__operations

    def add_operation(self, value):
        """
        Adds a single value to the operations
        """
        if value is not None:
            if any(v.name == value.name for v in self.__operations):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, SwcToSwcOperationArguments) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of SwcToSwcOperationArguments or its sub-classes'.format(value))
            self.__operations.add(value)
            operations_values = AutosarNode._add_or_get_xml_node(self._node, 'OPERATIONS')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            operations_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_operations(self, values):
        """
        Adds a list of ref value to the operations
        """
        for value in values:
            self.add_operation(value)

    def remove_operation(self, value):
        """
        Removes a single value from operations
        """
        if value is not None:
            self.__operations.remove(value)
            operations_values = AutosarNode._add_or_get_xml_node(self._node, 'OPERATIONS', createNode = False)
            operations_values.remove(value._node)
            value._parent = None #No parent
            value._update_path() #resets the path

    def remove_operations(self, values):
        """
        Removes a list of value from operations
        """
        for value in values:
            self.remove_operation(value)

    def get_signals(self):
        return self.__signals

    def add_signal(self, value):
        """
        Adds a single value to the signals
        """
        if value is not None:
            if any(v.name == value.name for v in self.__signals):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, SwcToSwcSignal) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of SwcToSwcSignal or its sub-classes'.format(value))
            self.__signals.add(value)
            signals_values = AutosarNode._add_or_get_xml_node(self._node, 'SIGNALS')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            signals_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_signals(self, values):
        """
        Adds a list of ref value to the signals
        """
        for value in values:
            self.add_signal(value)

    def remove_signal(self, value):
        """
        Removes a single value from signals
        """
        if value is not None:
            self.__signals.remove(value)
            signals_values = AutosarNode._add_or_get_xml_node(self._node, 'SIGNALS', createNode = False)
            signals_values.remove(value._node)
            value._parent = None #No parent
            value._update_path() #resets the path

    def remove_signals(self, values):
        """
        Removes a list of value from signals
        """
        for value in values:
            self.remove_signal(value)

    def new_Signal(self, name=None):
        """
        Creates a new SwcToSwcSignal under the SeparateSignalPath.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        SwcToSwcSignal_obj = SwcToSwcSignal()
        if isinstance(SwcToSwcSignal_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('SWC-TO-SWC-SIGNAL')
        SwcToSwcSignal_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        SwcToSwcSignal_obj.name = name
        SwcToSwcSignal_obj._node = xmlNode
        self.add_signal(SwcToSwcSignal_obj)
        return SwcToSwcSignal_obj

