class CanTpConfig(TpConfig):
    """
    This element defines exactly one CAN TP Configuration. , , One CanTpConfig element shall be created for each CAN Network in the System.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'CAN-TP-CONFIG'
        self.__tpAddress = set()
        self.__tpChannels = set()
        self.__tpConnections = set()
        self.__tpEcus = set()
        self.__tpNodes = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        tpAddress_nodes = self._node.findall('{*}TP-ADDRESSS/*')
        for tpAddress_node in tpAddress_nodes:
            self.__tpAddress.add(CanTpAddress()._build(self, tpAddress_node))

        tpChannels_nodes = self._node.findall('{*}TP-CHANNELS/*')
        for tpChannels_node in tpChannels_nodes:
            self.__tpChannels.add(CanTpChannel()._build(self, tpChannels_node))

        tpConnections_nodes = self._node.findall('{*}TP-CONNECTIONS/*')
        for tpConnections_node in tpConnections_nodes:
            self.__tpConnections.add(CanTpConnection()._build(self, tpConnections_node))

        tpEcus_nodes = self._node.findall('{*}TP-ECUS/*')
        for tpEcus_node in tpEcus_nodes:
            self.__tpEcus.add(CanTpEcu()._build(self, tpEcus_node))

        tpNodes_nodes = self._node.findall('{*}TP-NODES/*')
        for tpNodes_node in tpNodes_nodes:
            self.__tpNodes.add(CanTpNode()._build(self, tpNodes_node))

        return self

