class RunnableEntity(AtpStructureElement,ExecutableEntity):
    """
    A RunnableEntity represents the smallest code-fragment that is provided by an AtomicSwComponentType and are executed under control of the RTE. RunnableEntities are for instance set up to respond to data reception or operation invocation on a server.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'RUNNABLE-ENTITY'
        self.__canBeInvokedConcurrently = None
        self.__symbol = None
        self.__arguments = set()
        self.__asynchronousServerCallResultPoints = set()
        self.__dataReadAccess = set()
        self.__dataReceivePointByArguments = set()
        self.__dataReceivePointByValues = set()
        self.__dataSendPoints = set()
        self.__dataWriteAccess = set()
        self.__externalTriggeringPoints = set()
        self.__internalTriggeringPoints = set()
        self.__modeAccessPoints = set()
        self.__modeSwitchPoints = set()
        self.__parameterAccess = set()
        self.__readLocalVariables = set()
        self.__serverCallPoints = set()
        self.__waitPoints = set()
        self.__writtenLocalVariables = set()
        self.__variationPoint = None

    def _build(self, parent, node):
        super()._build(parent, node)
        canBeInvokedConcurrently_value = AutosarNode._get_node_text(node,'CAN-BE-INVOKED-CONCURRENTLY')
        if canBeInvokedConcurrently_value is not None:
            self.__canBeInvokedConcurrently = datatype_utils.get_bool_value(canBeInvokedConcurrently_value)

        symbol_value = AutosarNode._get_node_text(node,'SYMBOL')
        if symbol_value is not None:
            self.__symbol = datatype_utils.get_string_value(symbol_value)

        arguments_nodes = self._node.findall('{*}ARGUMENTS/*')
        for arguments_node in arguments_nodes:
            self.__arguments.add(RunnableEntityArgument()._build(self, arguments_node))

        asynchronousServerCallResultPoints_nodes = self._node.findall('{*}ASYNCHRONOUS-SERVER-CALL-RESULT-POINTS/*')
        for asynchronousServerCallResultPoints_node in asynchronousServerCallResultPoints_nodes:
            self.__asynchronousServerCallResultPoints.add(AsynchronousServerCallResultPoint()._build(self, asynchronousServerCallResultPoints_node))

        dataReadAccess_nodes = self._node.findall('{*}DATA-READ-ACCESSS/*')
