class ArParameterInImplementationDataInstanceRef(ARObject):
    """
    This class represents the ability to navigate into an element inside of an ParameterDataPrototype typed  by an ImplementationDatatype., , Note that it shall not be used if the target is the ParameterDataPrototype itself (e.g. if the target is a primitive data type)., , Note that this class follows the pattern of an InstanceRef but is not implemented based on the abstract classes because the ImplementationDataType isn't either, especially because ImplementationDataTypeElement (intentionally) isn't derived from AtpPrototype.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'AR-PARAMETER-IN-IMPLEMENTATION-DATA-INSTANCE-REF'
        self.__contextDataPrototypes = set()
        self.__portPrototype = None
        self.__rootParameterDataPrototype = None
        self.__targetDataPrototype = None


    def _resolve_references(self):
        contextDataPrototypes_nodes = self._node.findall('{*}CONTEXT-DATA-PROTOTYPE-REFS/*')
        for node in contextDataPrototypes_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__contextDataPrototypes.add(ref_value)
        portPrototype_node = self._node.find('{*}PORT-PROTOTYPE-REF')
        if portPrototype_node is not None and portPrototype_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[portPrototype_node.text]
            ref_value.referenced_by.add(self)
            self.__portPrototype = ref_value
        rootParameterDataPrototype_node = self._node.find('{*}ROOT-PARAMETER-DATA-PROTOTYPE-REF')
        if rootParameterDataPrototype_node is not None and rootParameterDataPrototype_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[rootParameterDataPrototype_node.text]
            ref_value.referenced_by.add(self)
            self.__rootParameterDataPrototype = ref_value
        targetDataPrototype_node = self._node.find('{*}TARGET-DATA-PROTOTYPE-REF')
        if targetDataPrototype_node is not None and targetDataPrototype_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[targetDataPrototype_node.text]
            ref_value.referenced_by.add(self)
            self.__targetDataPrototype = ref_value

