        """
        Removes a single value from contextDataPrototypes
        """
        if value is not None:
            self.__contextDataPrototypes.remove(value)
            contextDataPrototypes_values = AutosarNode._add_or_get_xml_node(self._node, 'CONTEXT-DATA-PROTOTYPE-REFS', createNode = False)
            for contextDataPrototypes_value in self._node.findall('{*}CONTEXT-DATA-PROTOTYPE-REFS/*'):
                if contextDataPrototypes_value.text == value.path:
                    contextDataPrototypes_value.text = ''
                    contextDataPrototypes_values.remove(contextDataPrototypes_value)
                    value.referenced_by.remove(self)
