class UnitGroup(ARElement):
    """
    This meta-class represents the ability to specify a logical grouping of units.The category denotes the unit system that the referenced units are associated to. , , In this way, e.g. country-specific unit systems (CATEGORY="COUNTRY") can be defined as well as specific unit systems for certain application domains. , , In the same way a group of equivalent units, can be defined which are used in different countries, by setting CATEGORY="EQUIV_UNITS".  KmPerHour and MilesPerHour could such be combined to one group named "vehicle_speed". The unit MeterPerSec would not belong to this group because it is normally not used for vehicle speed. But all of the mentioned units could be combined to one group named "speed"., , Note that the UnitGroup does not ensure the physical compliance of the units. This is maintained by the physical dimension.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'UNIT-GROUP'
        self.__units = set()


    def _resolve_references(self):
        units_nodes = self._node.findall('{*}UNIT-REFS/*')
        for node in units_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__units.add(ref_value)

    def get_units(self):
        return self.__units

    def add_unit(self, value):
        """
        Adds a single value to the units
        """
        if value is not None:
            if any(v.name == value.name for v in self.__units):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, Unit) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of Unit or its sub-classes'.format(value))
            self.__units.add(value)
            units_values = AutosarNode._add_or_get_xml_node(self._node, 'UNIT-REFS')

            units_value = AutosarNode._add_or_get_xml_node(units_values, 'UNIT-REF', value, forceCreate = True)
            units_value.text = value.path
            value.referenced_by.add(self)

    def set_units(self, values):
        """
        Adds a list of ref value to the units
        """
        for value in values:
            self.add_unit(value)

    def remove_unit(self, value):
        """
        Removes a single value from units
        """
        if value is not None:
            self.__units.remove(value)
            units_values = AutosarNode._add_or_get_xml_node(self._node, 'UNIT-REFS', createNode = False)
            for units_value in self._node.findall('{*}UNIT-REFS/*'):
                if units_value.text == value.path:
                    units_value.text = ''
                    units_values.remove(units_value)
                    value.referenced_by.remove(self)
                    break

    def remove_units(self, values):
        """
        Removes a list of value from units
        """
        for value in values:
            self.remove_unit(value)

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['Units'] = self.__units
        return property_values

    def _update_path(self):
        """
        Updates the path of the UnitGroup and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

