        if isinstance(LOverviewParagraph_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('L-2')
        LOverviewParagraph_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        LOverviewParagraph_obj.name = name
