class ModeInSwcInstanceRef(AtpInstanceRef,ModeInSwcBswInstanceRef):
    """
    Instance reference to be capable of referencing a ModeDeclaration at a specific Mode Switch Port of a SW-C.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'MODE-IN-SWC-INSTANCE-REF-IREF'
        self.__contextComponents = set()
        self.__contextPort = None
        self.__contextModeDeclarationGroupPrototype = None
        self.__targetModeDeclaration = None


    def _resolve_references(self):
        contextComponents_nodes = self._node.findall('{*}CONTEXT-COMPONENT-REFS/*')
        for node in contextComponents_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__contextComponents.add(ref_value)
        contextPort_node = self._node.find('{*}CONTEXT-PORT-REF')
        if contextPort_node is not None and contextPort_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[contextPort_node.text]
            ref_value.referenced_by.add(self)
            self.__contextPort = ref_value
        contextModeDeclarationGroupPrototype_node = self._node.find('{*}CONTEXT-MODE-DECLARATION-GROUP-PROTOTYPE-REF')
        if contextModeDeclarationGroupPrototype_node is not None and contextModeDeclarationGroupPrototype_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[contextModeDeclarationGroupPrototype_node.text]
            ref_value.referenced_by.add(self)
            self.__contextModeDeclarationGroupPrototype = ref_value
        targetModeDeclaration_node = self._node.find('{*}TARGET-MODE-DECLARATION-REF')
        if targetModeDeclaration_node is not None and targetModeDeclaration_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[targetModeDeclaration_node.text]
            ref_value.referenced_by.add(self)
            self.__targetModeDeclaration = ref_value

    def get_contextComponents(self):
        return self.__contextComponents

    def add_contextComponent(self, value):
        """
        Adds a single value to the contextComponents
        """
        if value is not None:
            if any(v.name == value.name for v in self.__contextComponents):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, SwComponentPrototype) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of SwComponentPrototype or its sub-classes'.format(value))
            self.__contextComponents.add(value)
            contextComponents_values = AutosarNode._add_or_get_xml_node(self._node, 'CONTEXT-COMPONENT-REFS')

            contextComponents_value = AutosarNode._add_or_get_xml_node(contextComponents_values, 'CONTEXT-COMPONENT-REF', value, forceCreate = True)
            contextComponents_value.text = value.path
            value.referenced_by.add(self)

    def set_contextComponents(self, values):
        """
        Adds a list of ref value to the contextComponents
        """
        for value in values:
            self.add_contextComponent(value)

    def remove_contextComponent(self, value):
        """
        Removes a single value from contextComponents
        """
        if value is not None:
            self.__contextComponents.remove(value)
            contextComponents_values = AutosarNode._add_or_get_xml_node(self._node, 'CONTEXT-COMPONENT-REFS', createNode = False)
            for contextComponents_value in self._node.findall('{*}CONTEXT-COMPONENT-REFS/*'):
                if contextComponents_value.text == value.path:
                    contextComponents_value.text = ''
                    contextComponents_values.remove(contextComponents_value)
                    value.referenced_by.remove(self)
                    break

    def remove_contextComponents(self, values):
        """
        Removes a list of value from contextComponents
        """
        for value in values:
            self.remove_contextComponent(value)

    def get_contextPort(self):
        return self.__contextPort

    def set_contextPort(self, value):
        """
        Adds a single value to the contextPort
        """
