class NmInstantiation(NonOsModuleInstantiation):
    """
    This meta-class defines the attributes for the Nm configuration on a specific machine.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'NM-INSTANTIATION'
        self.__networkHandles = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        networkHandles_nodes = self._node.findall('{*}NETWORK-HANDLES/*')
        for networkHandles_node in networkHandles_nodes:
            self.__networkHandles.add(NmNetworkHandle()._build(self, networkHandles_node))

        return self

    def get_networkHandles(self):
        return self.__networkHandles

    def add_networkHandle(self, value):
        """
        Adds a single value to the networkHandles
        """
        if value is not None:
            if any(v.name == value.name for v in self.__networkHandles):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, NmNetworkHandle) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of NmNetworkHandle or its sub-classes'.format(value))
            self.__networkHandles.add(value)
            networkHandles_values = AutosarNode._add_or_get_xml_node(self._node, 'NETWORK-HANDLES')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            networkHandles_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_networkHandles(self, values):
        """
        Adds a list of ref value to the networkHandles
        """
        for value in values:
            self.add_networkHandle(value)

    def remove_networkHandle(self, value):
        """
        Removes a single value from networkHandles
        """
        if value is not None:
            self.__networkHandles.remove(value)
            networkHandles_values = AutosarNode._add_or_get_xml_node(self._node, 'NETWORK-HANDLES', createNode = False)
            networkHandles_values.remove(value._node)
            value._parent = None #No parent
            value._update_path() #resets the path

    def remove_networkHandles(self, values):
        """
        Removes a list of value from networkHandles
        """
        for value in values:
            self.remove_networkHandle(value)

    def new_NetworkHandle(self, name=None):
        """
        Creates a new NmNetworkHandle under the NmInstantiation.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        NmNetworkHandle_obj = NmNetworkHandle()
        if isinstance(NmNetworkHandle_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('NM-NETWORK-HANDLE')
        NmNetworkHandle_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        NmNetworkHandle_obj.name = name
        NmNetworkHandle_obj._node = xmlNode
        self.add_networkHandle(NmNetworkHandle_obj)
        return NmNetworkHandle_obj

    def get_children(self):
        children = super().get_children()
        children.extend(self.__networkHandles)
        return children

    def _update_path(self):
        """
        Updates the path of the NmInstantiation and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

