class HwPinGroupConnector(Describable):
    """
    This meta-class represents the ability to connect two pin groups.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'HW-PIN-GROUP-CONNECTOR'
        self.__hwPinConnections = set()
        self.__hwPinGroups = set()
        self.__variationPoint = None

    def _build(self, parent, node):
        super()._build(parent, node)
        hwPinConnections_nodes = self._node.findall('{*}HW-PIN-CONNECTIONS/*')
        for hwPinConnections_node in hwPinConnections_nodes:
            self.__hwPinConnections.add(HwPinConnector()._build(self, hwPinConnections_node))

        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            self.__variationPoint = VariationPoint()._build(self, variationPoint_node)

        return self

    def _resolve_references(self):
        hwPinGroups_nodes = self._node.findall('{*}HW-PIN-GROUP-REFS/*')
        for node in hwPinGroups_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__hwPinGroups.add(ref_value)

    def get_hwPinConnections(self):
        return self.__hwPinConnections

    def add_hwPinConnection(self, value):
        """
        Adds a single value to the hwPinConnections
        """
        if value is not None:
            if any(v.name == value.name for v in self.__hwPinConnections):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, HwPinConnector) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of HwPinConnector or its sub-classes'.format(value))
            self.__hwPinConnections.add(value)
            hwPinConnections_values = AutosarNode._add_or_get_xml_node(self._node, 'HW-PIN-CONNECTIONS')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            hwPinConnections_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_hwPinConnections(self, values):
        """
        Adds a list of ref value to the hwPinConnections
        """
        for value in values:
            self.add_hwPinConnection(value)

    def remove_hwPinConnection(self, value):
        """
        Removes a single value from hwPinConnections
        """
        if value is not None:
            self.__hwPinConnections.remove(value)
            hwPinConnections_values = AutosarNode._add_or_get_xml_node(self._node, 'HW-PIN-CONNECTIONS', createNode = False)
            hwPinConnections_values.remove(value._node)
            value._parent = None #No parent
            value._update_path() #resets the path

    def remove_hwPinConnections(self, values):
        """
        Removes a list of value from hwPinConnections
        """
        for value in values:
            self.remove_hwPinConnection(value)

    def get_hwPinGroups(self):
        return self.__hwPinGroups

    def add_hwPinGroup(self, value):
        """
        Adds a single value to the hwPinGroups
        """
        if value is not None:
            if any(v.name == value.name for v in self.__hwPinGroups):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, HwPinGroup) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of HwPinGroup or its sub-classes'.format(value))
            self.__hwPinGroups.add(value)
            hwPinGroups_values = AutosarNode._add_or_get_xml_node(self._node, 'HW-PIN-GROUP-REFS')

            hwPinGroups_value = AutosarNode._add_or_get_xml_node(hwPinGroups_values, 'HW-PIN-GROUP-REF', value, forceCreate = True)
            hwPinGroups_value.text = value.path
            value.referenced_by.add(self)

    def set_hwPinGroups(self, values):
        """
        Adds a list of ref value to the hwPinGroups
        """
        for value in values:
            self.add_hwPinGroup(value)

    def remove_hwPinGroup(self, value):
        """
        Removes a single value from hwPinGroups
        """
        if value is not None:
            self.__hwPinGroups.remove(value)
            hwPinGroups_values = AutosarNode._add_or_get_xml_node(self._node, 'HW-PIN-GROUP-REFS', createNode = False)
            for hwPinGroups_value in self._node.findall('{*}HW-PIN-GROUP-REFS/*'):
                if hwPinGroups_value.text == value.path:
                    hwPinGroups_value.text = ''
                    hwPinGroups_values.remove(hwPinGroups_value)
                    value.referenced_by.remove(self)
                    break

    def remove_hwPinGroups(self, values):
        """
        Removes a list of value from hwPinGroups
        """
        for value in values:
            self.remove_hwPinGroup(value)

    def get_variationPoint(self):
        return self.__variationPoint

    def set_variationPoint(self, value):
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))
            if self.__variationPoint is not None:
                self._node.remove(self.__variationPoint._node)
            # if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            self._node.append(value._node)
            self.__variationPoint = value
            value._parent = self #set parent
            value._update_path() #updates the path
        elif self.__variationPoint is not None:
            self._node.remove(self.__variationPoint._node)
            self.__variationPoint = None
            self.__variationPoint._parent = None #No parent
            self.__variationPoint._update_path() #updates the path

    def new_HwPinConnection(self, name=None):
        """
        Creates a new HwPinConnector under the HwPinGroupConnector.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        HwPinConnector_obj = HwPinConnector()
        if isinstance(HwPinConnector_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('HW-PIN-CONNECTOR')
        HwPinConnector_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        HwPinConnector_obj.name = name
        HwPinConnector_obj._node = xmlNode
        self.add_hwPinConnection(HwPinConnector_obj)
        return HwPinConnector_obj

    def new_VariationPoint(self, name=None):
        """
        Creates a new VariationPoint under the HwPinGroupConnector.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        VariationPoint_obj = VariationPoint()
        if isinstance(VariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('VARIATION-POINT')
        VariationPoint_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        VariationPoint_obj.name = name
        VariationPoint_obj._node = xmlNode
        self.set_variationPoint(VariationPoint_obj)
        return VariationPoint_obj

    def get_children(self):
        children = super().get_children()
        children.extend(self.__hwPinConnections)
        if self.__variationPoint is not None:
            children.append(self.__variationPoint)
        return children

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['HwPinGroups'] = self.__hwPinGroups
        return property_values

    def _update_path(self):
        """
        Updates the path of the HwPinGroupConnector and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

