class DltLogChannelDesign(ARElement):
    """
    This meta-class has the ability to stand in for a DltLogChannel at the time when the DltLogChannel does not yet exist. But its future existence already needs to be considered during design phase and for that a dedicated model element is required.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'DLT-LOG-CHANNEL-DESIGN'
        self.__dltMessages = set()
        self.__endpointConfiguration = None


    def _resolve_references(self):
        dltMessages_nodes = self._node.findall('{*}DLT-MESSAGE-REFS/*')
        for node in dltMessages_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__dltMessages.add(ref_value)
        endpointConfiguration_node = self._node.find('{*}ENDPOINT-CONFIGURATION-REF')
        if endpointConfiguration_node is not None and endpointConfiguration_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[endpointConfiguration_node.text]
            ref_value.referenced_by.add(self)
            self.__endpointConfiguration = ref_value

    def get_dltMessages(self):
        return self.__dltMessages

    def add_dltMessage(self, value):
        """
        Adds a single value to the dltMessages
        """
        if value is not None:
            if any(v.name == value.name for v in self.__dltMessages):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, DltMessage) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of DltMessage or its sub-classes'.format(value))
