class PersistencyFileStorageInterface(PersistencyInterface):
    """
    This meta-class provides the ability to implement a PortInterface for supporting persistency use cases for files.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'PERSISTENCY-FILE-STORAGE-INTERFACE'
        self.__maxNumberOfFiles = None
        self.__fileElements = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        maxNumberOfFiles_value = AutosarNode._get_node_text(node,'MAX-NUMBER-OF-FILES')
        if maxNumberOfFiles_value is not None:
            self.__maxNumberOfFiles = datatype_utils.get_int_value(maxNumberOfFiles_value)

        fileElements_nodes = self._node.findall('{*}FILE-ELEMENTS/*')
        for fileElements_node in fileElements_nodes:
            self.__fileElements.add(PersistencyFileElement()._build(self, fileElements_node))

        return self

    def get_maxNumberOfFiles(self):
        return self.__maxNumberOfFiles

    def set_maxNumberOfFiles(self, value):
        self.__maxNumberOfFiles = value
        maxNumberOfFiles_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'MAX-NUMBER-OF-FILES')
        maxNumberOfFiles_xml_node.text = str(value) if value is not None else ''

    def get_fileElements(self):
        return self.__fileElements

    def add_fileElement(self, value):
        """
        Adds a single value to the fileElements
        """
        if value is not None:
            if any(v.name == value.name for v in self.__fileElements):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, PersistencyFileElement) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of PersistencyFileElement or its sub-classes'.format(value))
            self.__fileElements.add(value)
            fileElements_values = AutosarNode._add_or_get_xml_node(self._node, 'FILE-ELEMENTS')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            fileElements_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_fileElements(self, values):
        """
        Adds a list of ref value to the fileElements
        """
        for value in values:
            self.add_fileElement(value)

    def remove_fileElement(self, value):
        """
        Removes a single value from fileElements
        """
        if value is not None:
            self.__fileElements.remove(value)
            fileElements_values = AutosarNode._add_or_get_xml_node(self._node, 'FILE-ELEMENTS', createNode = False)
            fileElements_values.remove(value._node)
            value._parent = None #No parent
            value._update_path() #resets the path

    def remove_fileElements(self, values):
        """
        Removes a list of value from fileElements
        """
        for value in values:
            self.remove_fileElement(value)

    def new_FileElement(self, name=None):
        """
        Creates a new PersistencyFileElement under the PersistencyFileStorageInterface.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        PersistencyFileElement_obj = PersistencyFileElement()
        if isinstance(PersistencyFileElement_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('PERSISTENCY-FILE-ELEMENT')
        PersistencyFileElement_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        PersistencyFileElement_obj.name = name
        PersistencyFileElement_obj._node = xmlNode
        self.add_fileElement(PersistencyFileElement_obj)
        return PersistencyFileElement_obj

