class ModeSwitchInterface(PortInterface):
    """
    A mode switch interface declares a ModeDeclarationGroupPrototype to be sent and received.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'MODE-SWITCH-INTERFACE'
        self.__modeGroup = None

    def _build(self, parent, node):
        super()._build(parent, node)
        modeGroup_node = self._node.find('{*}MODE-GROUP')
        if modeGroup_node is not None:
            self.__modeGroup = ModeDeclarationGroupPrototype()._build(self, modeGroup_node)

        return self

    def get_modeGroup(self):
        return self.__modeGroup

    def set_modeGroup(self, value):
        """
        Adds a single value to the modeGroup
        """
        if value is not None:
            if isinstance(value, ModeDeclarationGroupPrototype) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ModeDeclarationGroupPrototype or its sub-classes'.format(value))
            if self.__modeGroup is not None:
                self._node.remove(self.__modeGroup._node)
            # if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            self._node.append(value._node)
            self.__modeGroup = value
            value._parent = self #set parent
            value._update_path() #updates the path
        elif self.__modeGroup is not None:
            self._node.remove(self.__modeGroup._node)
            self.__modeGroup = None
            self.__modeGroup._parent = None #No parent
            self.__modeGroup._update_path() #updates the path

    def new_ModeGroup(self, name=None):
        """
        Creates a new ModeDeclarationGroupPrototype under the ModeSwitchInterface.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        ModeDeclarationGroupPrototype_obj = ModeDeclarationGroupPrototype()
        if isinstance(ModeDeclarationGroupPrototype_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('MODE-GROUP')
        ModeDeclarationGroupPrototype_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        ModeDeclarationGroupPrototype_obj.name = name
        ModeDeclarationGroupPrototype_obj._node = xmlNode
        self.set_modeGroup(ModeDeclarationGroupPrototype_obj)
        return ModeDeclarationGroupPrototype_obj

    def get_children(self):
        children = super().get_children()
        if self.__modeGroup is not None:
            children.append(self.__modeGroup)
        return children

    def _update_path(self):
        """
        Updates the path of the ModeSwitchInterface and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

class GenericModelReference(ARObject):
    """
    This meta-class represents the ability to express a late binding reference to a model element. The model element can be from every model. Even if it is modeled according to the association representation, it is not limited to refer to AUTOSAR model elements.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'GENERIC-MODEL-REFERENCE'
        self.__base = None
        self.__dest = None
        self.__ref = None

    def _build(self, parent, node):
        super()._build(parent, node)
        base_value = AutosarNode._get_node_text(node,'BASE')
        if base_value is not None:
            self.__base = datatype_utils.get_string_value(base_value)

        dest_value = AutosarNode._get_node_text(node,'DEST')
        if dest_value is not None:
            self.__dest = datatype_utils.get_string_value(dest_value)

        ref_value = AutosarNode._get_node_text(node,'REF')
        if ref_value is not None:
            self.__ref = datatype_utils.get_string_value(ref_value)

        return self

    def get_base(self):
        return self.__base

