class HwPinConnector(Describable):
    """
    This meta-class represents the ability to connect two pins.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'HW-PIN-CONNECTOR'
        self.__hwPins = set()
        self.__variationPoint = None

    def _build(self, parent, node):
        super()._build(parent, node)
        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            self.__variationPoint = VariationPoint()._build(self, variationPoint_node)

        return self

    def _resolve_references(self):
        hwPins_nodes = self._node.findall('{*}HW-PIN-REFS/*')
        for node in hwPins_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__hwPins.add(ref_value)

    def get_hwPins(self):
        return self.__hwPins

    def add_hwPin(self, value):
        """
        Adds a single value to the hwPins
        """
        if value is not None:
            if any(v.name == value.name for v in self.__hwPins):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, HwPin) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of HwPin or its sub-classes'.format(value))
            self.__hwPins.add(value)
            hwPins_values = AutosarNode._add_or_get_xml_node(self._node, 'HW-PIN-REFS')

            hwPins_value = AutosarNode._add_or_get_xml_node(hwPins_values, 'HW-PIN-REF', value, forceCreate = True)
            hwPins_value.text = value.path
            value.referenced_by.add(self)

    def set_hwPins(self, values):
        """
        Adds a list of ref value to the hwPins
        """
        for value in values:
            self.add_hwPin(value)

    def remove_hwPin(self, value):
        """
        Removes a single value from hwPins
        """
        if value is not None:
            self.__hwPins.remove(value)
            hwPins_values = AutosarNode._add_or_get_xml_node(self._node, 'HW-PIN-REFS', createNode = False)
            for hwPins_value in self._node.findall('{*}HW-PIN-REFS/*'):
                if hwPins_value.text == value.path:
                    hwPins_value.text = ''
                    hwPins_values.remove(hwPins_value)
                    value.referenced_by.remove(self)
                    break

    def remove_hwPins(self, values):
        """
        Removes a list of value from hwPins
        """
        for value in values:
            self.remove_hwPin(value)

    def get_variationPoint(self):
        return self.__variationPoint

    def set_variationPoint(self, value):
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))
            if self.__variationPoint is not None:
                self._node.remove(self.__variationPoint._node)
            # if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            self._node.append(value._node)
            self.__variationPoint = value
            value._parent = self #set parent
            value._update_path() #updates the path
        elif self.__variationPoint is not None:
            self._node.remove(self.__variationPoint._node)
            self.__variationPoint = None
            self.__variationPoint._parent = None #No parent
            self.__variationPoint._update_path() #updates the path

    def new_VariationPoint(self, name=None):
        """
        Creates a new VariationPoint under the HwPinConnector.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        VariationPoint_obj = VariationPoint()
        if isinstance(VariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('VARIATION-POINT')
