            self.__replicaPdus.remove(value)
            replicaPdus_values = AutosarNode._add_or_get_xml_node(self._node, 'REPLICA-PDUS-REFS', createNode = False)
            for replicaPdus_value in self._node.findall('{*}REPLICA-PDUS-REFS/*'):
                if replicaPdus_value.text == value.path:
                    replicaPdus_value.text = ''
                    replicaPdus_values.remove(replicaPdus_value)
                    value.referenced_by.remove(self)
