class EngineeringObject(ARObject):
    """
    This class specifies an engineering object. Usually such an object is represented by a file artifact. The properties of engineering object are such that the artifact can be found  by querying an ASAM catalog file., , The engineering object is uniquely identified by domain+category+shortLabel+revisionLabel.
    """
    def __init__(self):
        super().__init__()
        self.__shortLabel = None
        self.__category = None
        self.__revisionLabels = None
        self.__domain = None

    def _build(self, parent, node):
        super()._build(parent, node)
        shortLabel_value = AutosarNode._get_node_text(node,'SHORT-LABEL')
        if shortLabel_value is not None:
            self.__shortLabel = datatype_utils.get_string_value(shortLabel_value)

        category_value = AutosarNode._get_node_text(node,'CATEGORY')
        if category_value is not None:
            self.__category = datatype_utils.get_string_value(category_value)

        revisionLabels_value = AutosarNode._get_node_text(node,'REVISION-LABEL')
        if revisionLabels_value is not None:
            self.__revisionLabels = datatype_utils.get_string_value(revisionLabels_value)

        domain_value = AutosarNode._get_node_text(node,'DOMAIN')
        if domain_value is not None:
            self.__domain = datatype_utils.get_string_value(domain_value)

        return self

    def get_shortLabel(self):
        return self.__shortLabel

    def set_shortLabel(self, value):
        self.__shortLabel = value
        shortLabel_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'SHORT-LABEL')
        shortLabel_xml_node.text = str(value) if value is not None else ''

    def get_category(self):
        return self.__category

    def set_category(self, value):
        self.__category = value
        category_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'CATEGORY')
        category_xml_node.text = str(value) if value is not None else ''

    def get_revisionLabels(self):
        return self.__revisionLabels

    def set_revisionLabels(self, value):
        self.__revisionLabels = value
        revisionLabels_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'REVISION-LABEL')
        revisionLabels_xml_node.text = str(value) if value is not None else ''

    def get_domain(self):
        return self.__domain

    def set_domain(self, value):
        self.__domain = value
        domain_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'DOMAIN')
        domain_xml_node.text = str(value) if value is not None else ''

    def _add_mandatory_attr(self, node, name = None):
        super()._add_mandatory_attr(node, name)
        shortLabel_node = etree.SubElement(node, 'SHORT-LABEL')
        self.__shortLabel = None
        shortLabel_node.text = ''
        category_node = etree.SubElement(node, 'CATEGORY')
        self.__category = None
        category_node.text = ''

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['ShortLabel'] = self.__shortLabel
        property_values['Category'] = self.__category
        property_values['RevisionLabels'] = self.__revisionLabels
        property_values['Domain'] = self.__domain
        return property_values

    def _update_path(self):
        """
        Updates the path of the EngineeringObject and its children.
        """
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

