class AgeConstraint(TimingConstraint):
    """
    The AgeConstraint is used to impose a constraint on an Timing Description Event referenced by the scope., , A minimum and a maximum age can be specified.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'AGE-CONSTRAINT'
        self.__maximum = None
        self.__minimum = None
        self.__scope = None

    def _build(self, parent, node):
        super()._build(parent, node)
        maximum_node = self._node.find('{*}MAXIMUM')
        if maximum_node is not None:
            self.__maximum = MultidimensionalTime()._build(self, maximum_node)

        minimum_node = self._node.find('{*}MINIMUM')
        if minimum_node is not None:
            self.__minimum = MultidimensionalTime()._build(self, minimum_node)

        return self

    def _resolve_references(self):
        scope_node = self._node.find('{*}SCOPE-REF')
        if scope_node is not None and scope_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[scope_node.text]
            ref_value.referenced_by.add(self)
            self.__scope = ref_value

    def get_maximum(self):
        return self.__maximum

    def set_maximum(self, value):
        """
        Adds a single value to the maximum
        """
        if value is not None:
            if isinstance(value, MultidimensionalTime) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of MultidimensionalTime or its sub-classes'.format(value))
            if self.__maximum is not None:
                self._node.remove(self.__maximum._node)
            # if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            self._node.append(value._node)
            self.__maximum = value
            value._parent = self #set parent
            value._update_path() #updates the path
        elif self.__maximum is not None:
            self._node.remove(self.__maximum._node)
            self.__maximum = None
            self.__maximum._parent = None #No parent
            self.__maximum._update_path() #updates the path

    def get_minimum(self):
        return self.__minimum

    def set_minimum(self, value):
        """
        Adds a single value to the minimum
        """
        if value is not None:
            if isinstance(value, MultidimensionalTime) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of MultidimensionalTime or its sub-classes'.format(value))
            if self.__minimum is not None:
                self._node.remove(self.__minimum._node)
