class CompuMethod(ARElement,AtpBlueprint,AtpBlueprintable):
    """
    This meta-class represents the ability to express the relationship between a physical value and the mathematical representation. , , Note that this is still independent of the technical implementation in data types. It only specifies the formula how the internal value corresponds to its physical pendant.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'COMPU-METHOD'
        self.__displayFormat = None
        self.__unit = None
        self.__compuInternalToPhys = None
        self.__compuPhysToInternal = None

    def _build(self, parent, node):
        super()._build(parent, node)
        displayFormat_value = AutosarNode._get_node_text(node,'DISPLAY-FORMAT')
