class ProvidedServiceInstance(AbstractServiceInstance):
    """
    Service instances that are provided by the ECU that is connected via the ApplicationEndpoint to a CommunicationConnector.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'PROVIDED-SERVICE-INSTANCE'
        self.__autoAvailable = None
        self.__instanceIdentifier = None
        self.__loadBalancingPriority = None
        self.__loadBalancingWeight = None
        self.__minorVersion = None
        self.__priority = None
        self.__serviceIdentifier = None
        self.__eventHandlers = set()
        self.__localUnicastAddress = set()
        self.__remoteUnicastAddress = set()
        self.__sdServerConfig = None
        self.__sdServerTimerConfigs = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        autoAvailable_value = AutosarNode._get_node_text(node,'AUTO-AVAILABLE')
        if autoAvailable_value is not None:
            self.__autoAvailable = datatype_utils.get_bool_value(autoAvailable_value)

        instanceIdentifier_value = AutosarNode._get_node_text(node,'INSTANCE-IDENTIFIER')
        if instanceIdentifier_value is not None:
            self.__instanceIdentifier = datatype_utils.get_int_value(instanceIdentifier_value)

        loadBalancingPriority_value = AutosarNode._get_node_text(node,'LOAD-BALANCING-PRIORITY')
        if loadBalancingPriority_value is not None:
            self.__loadBalancingPriority = datatype_utils.get_int_value(loadBalancingPriority_value)

        loadBalancingWeight_value = AutosarNode._get_node_text(node,'LOAD-BALANCING-WEIGHT')
        if loadBalancingWeight_value is not None:
            self.__loadBalancingWeight = datatype_utils.get_int_value(loadBalancingWeight_value)

        minorVersion_value = AutosarNode._get_node_text(node,'MINOR-VERSION')
        if minorVersion_value is not None:
            self.__minorVersion = datatype_utils.get_int_value(minorVersion_value)

        priority_value = AutosarNode._get_node_text(node,'PRIORITY')
        if priority_value is not None:
            self.__priority = datatype_utils.get_int_value(priority_value)

        serviceIdentifier_value = AutosarNode._get_node_text(node,'SERVICE-IDENTIFIER')
        if serviceIdentifier_value is not None:
            self.__serviceIdentifier = datatype_utils.get_int_value(serviceIdentifier_value)

        eventHandlers_nodes = self._node.findall('{*}EVENT-HANDLERS/*')
        for eventHandlers_node in eventHandlers_nodes:
            self.__eventHandlers.add(EventHandler()._build(self, eventHandlers_node))

        localUnicastAddress_nodes = self._node.findall('{*}LOCAL-UNICAST-ADDRESSS/*')
        for localUnicastAddress_node in localUnicastAddress_nodes:
            self.__localUnicastAddress.add(ApplicationEndpointRefConditional()._build(self, localUnicastAddress_node))

        remoteUnicastAddress_nodes = self._node.findall('{*}REMOTE-UNICAST-ADDRESSS/*')
        for remoteUnicastAddress_node in remoteUnicastAddress_nodes:
            self.__remoteUnicastAddress.add(ApplicationEndpointRefConditional()._build(self, remoteUnicastAddress_node))

        sdServerConfig_node = self._node.find('{*}SD-SERVER-CONFIG')
        if sdServerConfig_node is not None:
            self.__sdServerConfig = SdServerConfig()._build(self, sdServerConfig_node)

        sdServerTimerConfigs_nodes = self._node.findall('{*}SD-SERVER-TIMER-CONFIGS/*')
        for sdServerTimerConfigs_node in sdServerTimerConfigs_nodes:
            self.__sdServerTimerConfigs.add(SomeipSdServerServiceInstanceConfigRefConditional()._build(self, sdServerTimerConfigs_node))

        return self

    def get_autoAvailable(self):
        return self.__autoAvailable

    def set_autoAvailable(self, value):
        self.__autoAvailable = value
        autoAvailable_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'AUTO-AVAILABLE')
        autoAvailable_xml_node.text = 'true' if value is True else 'false'

    def get_instanceIdentifier(self):
        return self.__instanceIdentifier

    def set_instanceIdentifier(self, value):
        self.__instanceIdentifier = value
        instanceIdentifier_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'INSTANCE-IDENTIFIER')
        instanceIdentifier_xml_node.text = str(value) if value is not None else ''

    def get_loadBalancingPriority(self):
        return self.__loadBalancingPriority

    def set_loadBalancingPriority(self, value):
        self.__loadBalancingPriority = value
        loadBalancingPriority_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'LOAD-BALANCING-PRIORITY')
        loadBalancingPriority_xml_node.text = str(value) if value is not None else ''

    def get_loadBalancingWeight(self):
        return self.__loadBalancingWeight

    def set_loadBalancingWeight(self, value):
        self.__loadBalancingWeight = value
        loadBalancingWeight_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'LOAD-BALANCING-WEIGHT')
        loadBalancingWeight_xml_node.text = str(value) if value is not None else ''

    def get_minorVersion(self):
        return self.__minorVersion

    def set_minorVersion(self, value):
        self.__minorVersion = value
        minorVersion_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'MINOR-VERSION')
        minorVersion_xml_node.text = str(value) if value is not None else ''

    def get_priority(self):
        return self.__priority

    def set_priority(self, value):
        self.__priority = value
        priority_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'PRIORITY')
        priority_xml_node.text = str(value) if value is not None else ''

    def get_serviceIdentifier(self):
        return self.__serviceIdentifier

    def set_serviceIdentifier(self, value):
        self.__serviceIdentifier = value
        serviceIdentifier_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'SERVICE-IDENTIFIER')
        serviceIdentifier_xml_node.text = str(value) if value is not None else ''

    def get_eventHandlers(self):
        return self.__eventHandlers

    def add_eventHandler(self, value):
        """
        Adds a single value to the eventHandlers
        """
        if value is not None:
            if any(v.name == value.name for v in self.__eventHandlers):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, EventHandler) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of EventHandler or its sub-classes'.format(value))
            self.__eventHandlers.add(value)
            eventHandlers_values = AutosarNode._add_or_get_xml_node(self._node, 'EVENT-HANDLERS')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            eventHandlers_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_eventHandlers(self, values):
        """
        Adds a list of ref value to the eventHandlers
        """
        for value in values:
            self.add_eventHandler(value)

    def remove_eventHandler(self, value):
        """
        Removes a single value from eventHandlers
        """
        if value is not None:
            self.__eventHandlers.remove(value)
