class AnyInstanceRef(AtpInstanceRef):
    """
    Describes a reference to any instance in an AUTOSAR model. This is the most generic form of an instance ref. Refer to the superclass notes for more details.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'ANY-INSTANCE-REF-IREF'
        self.__contextElements = set()
        self.__target = None
        self.__variationPoint = None

    def _build(self, parent, node):
        super()._build(parent, node)
        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            self.__variationPoint = VariationPoint()._build(self, variationPoint_node)

        return self

    def _resolve_references(self):
        contextElements_nodes = self._node.findall('{*}CONTEXT-ELEMENT-REFS/*')
        for node in contextElements_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__contextElements.add(ref_value)
        target_node = self._node.find('{*}TARGET-REF')
        if target_node is not None and target_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[target_node.text]
            ref_value.referenced_by.add(self)
            self.__target = ref_value

    def get_contextElements(self):
        return self.__contextElements

    def add_contextElement(self, value):
        """
        Adds a single value to the contextElements
        """
        if value is not None:
            if any(v.name == value.name for v in self.__contextElements):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, AtpFeature) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of AtpFeature or its sub-classes'.format(value))
            self.__contextElements.add(value)
            contextElements_values = AutosarNode._add_or_get_xml_node(self._node, 'CONTEXT-ELEMENT-REFS')

            contextElements_value = AutosarNode._add_or_get_xml_node(contextElements_values, 'CONTEXT-ELEMENT-REF', value, forceCreate = True)
            contextElements_value.text = value.path
            value.referenced_by.add(self)

    def set_contextElements(self, values):
        """
        Adds a list of ref value to the contextElements
        """
        for value in values:
            self.add_contextElement(value)

    def remove_contextElement(self, value):
        """
        Removes a single value from contextElements
        """
        if value is not None:
            self.__contextElements.remove(value)
            contextElements_values = AutosarNode._add_or_get_xml_node(self._node, 'CONTEXT-ELEMENT-REFS', createNode = False)
            for contextElements_value in self._node.findall('{*}CONTEXT-ELEMENT-REFS/*'):
                if contextElements_value.text == value.path:
                    contextElements_value.text = ''
                    contextElements_values.remove(contextElements_value)
                    value.referenced_by.remove(self)
                    break

    def remove_contextElements(self, values):
        """
        Removes a list of value from contextElements
        """
        for value in values:
            self.remove_contextElement(value)

    def get_target(self):
        return self.__target

    def set_target(self, value):
        """
        Adds a single value to the target
        """
        if value is not None:
            if isinstance(value, AtpFeature) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of AtpFeature or its sub-classes'.format(value))
            if self.__target is not None:
                self.__target.referenced_by.remove(self)
            target_value = AutosarNode._add_or_get_xml_node(self._node, 'TARGET-REF', value)
            target_value.text = value.path
            target_value.attrib['DEST'] = value.tag
            self.__target = value
            value.referenced_by.add(self)
        elif self.__target is not None:
            self.__target.referenced_by.remove(self)
            self.__target = None
            target_value = AutosarNode._add_or_get_xml_node(self._node, 'TARGET-REF', createNode = False)
            if target_value is not None:
                target_value.referenced_by.remove(self)
                target_value.text = ''

