class NvDataInterface(DataInterface):
    """
    A non volatile data interface declares a number of VariableDataPrototypes to be exchanged between non volatile block components and atomic software components.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'NV-DATA-INTERFACE'
        self.__nvDatas = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        nvDatas_nodes = self._node.findall('{*}NV-DATAS/*')
        for nvDatas_node in nvDatas_nodes:
            self.__nvDatas.add(VariableDataPrototype()._build(self, nvDatas_node))

        return self

    def get_nvDatas(self):
        return self.__nvDatas

    def add_nvData(self, value):
        """
        Adds a single value to the nvDatas
        """
        if value is not None:
            if any(v.name == value.name for v in self.__nvDatas):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, VariableDataPrototype) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariableDataPrototype or its sub-classes'.format(value))
            self.__nvDatas.add(value)
            nvDatas_values = AutosarNode._add_or_get_xml_node(self._node, 'NV-DATAS')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            nvDatas_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_nvDatas(self, values):
        """
        Adds a list of ref value to the nvDatas
        """
        for value in values:
            self.add_nvData(value)

    def remove_nvData(self, value):
        """
        Removes a single value from nvDatas
        """
        if value is not None:
            self.__nvDatas.remove(value)
            nvDatas_values = AutosarNode._add_or_get_xml_node(self._node, 'NV-DATAS', createNode = False)
            nvDatas_values.remove(value._node)
            value._parent = None #No parent
            value._update_path() #resets the path

    def remove_nvDatas(self, values):
        """
        Removes a list of value from nvDatas
        """
        for value in values:
            self.remove_nvData(value)

    def new_NvData(self, name=None):
        """
        Creates a new VariableDataPrototype under the NvDataInterface.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        VariableDataPrototype_obj = VariableDataPrototype()
        if isinstance(VariableDataPrototype_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('VARIABLE-DATA-PROTOTYPE')
        VariableDataPrototype_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        VariableDataPrototype_obj.name = name
        VariableDataPrototype_obj._node = xmlNode
        self.add_nvData(VariableDataPrototype_obj)
        return VariableDataPrototype_obj

    def get_children(self):
        children = super().get_children()
        children.extend(self.__nvDatas)
        return children

    def _update_path(self):
        """
        Updates the path of the NvDataInterface and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

