class ServiceInterface(PortInterface):
    """
    This represents the ability to define a PortInterface that consists of a heterogeneous collection of methods, events and fields.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'SERVICE-INTERFACE'
        self.__majorVersion = None
        self.__minorVersion = None
        self.__events = set()
        self.__fields = set()
        self.__methods = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        majorVersion_value = AutosarNode._get_node_text(node,'MAJOR-VERSION')
        if majorVersion_value is not None:
            self.__majorVersion = datatype_utils.get_int_value(majorVersion_value)

        minorVersion_value = AutosarNode._get_node_text(node,'MINOR-VERSION')
        if minorVersion_value is not None:
            self.__minorVersion = datatype_utils.get_int_value(minorVersion_value)

        events_nodes = self._node.findall('{*}EVENTS/*')
        for events_node in events_nodes:
            self.__events.add(VariableDataPrototype()._build(self, events_node))

        fields_nodes = self._node.findall('{*}FIELDS/*')
        for fields_node in fields_nodes:
            self.__fields.add(Field()._build(self, fields_node))

        methods_nodes = self._node.findall('{*}METHODS/*')
        for methods_node in methods_nodes:
            self.__methods.add(ClientServerOperation()._build(self, methods_node))

        return self

    def get_majorVersion(self):
        return self.__majorVersion

