class J1939Cluster(AbstractCanCluster):
    """
    J1939 specific cluster attributes.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'J-1939-CLUSTER'
        self.__j1939ClusterVariants = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        j1939ClusterVariants_nodes = self._node.findall('{*}J-1939-CLUSTER-VARIANTS/*')
        for j1939ClusterVariants_node in j1939ClusterVariants_nodes:
            self.__j1939ClusterVariants.add(J1939ClusterConditional()._build(self, j1939ClusterVariants_node))

        return self

    def get_j1939ClusterVariants(self):
        return self.__j1939ClusterVariants

    def add_j1939ClusterVariant(self, value):
        """
        Adds a single value to the j1939ClusterVariants
        """
        if value is not None:
            if any(v.name == value.name for v in self.__j1939ClusterVariants):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, J1939ClusterConditional) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of J1939ClusterConditional or its sub-classes'.format(value))
            self.__j1939ClusterVariants.add(value)
            j1939ClusterVariants_values = AutosarNode._add_or_get_xml_node(self._node, 'J-1939-CLUSTER-VARIANTS')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            j1939ClusterVariants_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_j1939ClusterVariants(self, values):
        """
        Adds a list of ref value to the j1939ClusterVariants
        """
        for value in values:
            self.add_j1939ClusterVariant(value)

    def remove_j1939ClusterVariant(self, value):
        """
        Removes a single value from j1939ClusterVariants
        """
        if value is not None:
            self.__j1939ClusterVariants.remove(value)
            j1939ClusterVariants_values = AutosarNode._add_or_get_xml_node(self._node, 'J-1939-CLUSTER-VARIANTS', createNode = False)
            j1939ClusterVariants_values.remove(value._node)
            value._parent = None #No parent
            value._update_path() #resets the path

    def remove_j1939ClusterVariants(self, values):
        """
        Removes a list of value from j1939ClusterVariants
        """
        for value in values:
            self.remove_j1939ClusterVariant(value)

    def new_J1939ClusterVariant(self, name=None):
        """
        Creates a new J1939ClusterConditional under the J1939Cluster.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        J1939ClusterConditional_obj = J1939ClusterConditional()
        if isinstance(J1939ClusterConditional_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('J-1939-CLUSTER-CONDITIONAL')
        J1939ClusterConditional_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        J1939ClusterConditional_obj.name = name
        J1939ClusterConditional_obj._node = xmlNode
        self.add_j1939ClusterVariant(J1939ClusterConditional_obj)
        return J1939ClusterConditional_obj

    def get_children(self):
        children = super().get_children()
        children.extend(self.__j1939ClusterVariants)
        return children

    def _update_path(self):
        """
        Updates the path of the J1939Cluster and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

class TimingDescriptionEventChain(TimingDescription):
    """
    An event chain describes the causal order for a set of functionally dependent timing events. Each event chain has a well defined stimulus and response, which describe its start and end point. Furthermore, it can be hierarchically decomposed into an arbitrary number of sub-chains, so called ''event chain segments''.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'TIMING-DESCRIPTION-EVENT-CHAIN'
        self.__stimulus = None
        self.__response = None
        self.__segments = set()


    def _resolve_references(self):
        stimulus_node = self._node.find('{*}STIMULUS-REF')
        if stimulus_node is not None and stimulus_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[stimulus_node.text]
            ref_value.referenced_by.add(self)
            self.__stimulus = ref_value
        response_node = self._node.find('{*}RESPONSE-REF')
        if response_node is not None and response_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[response_node.text]
            ref_value.referenced_by.add(self)
            self.__response = ref_value
        segments_nodes = self._node.findall('{*}SEGMENT-REFS/*')
        for node in segments_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__segments.add(ref_value)

    def get_stimulus(self):
        return self.__stimulus

    def set_stimulus(self, value):
        """
        Adds a single value to the stimulus
        """
        if value is not None:
            if isinstance(value, TimingDescriptionEvent) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of TimingDescriptionEvent or its sub-classes'.format(value))
            if self.__stimulus is not None:
                self.__stimulus.referenced_by.remove(self)
            stimulus_value = AutosarNode._add_or_get_xml_node(self._node, 'STIMULUS-REF', value)
            stimulus_value.text = value.path
            stimulus_value.attrib['DEST'] = value.tag
            self.__stimulus = value
            value.referenced_by.add(self)
        elif self.__stimulus is not None:
            self.__stimulus.referenced_by.remove(self)
            self.__stimulus = None
            stimulus_value = AutosarNode._add_or_get_xml_node(self._node, 'STIMULUS-REF', createNode = False)
            if stimulus_value is not None:
                stimulus_value.referenced_by.remove(self)
                stimulus_value.text = ''

    def get_response(self):
        return self.__response

    def set_response(self, value):
        """
        Adds a single value to the response
        """
        if value is not None:
            if isinstance(value, TimingDescriptionEvent) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of TimingDescriptionEvent or its sub-classes'.format(value))
            if self.__response is not None:
                self.__response.referenced_by.remove(self)
            response_value = AutosarNode._add_or_get_xml_node(self._node, 'RESPONSE-REF', value)
            response_value.text = value.path
            response_value.attrib['DEST'] = value.tag
            self.__response = value
            value.referenced_by.add(self)
        elif self.__response is not None:
            self.__response.referenced_by.remove(self)
            self.__response = None
            response_value = AutosarNode._add_or_get_xml_node(self._node, 'RESPONSE-REF', createNode = False)
            if response_value is not None:
                response_value.referenced_by.remove(self)
                response_value.text = ''

    def get_segments(self):
        return self.__segments

    def add_segment(self, value):
        """
        Adds a single value to the segments
        """
        if value is not None:
            if any(v.name == value.name for v in self.__segments):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, TimingDescriptionEventChain) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of TimingDescriptionEventChain or its sub-classes'.format(value))
            self.__segments.add(value)
            segments_values = AutosarNode._add_or_get_xml_node(self._node, 'SEGMENT-REFS')

            segments_value = AutosarNode._add_or_get_xml_node(segments_values, 'SEGMENT-REF', value, forceCreate = True)
            segments_value.text = value.path
            value.referenced_by.add(self)

    def set_segments(self, values):
        """
        Adds a list of ref value to the segments
        """
        for value in values:
            self.add_segment(value)

    def remove_segment(self, value):
        """
        Removes a single value from segments
        """
        if value is not None:
            self.__segments.remove(value)
            segments_values = AutosarNode._add_or_get_xml_node(self._node, 'SEGMENT-REFS', createNode = False)
            for segments_value in self._node.findall('{*}SEGMENT-REFS/*'):
                if segments_value.text == value.path:
                    segments_value.text = ''
                    segments_values.remove(segments_value)
                    value.referenced_by.remove(self)
                    break

    def remove_segments(self, values):
        """
        Removes a list of value from segments
        """
        for value in values:
            self.remove_segment(value)

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['Stimulus'] = self.__stimulus
        property_values['Response'] = self.__response
        property_values['Segments'] = self.__segments
        return property_values

    def _update_path(self):
        """
        Updates the path of the TimingDescriptionEventChain and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

