    def get_children(self):
        children = super().get_children()
        children.extend(self.__arTypedPerInstanceMemories)
        children.extend(self.__events)
        children.extend(self.__exclusiveAreaPolicies)
        children.extend(self.__explicitInterRunnableVariables)
        children.extend(self.__implicitInterRunnableVariables)
        children.extend(self.__includedDataTypeSets)
        children.extend(self.__includedModeDeclarationGroupSets)
        children.extend(self.__instantiationDataDefProps)
