class IPSecIamRemoteSubject(AbstractIamRemoteSubject):
    """
    This meta-class defines the proxy information about the remote node in case of IPsec.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'IP-SEC-IAM-REMOTE-SUBJECT'
        self.__localIpSecRules = set()


    def _resolve_references(self):
        localIpSecRules_nodes = self._node.findall('{*}LOCAL-IP-SEC-RULE-REFS/*')
        for node in localIpSecRules_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__localIpSecRules.add(ref_value)

    def get_localIpSecRules(self):
        return self.__localIpSecRules

    def add_localIpSecRule(self, value):
        """
        Adds a single value to the localIpSecRules
        """
        if value is not None:
            if any(v.name == value.name for v in self.__localIpSecRules):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, IPSecRule) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of IPSecRule or its sub-classes'.format(value))
            self.__localIpSecRules.add(value)
            localIpSecRules_values = AutosarNode._add_or_get_xml_node(self._node, 'LOCAL-IP-SEC-RULE-REFS')

            localIpSecRules_value = AutosarNode._add_or_get_xml_node(localIpSecRules_values, 'LOCAL-IP-SEC-RULE-REF', value, forceCreate = True)
            localIpSecRules_value.text = value.path
            value.referenced_by.add(self)

    def set_localIpSecRules(self, values):
        """
        Adds a list of ref value to the localIpSecRules
        """
        for value in values:
            self.add_localIpSecRule(value)

    def remove_localIpSecRule(self, value):
        """
        Removes a single value from localIpSecRules
        """
        if value is not None:
            self.__localIpSecRules.remove(value)
            localIpSecRules_values = AutosarNode._add_or_get_xml_node(self._node, 'LOCAL-IP-SEC-RULE-REFS', createNode = False)
            for localIpSecRules_value in self._node.findall('{*}LOCAL-IP-SEC-RULE-REFS/*'):
                if localIpSecRules_value.text == value.path:
                    localIpSecRules_value.text = ''
                    localIpSecRules_values.remove(localIpSecRules_value)
                    value.referenced_by.remove(self)
                    break

    def remove_localIpSecRules(self, values):
        """
        Removes a list of value from localIpSecRules
        """
        for value in values:
            self.remove_localIpSecRule(value)

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['LocalIpSecRules'] = self.__localIpSecRules
        return property_values

    def _update_path(self):
        """
        Updates the path of the IPSecIamRemoteSubject and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

