class LinOrderedConfigurableFrame(ARObject):
    """
    With the assignment of the index to a frame a mapping of Pids to Frames is possible. This element shall be used for the LIN 2.1 Assign-Frame-PID-Range command.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'LIN-ORDERED-CONFIGURABLE-FRAME'
        self.__index = None
        self.__frame = None

    def _build(self, parent, node):
        super()._build(parent, node)
        index_value = AutosarNode._get_node_text(node,'INDEX')
        if index_value is not None:
            self.__index = datatype_utils.get_int_value(index_value)

        return self

    def _resolve_references(self):
        frame_node = self._node.find('{*}FRAME-REF')
        if frame_node is not None and frame_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[frame_node.text]
            ref_value.referenced_by.add(self)
            self.__frame = ref_value

    def get_index(self):
        return self.__index

    def set_index(self, value):
        self.__index = value
        index_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'INDEX')
        index_xml_node.text = str(value) if value is not None else ''

    def get_frame(self):
        return self.__frame

    def set_frame(self, value):
        """
        Adds a single value to the frame
        """
        if value is not None:
            if isinstance(value, LinFrame) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of LinFrame or its sub-classes'.format(value))
            if self.__frame is not None:
                self.__frame.referenced_by.remove(self)
            frame_value = AutosarNode._add_or_get_xml_node(self._node, 'FRAME-REF', value)
            frame_value.text = value.path
            frame_value.attrib['DEST'] = value.tag
            self.__frame = value
            value.referenced_by.add(self)
        elif self.__frame is not None:
            self.__frame.referenced_by.remove(self)
            self.__frame = None
            frame_value = AutosarNode._add_or_get_xml_node(self._node, 'FRAME-REF', createNode = False)
            if frame_value is not None:
                frame_value.referenced_by.remove(self)
                frame_value.text = ''

    def _add_mandatory_attr(self, node, name = None):
        super()._add_mandatory_attr(node, name)
        index_node = etree.SubElement(node, 'INDEX')
        self.__index = 0
        index_node.text = '0'

