class BswImplementation(Implementation):
    """
    Contains the implementation specific information in addition to the generic specification (BswModuleDescription and BswBehavior)., It is possible to have several different BswImplementations referring to the same BswBehavior.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'BSW-IMPLEMENTATION'
        self.__arReleaseVersion = None
        self.__vendorApiInfix = None
        self.__behavior = None
        self.__debugInfos = set()
        self.__preconfiguredConfigurations = set()
        self.__recommendedConfigurations = set()
        self.__vendorSpecificModuleDefs = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        arReleaseVersion_value = AutosarNode._get_node_text(node,'AR-RELEASE-VERSION')
        if arReleaseVersion_value is not None:
            self.__arReleaseVersion = datatype_utils.get_string_value(arReleaseVersion_value)

        vendorApiInfix_value = AutosarNode._get_node_text(node,'VENDOR-API-INFIX')
        if vendorApiInfix_value is not None:
            self.__vendorApiInfix = datatype_utils.get_string_value(vendorApiInfix_value)

        debugInfos_nodes = self._node.findall('{*}DEBUG-INFOS/*')
        for debugInfos_node in debugInfos_nodes:
            self.__debugInfos.add(BswDebugInfo()._build(self, debugInfos_node))

        return self

    def _resolve_references(self):
        behavior_node = self._node.find('{*}BEHAVIOR-REF')
        if behavior_node is not None and behavior_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[behavior_node.text]
            ref_value.referenced_by.add(self)
            self.__behavior = ref_value
        preconfiguredConfigurations_nodes = self._node.findall('{*}PRECONFIGURED-CONFIGURATION-REFS/*')
        for node in preconfiguredConfigurations_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__preconfiguredConfigurations.add(ref_value)
        recommendedConfigurations_nodes = self._node.findall('{*}RECOMMENDED-CONFIGURATION-REFS/*')
        for node in recommendedConfigurations_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__recommendedConfigurations.add(ref_value)
        vendorSpecificModuleDefs_nodes = self._node.findall('{*}VENDOR-SPECIFIC-MODULE-DEF-REFS/*')
        for node in vendorSpecificModuleDefs_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__vendorSpecificModuleDefs.add(ref_value)

