        """
        Adds a single value to the behavior
        """
        if value is not None:
            if isinstance(value, BswInternalBehavior) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of BswInternalBehavior or its sub-classes'.format(value))
            if self.__behavior is not None:
                self.__behavior.referenced_by.remove(self)
            behavior_value = AutosarNode._add_or_get_xml_node(self._node, 'BEHAVIOR-REF', value)
            behavior_value.text = value.path
            behavior_value.attrib['DEST'] = value.tag
            self.__behavior = value
            value.referenced_by.add(self)
        elif self.__behavior is not None:
            self.__behavior.referenced_by.remove(self)
            self.__behavior = None
            behavior_value = AutosarNode._add_or_get_xml_node(self._node, 'BEHAVIOR-REF', createNode = False)
