class VlanMembership(ARObject):
    """
    Static logical channel or VLAN binding to a switch-port., , The reference to an EthernetPhysicalChannel without a VLAN defined represents the handling of untagged frames.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'VLAN-MEMBERSHIP'
        self.__defaultPriority = None
        self.__sendActivity = None
        self.__dhcpAddressAssignment = None
        self.__vlan = None

    def _build(self, parent, node):
        super()._build(parent, node)
        defaultPriority_value = AutosarNode._get_node_text(node,'DEFAULT-PRIORITY')
        if defaultPriority_value is not None:
            self.__defaultPriority = datatype_utils.get_int_value(defaultPriority_value)

        sendActivity_value = AutosarNode._get_node_text(node,'SEND-ACTIVITY')
        if sendActivity_value is not None:
            self.__sendActivity = EthernetSwitchVlanEgressTaggingEnum.get(sendActivity_value)

        dhcpAddressAssignment_node = self._node.find('{*}DHCP-ADDRESS-ASSIGNMENT')
        if dhcpAddressAssignment_node is not None:
            self.__dhcpAddressAssignment = DhcpServerConfiguration()._build(self, dhcpAddressAssignment_node)

        return self

    def _resolve_references(self):
        vlan_node = self._node.find('{*}VLAN-REF')
        if vlan_node is not None and vlan_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[vlan_node.text]
            ref_value.referenced_by.add(self)
            self.__vlan = ref_value

