class Machine(ARElement,AtpStructureElement):
    """
    Machine that represents an Adaptive Autosar Software Stack.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'MACHINE'
        self.__trustedPlatformExecutableLaunchBehavior = None
        self.__defaultApplicationTimeout = None
        self.__environmentVariables = set()
        self.__machineDesign = None
        self.__moduleInstantiations = set()
        self.__processors = set()
        self.__secureCommunicationDeployments = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        trustedPlatformExecutableLaunchBehavior_value = AutosarNode._get_node_text(node,'TRUSTED-PLATFORM-EXECUTABLE-LAUNCH-BEHAVIOR')
        if trustedPlatformExecutableLaunchBehavior_value is not None:
            self.__trustedPlatformExecutableLaunchBehavior = TrustedPlatformExecutableLaunchBehaviorEnum.get(trustedPlatformExecutableLaunchBehavior_value)

        defaultApplicationTimeout_node = self._node.find('{*}DEFAULT-APPLICATION-TIMEOUT')
        if defaultApplicationTimeout_node is not None:
            self.__defaultApplicationTimeout = EnterExitTimeout()._build(self, defaultApplicationTimeout_node)

        environmentVariables_nodes = self._node.findall('{*}ENVIRONMENT-VARIABLES/*')
        for environmentVariables_node in environmentVariables_nodes:
            self.__environmentVariables.add(TagWithOptionalValue()._build(self, environmentVariables_node))

        moduleInstantiations_obj_dict = {}
        moduleInstantiations_obj_dict['OS-MODULE-INSTANTIATION'] = 'OsModuleInstantiation'
        moduleInstantiations_obj_dict['DO-IP-INSTANTIATION'] = 'DoIpInstantiation'
        moduleInstantiations_obj_dict['IAM-MODULE-INSTANTIATION'] = 'IamModuleInstantiation'
        moduleInstantiations_obj_dict['GENERIC-MODULE-INSTANTIATION'] = 'GenericModuleInstantiation'
        moduleInstantiations_obj_dict['TIME-SYNC-MODULE-INSTANTIATION'] = 'TimeSyncModuleInstantiation'
        moduleInstantiations_obj_dict['NM-INSTANTIATION'] = 'NmInstantiation'
        moduleInstantiations_obj_dict['CRYPTO-MODULE-INSTANTIATION'] = 'CryptoModuleInstantiation'
        moduleInstantiations_obj_dict['IDSM-MODULE-INSTANTIATION'] = 'IdsmModuleInstantiation'
        moduleInstantiations_obj_dict['UCM-MODULE-INSTANTIATION'] = 'UcmModuleInstantiation'
        moduleInstantiations_obj_dict['LOG-AND-TRACE-INSTANTIATION'] = 'LogAndTraceInstantiation'
        moduleInstantiations_nodes = self._node.findall('{*}MODULE-INSTANTIATIONS/*')
        for moduleInstantiations_node in moduleInstantiations_nodes:
            self.__moduleInstantiations.add(__str_to_class__(moduleInstantiations_obj_dict[etree.QName(moduleInstantiations_node).localname])()._build(self, moduleInstantiations_node))

        processors_nodes = self._node.findall('{*}PROCESSORS/*')
        for processors_node in processors_nodes:
            self.__processors.add(Processor()._build(self, processors_node))

        secureCommunicationDeployments_obj_dict = {}
        secureCommunicationDeployments_obj_dict['SEC-OC-DEPLOYMENT'] = 'SecOcDeployment'
        secureCommunicationDeployments_obj_dict['TLS-DEPLOYMENT'] = 'TlsDeployment'
        secureCommunicationDeployments_nodes = self._node.findall('{*}SECURE-COMMUNICATION-DEPLOYMENTS/*')
        for secureCommunicationDeployments_node in secureCommunicationDeployments_nodes:
            self.__secureCommunicationDeployments.add(__str_to_class__(secureCommunicationDeployments_obj_dict[etree.QName(secureCommunicationDeployments_node).localname])()._build(self, secureCommunicationDeployments_node))

        return self

    def _resolve_references(self):
        machineDesign_node = self._node.find('{*}MACHINE-DESIGN-REF')
        if machineDesign_node is not None and machineDesign_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[machineDesign_node.text]
            ref_value.referenced_by.add(self)
            self.__machineDesign = ref_value

    def get_trustedPlatformExecutableLaunchBehavior(self):
        return self.__trustedPlatformExecutableLaunchBehavior

    def set_trustedPlatformExecutableLaunchBehavior(self, value):
        self.__trustedPlatformExecutableLaunchBehavior = value
        trustedPlatformExecutableLaunchBehavior_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'TRUSTED-PLATFORM-EXECUTABLE-LAUNCH-BEHAVIOR')
        trustedPlatformExecutableLaunchBehavior_xml_node.text = value.literal if value is not None else ''

    def get_defaultApplicationTimeout(self):
        return self.__defaultApplicationTimeout

    def set_defaultApplicationTimeout(self, value):
        """
        Adds a single value to the defaultApplicationTimeout
        """
        if value is not None:
            if isinstance(value, EnterExitTimeout) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of EnterExitTimeout or its sub-classes'.format(value))
            if self.__defaultApplicationTimeout is not None:
                self._node.remove(self.__defaultApplicationTimeout._node)
            # if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            self._node.append(value._node)
            self.__defaultApplicationTimeout = value
            value._parent = self #set parent
            value._update_path() #updates the path
        elif self.__defaultApplicationTimeout is not None:
            self._node.remove(self.__defaultApplicationTimeout._node)
            self.__defaultApplicationTimeout = None
            self.__defaultApplicationTimeout._parent = None #No parent
            self.__defaultApplicationTimeout._update_path() #updates the path

