class AdminData(ARObject):
    """
    AdminData represents the ability to express administrative information for an element. This administration information is to be treated as meta-data such as revision id or state of the file. There are basically four kinds of meta-data, , * The language and/or used languages., , * Revision information covering e.g. revision number, state, release date, changes. Note that this information can be given in general as well as related to a particular company., , * Document meta-data specific for a company
    """
    def __init__(self):
        super().__init__()
        self.tag = 'ADMIN-DATA'
        self.__language = None
        self.__usedLanguages = None
        self.__docRevisions = set()
        self.__sdgs = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        language_value = AutosarNode._get_node_text(node,'LANGUAGE')
        if language_value is not None:
            self.__language = LEnum.get(language_value)

        usedLanguages_node = self._node.find('{*}USED-LANGUAGES')
        if usedLanguages_node is not None:
            self.__usedLanguages = MultiLanguagePlainText()._build(self, usedLanguages_node)

        docRevisions_nodes = self._node.findall('{*}DOC-REVISIONS/*')
        for docRevisions_node in docRevisions_nodes:
            self.__docRevisions.add(DocRevision()._build(self, docRevisions_node))

        sdgs_nodes = self._node.findall('{*}SDGS/*')
        for sdgs_node in sdgs_nodes:
            self.__sdgs.add(Sdg()._build(self, sdgs_node))

        return self

    def get_language(self):
        return self.__language

    def set_language(self, value):
        self.__language = value
        language_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'LANGUAGE')
        language_xml_node.text = value.literal if value is not None else ''

