        dataPdu_node = self._node.find('{*}DATA-PDU-REF')
        if dataPdu_node is not None and dataPdu_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[dataPdu_node.text]
            ref_value.referenced_by.add(self)
            self.__dataPdu = ref_value
        directPdu_node = self._node.find('{*}DIRECT-PDU-REF')
        if directPdu_node is not None and directPdu_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[directPdu_node.text]
            ref_value.referenced_by.add(self)
            self.__directPdu = ref_value
        flowControlPdus_nodes = self._node.findall('{*}FLOW-CONTROL-PDU-REFS/*')
        for node in flowControlPdus_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__flowControlPdus.add(ref_value)
        receivers_nodes = self._node.findall('{*}RECEIVER-REFS/*')
