class EcucSymbolicNameReferenceDef(EcucAbstractInternalReferenceDef):
    """
    This meta-class specifies that the implementation of the reference is done using a symbolic name defined by the referenced Container's shortName.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'ECUC-SYMBOLIC-NAME-REFERENCE-DEF'
        self.__destination = None


    def _resolve_references(self):
        destination_node = self._node.find('{*}DESTINATION-REF')
        if destination_node is not None and destination_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[destination_node.text]
            ref_value.referenced_by.add(self)
            self.__destination = ref_value

    def get_destination(self):
        return self.__destination

    def set_destination(self, value):
        """
        Adds a single value to the destination
        """
        if value is not None:
            if isinstance(value, EcucParamConfContainerDef) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of EcucParamConfContainerDef or its sub-classes'.format(value))
            if self.__destination is not None:
                self.__destination.referenced_by.remove(self)
            destination_value = AutosarNode._add_or_get_xml_node(self._node, 'DESTINATION-REF', value)
            destination_value.text = value.path
            destination_value.attrib['DEST'] = value.tag
            self.__destination = value
            value.referenced_by.add(self)
        elif self.__destination is not None:
            self.__destination.referenced_by.remove(self)
            self.__destination = None
            destination_value = AutosarNode._add_or_get_xml_node(self._node, 'DESTINATION-REF', createNode = False)
            if destination_value is not None:
                destination_value.referenced_by.remove(self)
                destination_value.text = ''

