class PhmSupervisedEntityInterface(PlatformHealthManagementInterface):
    """
    This meta-class provides the ability to implement a PortInterface for interaction with the Platform Health Management Supervised Entity.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'PHM-SUPERVISED-ENTITY-INTERFACE'
        self.__checkpoints = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        checkpoints_nodes = self._node.findall('{*}CHECKPOINTS/*')
        for checkpoints_node in checkpoints_nodes:
            self.__checkpoints.add(PhmCheckpoint()._build(self, checkpoints_node))

        return self

    def get_checkpoints(self):
        return self.__checkpoints

    def add_checkpoint(self, value):
        """
        Adds a single value to the checkpoints
        """
        if value is not None:
            if any(v.name == value.name for v in self.__checkpoints):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, PhmCheckpoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of PhmCheckpoint or its sub-classes'.format(value))
            self.__checkpoints.add(value)
            checkpoints_values = AutosarNode._add_or_get_xml_node(self._node, 'CHECKPOINTS')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            checkpoints_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_checkpoints(self, values):
        """
        Adds a list of ref value to the checkpoints
        """
        for value in values:
            self.add_checkpoint(value)

    def remove_checkpoint(self, value):
        """
        Removes a single value from checkpoints
        """
        if value is not None:
            self.__checkpoints.remove(value)
            checkpoints_values = AutosarNode._add_or_get_xml_node(self._node, 'CHECKPOINTS', createNode = False)
            checkpoints_values.remove(value._node)
            value._parent = None #No parent
            value._update_path() #resets the path

    def remove_checkpoints(self, values):
        """
        Removes a list of value from checkpoints
        """
        for value in values:
            self.remove_checkpoint(value)

    def new_Checkpoint(self, name=None):
        """
        Creates a new PhmCheckpoint under the PhmSupervisedEntityInterface.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        PhmCheckpoint_obj = PhmCheckpoint()
        if isinstance(PhmCheckpoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('PHM-CHECKPOINT')
        PhmCheckpoint_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        PhmCheckpoint_obj.name = name
        PhmCheckpoint_obj._node = xmlNode
        self.add_checkpoint(PhmCheckpoint_obj)
        return PhmCheckpoint_obj

    def get_children(self):
        children = super().get_children()
        children.extend(self.__checkpoints)
        return children

    def _update_path(self):
        """
        Updates the path of the PhmSupervisedEntityInterface and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

class TriggerMapping(ARObject):
    """
    Defines the mapping of two particular unequally named Triggers in the given context.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'TRIGGER-MAPPING'
        self.__firstTrigger = None
        self.__secondTrigger = None


    def _resolve_references(self):
        firstTrigger_node = self._node.find('{*}FIRST-TRIGGER-REF')
        if firstTrigger_node is not None and firstTrigger_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[firstTrigger_node.text]
            ref_value.referenced_by.add(self)
            self.__firstTrigger = ref_value
        secondTrigger_node = self._node.find('{*}SECOND-TRIGGER-REF')
        if secondTrigger_node is not None and secondTrigger_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[secondTrigger_node.text]
            ref_value.referenced_by.add(self)
            self.__secondTrigger = ref_value

    def get_firstTrigger(self):
        return self.__firstTrigger

    def set_firstTrigger(self, value):
        """
        Adds a single value to the firstTrigger
        """
        if value is not None:
            if isinstance(value, Trigger) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of Trigger or its sub-classes'.format(value))
            if self.__firstTrigger is not None:
                self.__firstTrigger.referenced_by.remove(self)
            firstTrigger_value = AutosarNode._add_or_get_xml_node(self._node, 'FIRST-TRIGGER-REF', value)
            firstTrigger_value.text = value.path
            firstTrigger_value.attrib['DEST'] = value.tag
            self.__firstTrigger = value
            value.referenced_by.add(self)
        elif self.__firstTrigger is not None:
            self.__firstTrigger.referenced_by.remove(self)
            self.__firstTrigger = None
            firstTrigger_value = AutosarNode._add_or_get_xml_node(self._node, 'FIRST-TRIGGER-REF', createNode = False)
            if firstTrigger_value is not None:
                firstTrigger_value.referenced_by.remove(self)
                firstTrigger_value.text = ''

    def get_secondTrigger(self):
        return self.__secondTrigger

    def set_secondTrigger(self, value):
        """
        Adds a single value to the secondTrigger
        """
        if value is not None:
            if isinstance(value, Trigger) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of Trigger or its sub-classes'.format(value))
            if self.__secondTrigger is not None:
                self.__secondTrigger.referenced_by.remove(self)
            secondTrigger_value = AutosarNode._add_or_get_xml_node(self._node, 'SECOND-TRIGGER-REF', value)
            secondTrigger_value.text = value.path
            secondTrigger_value.attrib['DEST'] = value.tag
            self.__secondTrigger = value
            value.referenced_by.add(self)
        elif self.__secondTrigger is not None:
            self.__secondTrigger.referenced_by.remove(self)
            self.__secondTrigger = None
            secondTrigger_value = AutosarNode._add_or_get_xml_node(self._node, 'SECOND-TRIGGER-REF', createNode = False)
            if secondTrigger_value is not None:
                secondTrigger_value.referenced_by.remove(self)
                secondTrigger_value.text = ''

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['FirstTrigger'] = self.__firstTrigger
        property_values['SecondTrigger'] = self.__secondTrigger
        return property_values

    def _update_path(self):
        """
        Updates the path of the TriggerMapping and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

