class EcucDerivationSpecification(ARObject):
    """
    Allows to define configuration items that are calculated based on the value of, * other parameter values, * elements (attributes/classes) defined in other AUTOSAR templates such as System template and SW component template
    """
    def __init__(self):
        super().__init__()
        self.tag = 'ECUC-DERIVATION-SPECIFICATION'
        self.__calculationFormula = None
        self.__ecucQueries = set()
        self.__informalFormula = None

    def _build(self, parent, node):
        super()._build(parent, node)
        calculationFormula_node = self._node.find('{*}CALCULATION-FORMULA')
        if calculationFormula_node is not None:
            self.__calculationFormula = EcucParameterDerivationFormula()._build(self, calculationFormula_node)

        ecucQueries_nodes = self._node.findall('{*}ECUC-QUERYS/*')
        for ecucQueries_node in ecucQueries_nodes:
            self.__ecucQueries.add(EcucQuery()._build(self, ecucQueries_node))

        informalFormula_node = self._node.find('{*}INFORMAL-FORMULA')
        if informalFormula_node is not None:
            self.__informalFormula = MlFormula()._build(self, informalFormula_node)

        return self

    def get_calculationFormula(self):
        return self.__calculationFormula

