        functionalRequests_nodes = self._node.findall('{*}FUNCTIONAL-REQUEST-REFS/*')
        for node in functionalRequests_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
