class TpAddress(Identifiable):
    """
    An ECUs TP address on the referenced channel. This represents the diagnostic Address.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'TP-ADDRESS'
        self.__tpAddress = None
        self.__variationPoint = None

    def _build(self, parent, node):
        super()._build(parent, node)
        tpAddress_value = AutosarNode._get_node_text(node,'TP-ADDRESS')
        if tpAddress_value is not None:
            self.__tpAddress = datatype_utils.get_int_value(tpAddress_value)

        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            self.__variationPoint = VariationPoint()._build(self, variationPoint_node)

        return self

