class SynchronizationTimingConstraint(TimingConstraint):
    """
    This constraint is used to restrict the timing behavior of different, but correlated events or event chains, with regard to synchronization., , Thereby, in case of imposing a synchronization timing constraint on events or event chains the following two scenarios are supported:, , 1) [synchronizationConstraintType=responseSynchronization] Events: An arbitrary number of correlated events which play the role of responses shall occur synchronously with respect to a predefined tolerance. Event Chains: An arbitrary number of correlated event chains with a common stimulus, but different responses, where the responses shall occur synchronously with respect to a predefined tolerance., , 2) [synchronizationConstraintType=stimulusSynchronization] Events: An arbitrary number of correlated events which play the role of stimuli shall occur synchronously with respect to a predefined tolerance. Event Chains: An arbitrary number of correlated event chains with a common response, but different stimuli, where the stimuli shall occur synchronously with respect to a predefined tolerance., , In case of imposing a synchronization timing constraint on events the following two scenarios are supported:, , 1) [eventOccurrenceKind=singleOccurrence] Any of the events shall occur only once in the given time interval., , 2) [eventOccurrenceKind=multipleOccurrences] Any of the events may occur more than once in the given time interval. In other words multiple occurrences of an event within the given time interval are permitted.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'SYNCHRONIZATION-TIMING-CONSTRAINT'
        self.__eventOccurrenceKind = None
        self.__synchronizationConstraintType = None
        self.__scopeEvents = set()
        self.__scopes = set()
        self.__tolerance = None

    def _build(self, parent, node):
        super()._build(parent, node)
        eventOccurrenceKind_value = AutosarNode._get_node_text(node,'EVENT-OCCURRENCE-KIND')
        if eventOccurrenceKind_value is not None:
            self.__eventOccurrenceKind = EventOccurrenceKindEnum.get(eventOccurrenceKind_value)

        synchronizationConstraintType_value = AutosarNode._get_node_text(node,'SYNCHRONIZATION-CONSTRAINT-TYPE')
        if synchronizationConstraintType_value is not None:
            self.__synchronizationConstraintType = SynchronizationTypeEnum.get(synchronizationConstraintType_value)

        tolerance_node = self._node.find('{*}TOLERANCE')
        if tolerance_node is not None:
            self.__tolerance = MultidimensionalTime()._build(self, tolerance_node)

        return self

    def _resolve_references(self):
        scopeEvents_nodes = self._node.findall('{*}SCOPE-EVENT-REFS/*')
        for node in scopeEvents_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__scopeEvents.add(ref_value)
        scopes_nodes = self._node.findall('{*}SCOPE-REFS/*')
        for node in scopes_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__scopes.add(ref_value)

    def get_eventOccurrenceKind(self):
        return self.__eventOccurrenceKind

    def set_eventOccurrenceKind(self, value):
        self.__eventOccurrenceKind = value
        eventOccurrenceKind_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'EVENT-OCCURRENCE-KIND')
        eventOccurrenceKind_xml_node.text = value.literal if value is not None else ''

    def get_synchronizationConstraintType(self):
        return self.__synchronizationConstraintType

    def set_synchronizationConstraintType(self, value):
        self.__synchronizationConstraintType = value
        synchronizationConstraintType_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'SYNCHRONIZATION-CONSTRAINT-TYPE')
        synchronizationConstraintType_xml_node.text = value.literal if value is not None else ''

    def get_scopeEvents(self):
        return self.__scopeEvents

    def add_scopeEvent(self, value):
        """
        Adds a single value to the scopeEvents
        """
        if value is not None:
            if any(v.name == value.name for v in self.__scopeEvents):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, TimingDescriptionEvent) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of TimingDescriptionEvent or its sub-classes'.format(value))
            self.__scopeEvents.add(value)
            scopeEvents_values = AutosarNode._add_or_get_xml_node(self._node, 'SCOPE-EVENT-REFS')

            scopeEvents_value = AutosarNode._add_or_get_xml_node(scopeEvents_values, 'SCOPE-EVENT-REF', value, forceCreate = True)
            scopeEvents_value.text = value.path
            value.referenced_by.add(self)

    def set_scopeEvents(self, values):
        """
        Adds a list of ref value to the scopeEvents
        """
        for value in values:
            self.add_scopeEvent(value)

    def remove_scopeEvent(self, value):
        """
        Removes a single value from scopeEvents
        """
        if value is not None:
            self.__scopeEvents.remove(value)
            scopeEvents_values = AutosarNode._add_or_get_xml_node(self._node, 'SCOPE-EVENT-REFS', createNode = False)
            for scopeEvents_value in self._node.findall('{*}SCOPE-EVENT-REFS/*'):
                if scopeEvents_value.text == value.path:
                    scopeEvents_value.text = ''
                    scopeEvents_values.remove(scopeEvents_value)
                    value.referenced_by.remove(self)
                    break

    def remove_scopeEvents(self, values):
        """
        Removes a list of value from scopeEvents
        """
        for value in values:
            self.remove_scopeEvent(value)

    def get_scopes(self):
        return self.__scopes

    def add_scope(self, value):
        """
        Adds a single value to the scopes
        """
        if value is not None:
            if any(v.name == value.name for v in self.__scopes):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, TimingDescriptionEventChain) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of TimingDescriptionEventChain or its sub-classes'.format(value))
            self.__scopes.add(value)
            scopes_values = AutosarNode._add_or_get_xml_node(self._node, 'SCOPE-REFS')

            scopes_value = AutosarNode._add_or_get_xml_node(scopes_values, 'SCOPE-REF', value, forceCreate = True)
            scopes_value.text = value.path
            value.referenced_by.add(self)

    def set_scopes(self, values):
        """
        Adds a list of ref value to the scopes
        """
        for value in values:
            self.add_scope(value)

    def remove_scope(self, value):
        """
        Removes a single value from scopes
        """
        if value is not None:
            self.__scopes.remove(value)
            scopes_values = AutosarNode._add_or_get_xml_node(self._node, 'SCOPE-REFS', createNode = False)
            for scopes_value in self._node.findall('{*}SCOPE-REFS/*'):
                if scopes_value.text == value.path:
                    scopes_value.text = ''
                    scopes_values.remove(scopes_value)
                    value.referenced_by.remove(self)
                    break

    def remove_scopes(self, values):
        """
        Removes a list of value from scopes
        """
        for value in values:
            self.remove_scope(value)

    def get_tolerance(self):
        return self.__tolerance

    def set_tolerance(self, value):
        """
        Adds a single value to the tolerance
        """
        if value is not None:
            if isinstance(value, MultidimensionalTime) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of MultidimensionalTime or its sub-classes'.format(value))
            if self.__tolerance is not None:
                self._node.remove(self.__tolerance._node)
            # if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            self._node.append(value._node)
            self.__tolerance = value
            value._parent = self #set parent
            value._update_path() #updates the path
        elif self.__tolerance is not None:
            self._node.remove(self.__tolerance._node)
            self.__tolerance = None
            self.__tolerance._parent = None #No parent
            self.__tolerance._update_path() #updates the path

    def new_Tolerance(self, name=None):
        """
        Creates a new MultidimensionalTime under the SynchronizationTimingConstraint.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        MultidimensionalTime_obj = MultidimensionalTime()
        if isinstance(MultidimensionalTime_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('TOLERANCE')
        MultidimensionalTime_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        MultidimensionalTime_obj.name = name
        MultidimensionalTime_obj._node = xmlNode
        self.set_tolerance(MultidimensionalTime_obj)
        return MultidimensionalTime_obj

    def _add_mandatory_attr(self, node, name = None):
        super()._add_mandatory_attr(node, name)
        synchronizationConstraintType_node = etree.SubElement(node, 'SYNCHRONIZATION-CONSTRAINT-TYPE')
        synchronizationConstraintType_node.text = ''

    def get_children(self):
        children = super().get_children()
        if self.__tolerance is not None:
            children.append(self.__tolerance)
        return children

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['EventOccurrenceKind'] = self.__eventOccurrenceKind
        property_values['SynchronizationConstraintType'] = self.__synchronizationConstraintType
        property_values['ScopeEvents'] = self.__scopeEvents
        property_values['Scopes'] = self.__scopes
        return property_values

    def _update_path(self):
        """
        Updates the path of the SynchronizationTimingConstraint and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

