class BswModuleDependency(Identifiable):
    """
    This class collects the dependencies of a BSW module or cluster on a certain other BSW module.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'BSW-MODULE-DEPENDENCY'
        self.__targetModuleId = None
        self.__targetModuleRefs = set()
        self.__requiredEntries = set()
        self.__expectedCallbacks = set()
        self.__serviceItems = set()
        self.__variationPoint = None

    def _build(self, parent, node):
        super()._build(parent, node)
        targetModuleId_value = AutosarNode._get_node_text(node,'TARGET-MODULE-ID')
        if targetModuleId_value is not None:
            self.__targetModuleId = datatype_utils.get_int_value(targetModuleId_value)

        targetModuleRefs_nodes = self._node.findall('{*}TARGET-MODULE-REFS/*')
        for targetModuleRefs_node in targetModuleRefs_nodes:
            self.__targetModuleRefs.add(BswModuleDescriptionRefConditional()._build(self, targetModuleRefs_node))

        requiredEntries_nodes = self._node.findall('{*}REQUIRED-ENTRYS/*')
        for requiredEntries_node in requiredEntries_nodes:
            self.__requiredEntries.add(BswModuleEntryRefConditional()._build(self, requiredEntries_node))

        expectedCallbacks_nodes = self._node.findall('{*}EXPECTED-CALLBACKS/*')
        for expectedCallbacks_node in expectedCallbacks_nodes:
            self.__expectedCallbacks.add(BswModuleEntryRefConditional()._build(self, expectedCallbacks_node))

        serviceItems_obj_dict = {}
        serviceItems_obj_dict['DO-IP-GID-SYNCHRONIZATION-NEEDS'] = 'DoIpGidSynchronizationNeeds'
        serviceItems_obj_dict['OBD-CONTROL-SERVICE-NEEDS'] = 'ObdControlServiceNeeds'
