class ExecutableTiming(TimingExtension):
    """
    This meta-class represents the timing view for one or more executables.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'EXECUTABLE-TIMING'
        self.__executables = set()


    def _resolve_references(self):
        executables_nodes = self._node.findall('{*}EXECUTABLE-REFS/*')
        for node in executables_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__executables.add(ref_value)

    def get_executables(self):
        return self.__executables

    def add_executable(self, value):
        """
        Adds a single value to the executables
        """
        if value is not None:
            if any(v.name == value.name for v in self.__executables):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, Executable) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of Executable or its sub-classes'.format(value))
            self.__executables.add(value)
            executables_values = AutosarNode._add_or_get_xml_node(self._node, 'EXECUTABLE-REFS')

            executables_value = AutosarNode._add_or_get_xml_node(executables_values, 'EXECUTABLE-REF', value, forceCreate = True)
            executables_value.text = value.path
            value.referenced_by.add(self)

    def set_executables(self, values):
        """
        Adds a list of ref value to the executables
        """
        for value in values:
            self.add_executable(value)

    def remove_executable(self, value):
        """
        Removes a single value from executables
        """
        if value is not None:
            self.__executables.remove(value)
            executables_values = AutosarNode._add_or_get_xml_node(self._node, 'EXECUTABLE-REFS', createNode = False)
            for executables_value in self._node.findall('{*}EXECUTABLE-REFS/*'):
                if executables_value.text == value.path:
                    executables_value.text = ''
                    executables_values.remove(executables_value)
                    value.referenced_by.remove(self)
                    break

    def remove_executables(self, values):
        """
        Removes a list of value from executables
        """
        for value in values:
            self.remove_executable(value)

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['Executables'] = self.__executables
        return property_values

    def _update_path(self):
        """
        Updates the path of the ExecutableTiming and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

class TargetIPduRef(ARObject):
    """
    Target destination of the referencing mapping.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'TARGET-I-PDU-REF'
        self.__defaultValue = None
        self.__targetIPdu = None

    def _build(self, parent, node):
        super()._build(parent, node)
        defaultValue_node = self._node.find('{*}DEFAULT-VALUE')
        if defaultValue_node is not None:
            self.__defaultValue = PduMappingDefaultValue()._build(self, defaultValue_node)

        return self

    def _resolve_references(self):
        targetIPdu_node = self._node.find('{*}TARGET-I-PDU-REF')
        if targetIPdu_node is not None and targetIPdu_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[targetIPdu_node.text]
            ref_value.referenced_by.add(self)
            self.__targetIPdu = ref_value

    def get_defaultValue(self):
        return self.__defaultValue

    def set_defaultValue(self, value):
        """
        Adds a single value to the defaultValue
        """
        if value is not None:
            if isinstance(value, PduMappingDefaultValue) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of PduMappingDefaultValue or its sub-classes'.format(value))
            if self.__defaultValue is not None:
                self._node.remove(self.__defaultValue._node)
            # if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            self._node.append(value._node)
            self.__defaultValue = value
            value._parent = self #set parent
            value._update_path() #updates the path
        elif self.__defaultValue is not None:
            self._node.remove(self.__defaultValue._node)
            self.__defaultValue = None
            self.__defaultValue._parent = None #No parent
            self.__defaultValue._update_path() #updates the path

    def get_targetIPdu(self):
        return self.__targetIPdu

    def set_targetIPdu(self, value):
        """
        Adds a single value to the targetIPdu
        """
        if value is not None:
            if isinstance(value, PduTriggering) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of PduTriggering or its sub-classes'.format(value))
            if self.__targetIPdu is not None:
                self.__targetIPdu.referenced_by.remove(self)
            targetIPdu_value = AutosarNode._add_or_get_xml_node(self._node, 'TARGET-I-PDU-REF', value)
            targetIPdu_value.text = value.path
            targetIPdu_value.attrib['DEST'] = value.tag
            self.__targetIPdu = value
            value.referenced_by.add(self)
        elif self.__targetIPdu is not None:
            self.__targetIPdu.referenced_by.remove(self)
            self.__targetIPdu = None
            targetIPdu_value = AutosarNode._add_or_get_xml_node(self._node, 'TARGET-I-PDU-REF', createNode = False)
            if targetIPdu_value is not None:
                targetIPdu_value.referenced_by.remove(self)
                targetIPdu_value.text = ''

    def new_DefaultValue(self, name=None):
        """
        Creates a new PduMappingDefaultValue under the TargetIPduRef.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        PduMappingDefaultValue_obj = PduMappingDefaultValue()
