class RoleBasedMcDataAssignment(ARObject):
    """
    This meta-class allows to define links that specify logical relationships between single McDataInstances. The details on the existence and semantics of such links are not standardized., , Possible Use Case: , Rapid Prototyping solutions in which additional communication buffers and switches are implemented  in the RTE that allow to switch between the usage of the original and the bypass buffers. The different buffers and the switch can be represented by McDataInstances (in order to be accessed by MC tools) which have relationships to each other.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'ROLE-BASED-MC-DATA-ASSIGNMENT'
        self.__role = None
        self.__executionContexts = set()
        self.__mcDataInstances = set()
        self.__variationPoint = None

    def _build(self, parent, node):
        super()._build(parent, node)
        role_value = AutosarNode._get_node_text(node,'ROLE')
        if role_value is not None:
            self.__role = datatype_utils.get_string_value(role_value)

        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            self.__variationPoint = VariationPoint()._build(self, variationPoint_node)

        return self

    def _resolve_references(self):
        executionContexts_nodes = self._node.findall('{*}EXECUTION-CONTEXT-REFS/*')
        for node in executionContexts_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__executionContexts.add(ref_value)
        mcDataInstances_nodes = self._node.findall('{*}MC-DATA-INSTANCE-REFS/*')
        for node in mcDataInstances_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__mcDataInstances.add(ref_value)

    def get_role(self):
        return self.__role

    def set_role(self, value):
        self.__role = value
        role_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'ROLE')
        role_xml_node.text = str(value) if value is not None else ''

    def get_executionContexts(self):
        return self.__executionContexts

    def add_executionContext(self, value):
        """
        Adds a single value to the executionContexts
        """
        if value is not None:
            if any(v.name == value.name for v in self.__executionContexts):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, RptExecutionContext) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of RptExecutionContext or its sub-classes'.format(value))
            self.__executionContexts.add(value)
            executionContexts_values = AutosarNode._add_or_get_xml_node(self._node, 'EXECUTION-CONTEXT-REFS')

            executionContexts_value = AutosarNode._add_or_get_xml_node(executionContexts_values, 'EXECUTION-CONTEXT-REF', value, forceCreate = True)
            executionContexts_value.text = value.path
            value.referenced_by.add(self)

    def set_executionContexts(self, values):
        """
        Adds a list of ref value to the executionContexts
        """
        for value in values:
            self.add_executionContext(value)

    def remove_executionContext(self, value):
        """
        Removes a single value from executionContexts
        """
        if value is not None:
            self.__executionContexts.remove(value)
            executionContexts_values = AutosarNode._add_or_get_xml_node(self._node, 'EXECUTION-CONTEXT-REFS', createNode = False)
            for executionContexts_value in self._node.findall('{*}EXECUTION-CONTEXT-REFS/*'):
                if executionContexts_value.text == value.path:
                    executionContexts_value.text = ''
                    executionContexts_values.remove(executionContexts_value)
                    value.referenced_by.remove(self)
                    break

    def remove_executionContexts(self, values):
        """
        Removes a list of value from executionContexts
        """
        for value in values:
            self.remove_executionContext(value)

