class CanTpAddress(Identifiable):
    """
    An ECUs TP address on the referenced channel. This represents the diagnostic Address.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'CAN-TP-ADDRESS'
        self.__tpAddress = None
        self.__tpAddressExtensionValue = None
        self.__variationPoint = None

    def _build(self, parent, node):
        super()._build(parent, node)
        tpAddress_value = AutosarNode._get_node_text(node,'TP-ADDRESS')
        if tpAddress_value is not None:
            self.__tpAddress = datatype_utils.get_int_value(tpAddress_value)

        tpAddressExtensionValue_value = AutosarNode._get_node_text(node,'TP-ADDRESS-EXTENSION-VALUE')
        if tpAddressExtensionValue_value is not None:
            self.__tpAddressExtensionValue = datatype_utils.get_int_value(tpAddressExtensionValue_value)

        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            self.__variationPoint = VariationPoint()._build(self, variationPoint_node)

        return self

    def get_tpAddress(self):
        return self.__tpAddress

    def set_tpAddress(self, value):
        self.__tpAddress = value
        tpAddress_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'TP-ADDRESS')
        tpAddress_xml_node.text = str(value) if value is not None else ''

    def get_tpAddressExtensionValue(self):
        return self.__tpAddressExtensionValue

    def set_tpAddressExtensionValue(self, value):
        self.__tpAddressExtensionValue = value
        tpAddressExtensionValue_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'TP-ADDRESS-EXTENSION-VALUE')
        tpAddressExtensionValue_xml_node.text = str(value) if value is not None else ''

    def get_variationPoint(self):
        return self.__variationPoint

    def set_variationPoint(self, value):
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))
            if self.__variationPoint is not None:
                self._node.remove(self.__variationPoint._node)
            # if it has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            self._node.append(value._node)
            self.__variationPoint = value
            value._parent = self #set parent
            value._update_path() #updates the path
        elif self.__variationPoint is not None:
            self._node.remove(self.__variationPoint._node)
            self.__variationPoint = None
            self.__variationPoint._parent = None #No parent
            self.__variationPoint._update_path() #updates the path

    def new_VariationPoint(self, name=None):
        """
        Creates a new VariationPoint under the CanTpAddress.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        VariationPoint_obj = VariationPoint()
        if isinstance(VariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('VARIATION-POINT')
        VariationPoint_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        VariationPoint_obj.name = name
        VariationPoint_obj._node = xmlNode
        self.set_variationPoint(VariationPoint_obj)
        return VariationPoint_obj

    def _add_mandatory_attr(self, node, name = None):
        super()._add_mandatory_attr(node, name)
        tpAddress_node = etree.SubElement(node, 'TP-ADDRESS')
        self.__tpAddress = 0
        tpAddress_node.text = '0'

    def get_children(self):
        children = super().get_children()
        if self.__variationPoint is not None:
            children.append(self.__variationPoint)
        return children

