class SocketConnection(Describable):
    """
    The SoAd serves as a (De)Multiplexer between different PDU sources and the TCP/IP stack.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'SOCKET-CONNECTION'
        self.__autosarConnector = None
        self.__clientIpAddrFromConnectionRequest = None
        self.__clientPortFromConnectionRequest = None
        self.__pduCollectionMaxBufferSize = None
        self.__pduCollectionTimeout = None
        self.__runtimeIpAddressConfiguration = None
        self.__runtimePortConfiguration = None
        self.__shortLabel = None
        self.__socketProtocol = None
        self.__allowedIPv6ExtHeaders = None
        self.__allowedTcpOptions = None
        self.__clientPort = None
        self.__doIpSourceAddress = None
        self.__doIpTargetAddress = None
        self.__ident = None
        self.__localPort = None
        self.__nPdu = None
        self.__pdus = set()
        self.__remotePort = None
        self.__variationPoint = None

    def _build(self, parent, node):
        super()._build(parent, node)
        autosarConnector_value = AutosarNode._get_node_text(node,'AUTOSAR-CONNECTOR')
        if autosarConnector_value is not None:
            self.__autosarConnector = SoAdConnectorType.get(autosarConnector_value)

        clientIpAddrFromConnectionRequest_value = AutosarNode._get_node_text(node,'CLIENT-IP-ADDR-FROM-CONNECTION-REQUEST')
        if clientIpAddrFromConnectionRequest_value is not None:
            self.__clientIpAddrFromConnectionRequest = datatype_utils.get_bool_value(clientIpAddrFromConnectionRequest_value)

        clientPortFromConnectionRequest_value = AutosarNode._get_node_text(node,'CLIENT-PORT-FROM-CONNECTION-REQUEST')
        if clientPortFromConnectionRequest_value is not None:
            self.__clientPortFromConnectionRequest = datatype_utils.get_bool_value(clientPortFromConnectionRequest_value)

        pduCollectionMaxBufferSize_value = AutosarNode._get_node_text(node,'PDU-COLLECTION-MAX-BUFFER-SIZE')
        if pduCollectionMaxBufferSize_value is not None:
            self.__pduCollectionMaxBufferSize = datatype_utils.get_int_value(pduCollectionMaxBufferSize_value)

        pduCollectionTimeout_value = AutosarNode._get_node_text(node,'PDU-COLLECTION-TIMEOUT')
        if pduCollectionTimeout_value is not None:
            self.__pduCollectionTimeout = datatype_utils.get_float_value(pduCollectionTimeout_value)

        runtimeIpAddressConfiguration_value = AutosarNode._get_node_text(node,'RUNTIME-IP-ADDRESS-CONFIGURATION')
        if runtimeIpAddressConfiguration_value is not None:
            self.__runtimeIpAddressConfiguration = RuntimeAddressConfigurationEnum.get(runtimeIpAddressConfiguration_value)

        runtimePortConfiguration_value = AutosarNode._get_node_text(node,'RUNTIME-PORT-CONFIGURATION')
        if runtimePortConfiguration_value is not None:
            self.__runtimePortConfiguration = RuntimeAddressConfigurationEnum.get(runtimePortConfiguration_value)

        shortLabel_value = AutosarNode._get_node_text(node,'SHORT-LABEL')
        if shortLabel_value is not None:
            self.__shortLabel = datatype_utils.get_string_value(shortLabel_value)

        socketProtocol_value = AutosarNode._get_node_text(node,'SOCKET-PROTOCOL')
        if socketProtocol_value is not None:
            self.__socketProtocol = SoAdProtocolType.get(socketProtocol_value)

        ident_node = self._node.find('{*}IDENT')
        if ident_node is not None:
            self.__ident = TpConnectionIdent()._build(self, ident_node)

        pdus_nodes = self._node.findall('{*}PDUS/*')
        for pdus_node in pdus_nodes:
            self.__pdus.add(SocketConnectionIpduIdentifier()._build(self, pdus_node))

        variationPoint_node = self._node.find('{*}VARIATION-POINT')
        if variationPoint_node is not None:
            self.__variationPoint = VariationPoint()._build(self, variationPoint_node)

        return self

    def _resolve_references(self):
        allowedIPv6ExtHeaders_node = self._node.find('{*}ALLOWED-I-PV-6-EXT-HEADERS-REF')
        if allowedIPv6ExtHeaders_node is not None and allowedIPv6ExtHeaders_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[allowedIPv6ExtHeaders_node.text]
            ref_value.referenced_by.add(self)
            self.__allowedIPv6ExtHeaders = ref_value
        allowedTcpOptions_node = self._node.find('{*}ALLOWED-TCP-OPTIONS-REF')
        if allowedTcpOptions_node is not None and allowedTcpOptions_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[allowedTcpOptions_node.text]
            ref_value.referenced_by.add(self)
            self.__allowedTcpOptions = ref_value
        clientPort_node = self._node.find('{*}CLIENT-PORT-REF')
        if clientPort_node is not None and clientPort_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[clientPort_node.text]
