class DelegationSwConnector(SwConnector):
    """
    A delegation connector delegates one inner PortPrototype  (a port of a component that is used inside the composition) to a outer PortPrototype of compatible type that belongs directly to the composition (a port that is owned by the composition).
    """
    def __init__(self):
        super().__init__()
        self.tag = 'DELEGATION-SW-CONNECTOR'
        self.__innerPort = None
        self.__outerPort = None

    def _build(self, parent, node):
        super()._build(parent, node)
        innerPort_obj_dict = {}
        innerPort_obj_dict['P-PORT-IN-COMPOSITION-INSTANCE-REF'] = 'PPortInCompositionInstanceRef'
        innerPort_obj_dict['R-PORT-IN-COMPOSITION-INSTANCE-REF'] = 'RPortInCompositionInstanceRef'
        innerPort_node = self._node.find('{*}INNER-PORT-IREF/*')
        if innerPort_node is not None:
            self.__innerPort = __str_to_class__(innerPort_obj_dict[etree.QName(innerPort_node).localname])()._build(self, innerPort_node)

        return self

