class FMFeatureDecomposition(ARObject):
    """
    A FMFeatureDecomposition describes dependencies between a list of, features and their parent feature (i.e., the FMFeature that, aggregates the FMFeatureDecomposition). The kind of dependency is, defined by the attribute category.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'FM-FEATURE-DECOMPOSITION'
        self.__category = None
        self.__max = None
        self.__min = None
        self.__features = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        category_value = AutosarNode._get_node_text(node,'CATEGORY')
        if category_value is not None:
            self.__category = datatype_utils.get_string_value(category_value)

        max_value = AutosarNode._get_node_text(node,'MAX')
        if max_value is not None:
            self.__max = datatype_utils.get_int_value(max_value)

        min_value = AutosarNode._get_node_text(node,'MIN')
        if min_value is not None:
            self.__min = datatype_utils.get_int_value(min_value)

        return self

    def _resolve_references(self):
        features_nodes = self._node.findall('{*}FEATURE-REFS/*')
        for node in features_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__features.add(ref_value)

    def get_category(self):
        return self.__category

    def set_category(self, value):
        self.__category = value
        category_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'CATEGORY')
        category_xml_node.text = str(value) if value is not None else ''

    def get_max(self):
        return self.__max

    def set_max(self, value):
        self.__max = value
        max_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'MAX')
        max_xml_node.text = str(value) if value is not None else ''

    def get_min(self):
        return self.__min

    def set_min(self, value):
        self.__min = value
        min_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'MIN')
        min_xml_node.text = str(value) if value is not None else ''

    def get_features(self):
        return self.__features

    def add_feature(self, value):
        """
        Adds a single value to the features
        """
        if value is not None:
            if any(v.name == value.name for v in self.__features):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, FMFeature) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of FMFeature or its sub-classes'.format(value))
            self.__features.add(value)
            features_values = AutosarNode._add_or_get_xml_node(self._node, 'FEATURE-REFS')

            features_value = AutosarNode._add_or_get_xml_node(features_values, 'FEATURE-REF', value, forceCreate = True)
            features_value.text = value.path
            value.referenced_by.add(self)

    def set_features(self, values):
        """
        Adds a list of ref value to the features
        """
        for value in values:
            self.add_feature(value)

    def remove_feature(self, value):
        """
        Removes a single value from features
        """
        if value is not None:
            self.__features.remove(value)
            features_values = AutosarNode._add_or_get_xml_node(self._node, 'FEATURE-REFS', createNode = False)
            for features_value in self._node.findall('{*}FEATURE-REFS/*'):
                if features_value.text == value.path:
                    features_value.text = ''
                    features_values.remove(features_value)
                    value.referenced_by.remove(self)
                    break

    def remove_features(self, values):
        """
        Removes a list of value from features
        """
        for value in values:
            self.remove_feature(value)

    def _add_mandatory_attr(self, node, name = None):
        super()._add_mandatory_attr(node, name)
        category_node = etree.SubElement(node, 'CATEGORY')
        self.__category = None
        category_node.text = ''

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['Category'] = self.__category
        property_values['Max'] = self.__max
        property_values['Min'] = self.__min
        property_values['Features'] = self.__features
        return property_values

    def _update_path(self):
        """
        Updates the path of the FMFeatureDecomposition and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

