class SecuredIPdu(IPdu):
    """
    If useAsCryptographicPdu is not set or set to false this IPdu contains the payload of an Authentic IPdu supplemented by additional Authentication Information (Freshness Counter and an Authenticator)., , If useAsCryptographicPdu is set to true this IPdu contains the Authenticator for a payload that is transported in a separate message. The separate Authentic IPdu is described by the Pdu that is referenced with the payload reference from this SecuredIPdu.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'SECURED-I-PDU'
        self.__useAsCryptographicIPdu = None
        self.__useSecuredPduHeader = None
        self.__authenticationProps = None
        self.__freshnessProps = None
        self.__payload = None
        self.__secureCommunicationProps = None

    def _build(self, parent, node):
        super()._build(parent, node)
        useAsCryptographicIPdu_value = AutosarNode._get_node_text(node,'USE-AS-CRYPTOGRAPHIC-I-PDU')
        if useAsCryptographicIPdu_value is not None:
            self.__useAsCryptographicIPdu = datatype_utils.get_bool_value(useAsCryptographicIPdu_value)

        useSecuredPduHeader_value = AutosarNode._get_node_text(node,'USE-SECURED-PDU-HEADER')
        if useSecuredPduHeader_value is not None:
            self.__useSecuredPduHeader = SecuredPduHeaderEnum.get(useSecuredPduHeader_value)

        secureCommunicationProps_node = self._node.find('{*}SECURE-COMMUNICATION-PROPS')
        if secureCommunicationProps_node is not None:
            self.__secureCommunicationProps = SecureCommunicationProps()._build(self, secureCommunicationProps_node)

        return self

    def _resolve_references(self):
        authenticationProps_node = self._node.find('{*}AUTHENTICATION-PROPS-REF')
        if authenticationProps_node is not None and authenticationProps_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[authenticationProps_node.text]
            ref_value.referenced_by.add(self)
            self.__authenticationProps = ref_value
        freshnessProps_node = self._node.find('{*}FRESHNESS-PROPS-REF')
        if freshnessProps_node is not None and freshnessProps_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[freshnessProps_node.text]
            ref_value.referenced_by.add(self)
            self.__freshnessProps = ref_value
        payload_node = self._node.find('{*}PAYLOAD-REF')
        if payload_node is not None and payload_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[payload_node.text]
            ref_value.referenced_by.add(self)
            self.__payload = ref_value

    def get_useAsCryptographicIPdu(self):
        return self.__useAsCryptographicIPdu

    def set_useAsCryptographicIPdu(self, value):
        self.__useAsCryptographicIPdu = value
        useAsCryptographicIPdu_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'USE-AS-CRYPTOGRAPHIC-I-PDU')
        useAsCryptographicIPdu_xml_node.text = 'true' if value is True else 'false'

    def get_useSecuredPduHeader(self):
        return self.__useSecuredPduHeader

