class ImplementationElementInParameterInstanceRef(AtpInstanceRef):
    """
    Describes a reference to a particular ImplementationDataTypeElement instance in the context of a given ParameterDataPrototype., Thus it refers to a particular element in the implementation description of a software data structure., , Use Case:, The RTE generator publishes its generated structure of calibration parameters in its BSW module description using the "constantMemory" role of ParameterDataPrototypes. Each ParameterDataPrototype describes a group of single calibration parameters. In order to point to these single parameters, this "instance ref" is needed., , Note that this class follows the pattern of an InstanceRef but is not implemented based on the abstract classes because the ImplementationDataType isn't either, especially because ImplementationDataTypeElement isn't derived from AtpPrototype.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'IMPLEMENTATION-ELEMENT-IN-PARAMETER-INSTANCE-REF'
        self.__context = None
        self.__target = None


    def _resolve_references(self):
        context_node = self._node.find('{*}CONTEXT-REF')
        if context_node is not None and context_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[context_node.text]
            ref_value.referenced_by.add(self)
            self.__context = ref_value
        target_node = self._node.find('{*}TARGET-REF')
        if target_node is not None and target_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[target_node.text]
            ref_value.referenced_by.add(self)
            self.__target = ref_value

    def get_context(self):
        return self.__context

    def set_context(self, value):
        """
        Adds a single value to the context
        """
        if value is not None:
            if isinstance(value, ParameterDataPrototype) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ParameterDataPrototype or its sub-classes'.format(value))
            if self.__context is not None:
                self.__context.referenced_by.remove(self)
            context_value = AutosarNode._add_or_get_xml_node(self._node, 'CONTEXT-REF', value)
            context_value.text = value.path
            context_value.attrib['DEST'] = value.tag
            self.__context = value
            value.referenced_by.add(self)
        elif self.__context is not None:
            self.__context.referenced_by.remove(self)
            self.__context = None
            context_value = AutosarNode._add_or_get_xml_node(self._node, 'CONTEXT-REF', createNode = False)
            if context_value is not None:
                context_value.referenced_by.remove(self)
                context_value.text = ''

    def get_target(self):
        return self.__target

    def set_target(self, value):
        """
        Adds a single value to the target
        """
        if value is not None:
            if isinstance(value, ImplementationDataTypeElement) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ImplementationDataTypeElement or its sub-classes'.format(value))
            if self.__target is not None:
                self.__target.referenced_by.remove(self)
            target_value = AutosarNode._add_or_get_xml_node(self._node, 'TARGET-REF', value)
            target_value.text = value.path
            target_value.attrib['DEST'] = value.tag
            self.__target = value
            value.referenced_by.add(self)
        elif self.__target is not None:
            self.__target.referenced_by.remove(self)
            self.__target = None
            target_value = AutosarNode._add_or_get_xml_node(self._node, 'TARGET-REF', createNode = False)
            if target_value is not None:
                target_value.referenced_by.remove(self)
                target_value.text = ''

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['Context'] = self.__context
        property_values['Target'] = self.__target
        return property_values

    def _update_path(self):
        """
        Updates the path of the ImplementationElementInParameterInstanceRef and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

