class SystemSignalGroup(ARElement):
    """
    A signal group refers to a set of signals that shall always be kept together. A signal group is used to guarantee the atomic transfer of AUTOSAR composite data types.  , , The SystemSignalGroup defines a signal grouping on VFB level. On cluster level the Signal grouping is described by the ISignalGroup element.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'SYSTEM-SIGNAL-GROUP'
        self.__systemSignals = set()
        self.__transformingSystemSignal = None


    def _resolve_references(self):
        systemSignals_nodes = self._node.findall('{*}SYSTEM-SIGNAL-REFS/*')
        for node in systemSignals_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__systemSignals.add(ref_value)
        transformingSystemSignal_node = self._node.find('{*}TRANSFORMING-SYSTEM-SIGNAL-REF')
        if transformingSystemSignal_node is not None and transformingSystemSignal_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[transformingSystemSignal_node.text]
            ref_value.referenced_by.add(self)
            self.__transformingSystemSignal = ref_value

    def get_systemSignals(self):
        return self.__systemSignals

    def add_systemSignal(self, value):
        """
        Adds a single value to the systemSignals
        """
        if value is not None:
            if any(v.name == value.name for v in self.__systemSignals):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, SystemSignal) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of SystemSignal or its sub-classes'.format(value))
            self.__systemSignals.add(value)
            systemSignals_values = AutosarNode._add_or_get_xml_node(self._node, 'SYSTEM-SIGNAL-REFS')

            systemSignals_value = AutosarNode._add_or_get_xml_node(systemSignals_values, 'SYSTEM-SIGNAL-REF', value, forceCreate = True)
            systemSignals_value.text = value.path
            value.referenced_by.add(self)

    def set_systemSignals(self, values):
        """
        Adds a list of ref value to the systemSignals
        """
        for value in values:
            self.add_systemSignal(value)

    def remove_systemSignal(self, value):
        """
        Removes a single value from systemSignals
        """
        if value is not None:
            self.__systemSignals.remove(value)
            systemSignals_values = AutosarNode._add_or_get_xml_node(self._node, 'SYSTEM-SIGNAL-REFS', createNode = False)
            for systemSignals_value in self._node.findall('{*}SYSTEM-SIGNAL-REFS/*'):
                if systemSignals_value.text == value.path:
                    systemSignals_value.text = ''
                    systemSignals_values.remove(systemSignals_value)
                    value.referenced_by.remove(self)
                    break

    def remove_systemSignals(self, values):
        """
        Removes a list of value from systemSignals
        """
        for value in values:
            self.remove_systemSignal(value)

    def get_transformingSystemSignal(self):
        return self.__transformingSystemSignal

    def set_transformingSystemSignal(self, value):
        """
        Adds a single value to the transformingSystemSignal
        """
        if value is not None:
            if isinstance(value, SystemSignal) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of SystemSignal or its sub-classes'.format(value))
            if self.__transformingSystemSignal is not None:
                self.__transformingSystemSignal.referenced_by.remove(self)
            transformingSystemSignal_value = AutosarNode._add_or_get_xml_node(self._node, 'TRANSFORMING-SYSTEM-SIGNAL-REF', value)
            transformingSystemSignal_value.text = value.path
            transformingSystemSignal_value.attrib['DEST'] = value.tag
            self.__transformingSystemSignal = value
            value.referenced_by.add(self)
        elif self.__transformingSystemSignal is not None:
            self.__transformingSystemSignal.referenced_by.remove(self)
            self.__transformingSystemSignal = None
            transformingSystemSignal_value = AutosarNode._add_or_get_xml_node(self._node, 'TRANSFORMING-SYSTEM-SIGNAL-REF', createNode = False)
            if transformingSystemSignal_value is not None:
                transformingSystemSignal_value.referenced_by.remove(self)
                transformingSystemSignal_value.text = ''

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['SystemSignals'] = self.__systemSignals
        property_values['TransformingSystemSignal'] = self.__transformingSystemSignal
        return property_values

    def _update_path(self):
        """
        Updates the path of the SystemSignalGroup and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

