class FMFeatureModel(ARElement):
    """
    A Feature model describes the features of a product line and their dependencies. Feature models are an optional part of an AUTOSAR model.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'FM-FEATURE-MODEL'
        self.__features = set()
        self.__root = None


    def _resolve_references(self):
        features_nodes = self._node.findall('{*}FEATURE-REFS/*')
        for node in features_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__features.add(ref_value)
        root_node = self._node.find('{*}ROOT-REF')
        if root_node is not None and root_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[root_node.text]
            ref_value.referenced_by.add(self)
            self.__root = ref_value

    def get_features(self):
        return self.__features

    def add_feature(self, value):
        """
        Adds a single value to the features
        """
        if value is not None:
            if any(v.name == value.name for v in self.__features):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, FMFeature) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of FMFeature or its sub-classes'.format(value))
            self.__features.add(value)
            features_values = AutosarNode._add_or_get_xml_node(self._node, 'FEATURE-REFS')

            features_value = AutosarNode._add_or_get_xml_node(features_values, 'FEATURE-REF', value, forceCreate = True)
            features_value.text = value.path
            value.referenced_by.add(self)

    def set_features(self, values):
        """
        Adds a list of ref value to the features
        """
        for value in values:
            self.add_feature(value)

    def remove_feature(self, value):
        """
        Removes a single value from features
        """
        if value is not None:
            self.__features.remove(value)
            features_values = AutosarNode._add_or_get_xml_node(self._node, 'FEATURE-REFS', createNode = False)
            for features_value in self._node.findall('{*}FEATURE-REFS/*'):
                if features_value.text == value.path:
                    features_value.text = ''
                    features_values.remove(features_value)
                    value.referenced_by.remove(self)
                    break

    def remove_features(self, values):
        """
        Removes a list of value from features
        """
        for value in values:
            self.remove_feature(value)

    def get_root(self):
        return self.__root

    def set_root(self, value):
        """
        Adds a single value to the root
        """
        if value is not None:
            if isinstance(value, FMFeature) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of FMFeature or its sub-classes'.format(value))
            if self.__root is not None:
                self.__root.referenced_by.remove(self)
            root_value = AutosarNode._add_or_get_xml_node(self._node, 'ROOT-REF', value)
            root_value.text = value.path
            root_value.attrib['DEST'] = value.tag
            self.__root = value
            value.referenced_by.add(self)
        elif self.__root is not None:
            self.__root.referenced_by.remove(self)
            self.__root = None
            root_value = AutosarNode._add_or_get_xml_node(self._node, 'ROOT-REF', createNode = False)
            if root_value is not None:
                root_value.referenced_by.remove(self)
                root_value.text = ''

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['Features'] = self.__features
        property_values['Root'] = self.__root
        return property_values

    def _update_path(self):
        """
        Updates the path of the FMFeatureModel and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

