class Baseline(ARObject):
    """
    Specification of the baseline of the AUTOSAR standard this Data Exchange Point relates to. The baseline is specified by listing the AUTOSAR products and their revisions. Custom defined functionality and deviations to the standard can be provided as well. , All references to specification elements in this Data Exchange Point refer to specification elements that are part of this specification baseline.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'BASELINE'
        self.__standardRevisions = None
        self.__customSpecifications = set()
        self.__customSdgDefs = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        standardRevisions_value = AutosarNode._get_node_text(node,'STANDARD-REVISION')
        if standardRevisions_value is not None:
            self.__standardRevisions = datatype_utils.get_string_value(standardRevisions_value)

        return self

    def _resolve_references(self):
        customSpecifications_nodes = self._node.findall('{*}CUSTOM-SPECIFICATION-REFS/*')
        for node in customSpecifications_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__customSpecifications.add(ref_value)
        customSdgDefs_nodes = self._node.findall('{*}CUSTOM-SDG-DEF-REFS/*')
        for node in customSdgDefs_nodes:
            if node.text in __pathsToNodeDict__:
                ref_value = __pathsToNodeDict__[node.text]
                ref_value.referenced_by.add(self)
                self.__customSdgDefs.add(ref_value)

    def get_standardRevisions(self):
        return self.__standardRevisions

    def set_standardRevisions(self, value):
        self.__standardRevisions = value
        standardRevisions_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'STANDARD-REVISION')
        standardRevisions_xml_node.text = str(value) if value is not None else ''

    def get_customSpecifications(self):
        return self.__customSpecifications

    def add_customSpecification(self, value):
        """
        Adds a single value to the customSpecifications
        """
        if value is not None:
            if any(v.name == value.name for v in self.__customSpecifications):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, Documentation) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of Documentation or its sub-classes'.format(value))
            self.__customSpecifications.add(value)
            customSpecifications_values = AutosarNode._add_or_get_xml_node(self._node, 'CUSTOM-SPECIFICATION-REFS')

            customSpecifications_value = AutosarNode._add_or_get_xml_node(customSpecifications_values, 'CUSTOM-SPECIFICATION-REF', value, forceCreate = True)
            customSpecifications_value.text = value.path
            value.referenced_by.add(self)

    def set_customSpecifications(self, values):
        """
        Adds a list of ref value to the customSpecifications
        """
        for value in values:
            self.add_customSpecification(value)

    def remove_customSpecification(self, value):
        """
        Removes a single value from customSpecifications
        """
        if value is not None:
            self.__customSpecifications.remove(value)
