class SupervisedEntityNeeds(ServiceNeeds):
    """
    Specifies the abstract needs on the configuration of the Watchdog Manager for one specific Supervised Entity.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'SUPERVISED-ENTITY-NEEDS'
        self.__activateAtStart = None
        self.__enableDeactivation = None
        self.__expectedAliveCycle = None
        self.__maxAliveCycle = None
        self.__minAliveCycle = None
        self.__toleratedFailedCycles = None
        self.__checkpoints = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        activateAtStart_value = AutosarNode._get_node_text(node,'ACTIVATE-AT-START')
        if activateAtStart_value is not None:
            self.__activateAtStart = datatype_utils.get_bool_value(activateAtStart_value)

        enableDeactivation_value = AutosarNode._get_node_text(node,'ENABLE-DEACTIVATION')
        if enableDeactivation_value is not None:
            self.__enableDeactivation = datatype_utils.get_bool_value(enableDeactivation_value)

        expectedAliveCycle_value = AutosarNode._get_node_text(node,'EXPECTED-ALIVE-CYCLE')
        if expectedAliveCycle_value is not None:
            self.__expectedAliveCycle = datatype_utils.get_float_value(expectedAliveCycle_value)

        maxAliveCycle_value = AutosarNode._get_node_text(node,'MAX-ALIVE-CYCLE')
        if maxAliveCycle_value is not None:
            self.__maxAliveCycle = datatype_utils.get_float_value(maxAliveCycle_value)

        minAliveCycle_value = AutosarNode._get_node_text(node,'MIN-ALIVE-CYCLE')
        if minAliveCycle_value is not None:
            self.__minAliveCycle = datatype_utils.get_float_value(minAliveCycle_value)

        toleratedFailedCycles_value = AutosarNode._get_node_text(node,'TOLERATED-FAILED-CYCLES')
        if toleratedFailedCycles_value is not None:
            self.__toleratedFailedCycles = datatype_utils.get_int_value(toleratedFailedCycles_value)

        checkpoints_nodes = self._node.findall('{*}CHECKPOINTSS/*')
        for checkpoints_node in checkpoints_nodes:
            self.__checkpoints.add(SupervisedEntityCheckpointNeedsRefConditional()._build(self, checkpoints_node))

        return self

    def get_activateAtStart(self):
        return self.__activateAtStart

    def set_activateAtStart(self, value):
        self.__activateAtStart = value
        activateAtStart_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'ACTIVATE-AT-START')
        activateAtStart_xml_node.text = 'true' if value is True else 'false'

    def get_enableDeactivation(self):
        return self.__enableDeactivation

    def set_enableDeactivation(self, value):
        self.__enableDeactivation = value
        enableDeactivation_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'ENABLE-DEACTIVATION')
        enableDeactivation_xml_node.text = 'true' if value is True else 'false'

    def get_expectedAliveCycle(self):
        return self.__expectedAliveCycle

    def set_expectedAliveCycle(self, value):
        self.__expectedAliveCycle = value
        expectedAliveCycle_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'EXPECTED-ALIVE-CYCLE')
        expectedAliveCycle_xml_node.text = str(value) if value is not None else ''

    def get_maxAliveCycle(self):
        return self.__maxAliveCycle

    def set_maxAliveCycle(self, value):
        self.__maxAliveCycle = value
        maxAliveCycle_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'MAX-ALIVE-CYCLE')
        maxAliveCycle_xml_node.text = str(value) if value is not None else ''

    def get_minAliveCycle(self):
        return self.__minAliveCycle

    def set_minAliveCycle(self, value):
        self.__minAliveCycle = value
        minAliveCycle_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'MIN-ALIVE-CYCLE')
        minAliveCycle_xml_node.text = str(value) if value is not None else ''

    def get_toleratedFailedCycles(self):
        return self.__toleratedFailedCycles

    def set_toleratedFailedCycles(self, value):
        self.__toleratedFailedCycles = value
        toleratedFailedCycles_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'TOLERATED-FAILED-CYCLES')
        toleratedFailedCycles_xml_node.text = str(value) if value is not None else ''

    def get_checkpoints(self):
        return self.__checkpoints

    def add_checkpoint(self, value):
        """
        Adds a single value to the checkpoints
        """
        if value is not None:
            if any(v.name == value.name for v in self.__checkpoints):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, SupervisedEntityCheckpointNeedsRefConditional) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of SupervisedEntityCheckpointNeedsRefConditional or its sub-classes'.format(value))
            self.__checkpoints.add(value)
            checkpoints_values = AutosarNode._add_or_get_xml_node(self._node, 'CHECKPOINTSS')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            checkpoints_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_checkpoints(self, values):
        """
        Adds a list of ref value to the checkpoints
        """
        for value in values:
            self.add_checkpoint(value)

    def remove_checkpoint(self, value):
        """
        Removes a single value from checkpoints
        """
        if value is not None:
            self.__checkpoints.remove(value)
            checkpoints_values = AutosarNode._add_or_get_xml_node(self._node, 'CHECKPOINTSS', createNode = False)
            checkpoints_values.remove(value._node)
            value._parent = None #No parent
            value._update_path() #resets the path

    def remove_checkpoints(self, values):
        """
        Removes a list of value from checkpoints
        """
        for value in values:
            self.remove_checkpoint(value)

    def new_Checkpoint(self, name=None):
        """
        Creates a new SupervisedEntityCheckpointNeedsRefConditional under the SupervisedEntityNeeds.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        SupervisedEntityCheckpointNeedsRefConditional_obj = SupervisedEntityCheckpointNeedsRefConditional()
        if isinstance(SupervisedEntityCheckpointNeedsRefConditional_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('SUPERVISED-ENTITY-CHECKPOINT-NEEDS-REF-CONDITIONAL')
        SupervisedEntityCheckpointNeedsRefConditional_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        SupervisedEntityCheckpointNeedsRefConditional_obj.name = name
        SupervisedEntityCheckpointNeedsRefConditional_obj._node = xmlNode
        self.add_checkpoint(SupervisedEntityCheckpointNeedsRefConditional_obj)
        return SupervisedEntityCheckpointNeedsRefConditional_obj

    def get_children(self):
        children = super().get_children()
        children.extend(self.__checkpoints)
        return children

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['ActivateAtStart'] = self.__activateAtStart
        property_values['EnableDeactivation'] = self.__enableDeactivation
        property_values['ExpectedAliveCycle'] = self.__expectedAliveCycle
        property_values['MaxAliveCycle'] = self.__maxAliveCycle
        property_values['MinAliveCycle'] = self.__minAliveCycle
        property_values['ToleratedFailedCycles'] = self.__toleratedFailedCycles
        return property_values

    def _update_path(self):
        """
        Updates the path of the SupervisedEntityNeeds and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

