class DiagnosticStorageConditionGroup(DiagnosticConditionGroup):
    """
    Storage condition group which includes one or several storage conditions.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'DIAGNOSTIC-STORAGE-CONDITION-GROUP'
        self.__storageConditions = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        storageConditions_nodes = self._node.findall('{*}STORAGE-CONDITIONS/*')
        for storageConditions_node in storageConditions_nodes:
            self.__storageConditions.add(DiagnosticStorageConditionRefConditional()._build(self, storageConditions_node))

        return self

    def get_storageConditions(self):
        return self.__storageConditions

    def add_storageCondition(self, value):
        """
        Adds a single value to the storageConditions
        """
        if value is not None:
            if any(v.name == value.name for v in self.__storageConditions):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, DiagnosticStorageConditionRefConditional) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of DiagnosticStorageConditionRefConditional or its sub-classes'.format(value))
            self.__storageConditions.add(value)
            storageConditions_values = AutosarNode._add_or_get_xml_node(self._node, 'STORAGE-CONDITIONS')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            storageConditions_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_storageConditions(self, values):
        """
        Adds a list of ref value to the storageConditions
        """
        for value in values:
            self.add_storageCondition(value)

    def remove_storageCondition(self, value):
        """
        Removes a single value from storageConditions
        """
        if value is not None:
            self.__storageConditions.remove(value)
            storageConditions_values = AutosarNode._add_or_get_xml_node(self._node, 'STORAGE-CONDITIONS', createNode = False)
            storageConditions_values.remove(value._node)
            value._parent = None #No parent
            value._update_path() #resets the path

    def remove_storageConditions(self, values):
        """
        Removes a list of value from storageConditions
        """
        for value in values:
            self.remove_storageCondition(value)

    def new_StorageCondition(self, name=None):
        """
        Creates a new DiagnosticStorageConditionRefConditional under the DiagnosticStorageConditionGroup.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        DiagnosticStorageConditionRefConditional_obj = DiagnosticStorageConditionRefConditional()
        if isinstance(DiagnosticStorageConditionRefConditional_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('DIAGNOSTIC-STORAGE-CONDITION-REF-CONDITIONAL')
        DiagnosticStorageConditionRefConditional_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        DiagnosticStorageConditionRefConditional_obj.name = name
        DiagnosticStorageConditionRefConditional_obj._node = xmlNode
        self.add_storageCondition(DiagnosticStorageConditionRefConditional_obj)
        return DiagnosticStorageConditionRefConditional_obj

