class ComponentSeparation(MappingConstraint):
    """
    Constraint that forces the two referenced SW components (called A and B in the following) not to be mapped to the same ECU, Core, Partition depending on the defined mappingScope attribute. If mappingScope is not specified then mappingScopeEcu shall be assumed. , , If a SW component (e.g. A) is a composition, none of the atomic SW components making up the A composition shall be mapped together with any of the atomic SW components making up the B composition. Furthermore, A and B shall be disjoint.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'COMPONENT-SEPARATION'
        self.__mappingScope = None
        self.__separatedComponents = set()

    def _build(self, parent, node):
        super()._build(parent, node)
        mappingScope_value = AutosarNode._get_node_text(node,'MAPPING-SCOPE')
        if mappingScope_value is not None:
            self.__mappingScope = MappingScopeEnum.get(mappingScope_value)

        separatedComponents_nodes = self._node.findall('{*}SEPARATED-COMPONENT-IREFS/*')
        for separatedComponents_node in separatedComponents_nodes:
            self.__separatedComponents.add(ComponentInSystemInstanceRef()._build(self, separatedComponents_node))

        return self

    def get_mappingScope(self):
        return self.__mappingScope

    def set_mappingScope(self, value):
        self.__mappingScope = value
        mappingScope_xml_node = AutosarNode._add_or_get_xml_node(self._node, 'MAPPING-SCOPE')
        mappingScope_xml_node.text = value.literal if value is not None else ''

    def get_separatedComponents(self):
        return self.__separatedComponents

    def add_separatedComponent(self, value):
        """
        Adds a single value to the separatedComponents
        """
        if value is not None:
            if any(v.name == value.name for v in self.__separatedComponents):
                raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
            if isinstance(value, ComponentInSystemInstanceRef) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ComponentInSystemInstanceRef or its sub-classes'.format(value))
            self.__separatedComponents.add(value)
            separatedComponents_values = AutosarNode._add_or_get_xml_node(self._node, 'SEPARATED-COMPONENT-IREFS')

            # if value has a parent, then this node should be removed from the parents children.
            if value._parent is not None and value._parent._node is not self._node:
                value._parent.get_children().remove(value)
                value._parent._node.remove(value._node)

            separatedComponents_values.append(value._node)
            value._parent = self #assign the parent
            value._update_path() #updates the path

    def set_separatedComponents(self, values):
        """
        Adds a list of ref value to the separatedComponents
        """
        for value in values:
            self.add_separatedComponent(value)

    def remove_separatedComponent(self, value):
        """
        Removes a single value from separatedComponents
        """
        if value is not None:
            self.__separatedComponents.remove(value)
            separatedComponents_values = AutosarNode._add_or_get_xml_node(self._node, 'SEPARATED-COMPONENT-IREFS', createNode = False)
            separatedComponents_values.remove(value._node)
            value._parent = None #No parent
            value._update_path() #resets the path

    def remove_separatedComponents(self, values):
        """
        Removes a list of value from separatedComponents
        """
        for value in values:
            self.remove_separatedComponent(value)

    def new_SeparatedComponent(self, name=None):
        """
        Creates a new ComponentInSystemInstanceRef under the ComponentSeparation.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        ComponentInSystemInstanceRef_obj = ComponentInSystemInstanceRef()
        if isinstance(ComponentInSystemInstanceRef_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        xmlNode = etree.Element('SEPARATED-COMPONENT-IREF')
        ComponentInSystemInstanceRef_obj._add_mandatory_attr(xmlNode, name)#Add mandatory attributes.
        ComponentInSystemInstanceRef_obj.name = name
        ComponentInSystemInstanceRef_obj._node = xmlNode
        self.add_separatedComponent(ComponentInSystemInstanceRef_obj)
        return ComponentInSystemInstanceRef_obj

    def get_children(self):
        children = super().get_children()
        children.extend(self.__separatedComponents)
        return children

    def get_property_values(self):
        property_values = super().get_property_values()
        property_values['MappingScope'] = self.__mappingScope
        return property_values

    def _update_path(self):
        """
        Updates the path of the ComponentSeparation and its children.
        """
        self._build_path()
        super()._update_path() # updates any references from the super class
        for child in filter(None, self.get_children()):
            child._build_path()

