        cryptoKeySlot_node = self._node.find('{*}CRYPTO-KEY-SLOT-REF')
        if cryptoKeySlot_node is not None and cryptoKeySlot_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[cryptoKeySlot_node.text]
            ref_value.referenced_by.add(self)
            self.__cryptoKeySlot = ref_value
        persistencyDeployment_node = self._node.find('{*}PERSISTENCY-DEPLOYMENT-REF')
        if persistencyDeployment_node is not None and persistencyDeployment_node.text in __pathsToNodeDict__:
            ref_value = __pathsToNodeDict__[persistencyDeployment_node.text]
            ref_value.referenced_by.add(self)
